\title{Convolutional Neural Networks vs. Deformable Image Registration For Medical Slice Interpolation}

\author{\IEEEauthorblockN{Dilip Kumar Verma}
\IEEEauthorblockA{\textit{Applied Signal \& Image Processing (ASIP) Laboratory} \\
\textit{ College of Engineering and Computing Sciences} \\
\textit{New York Institute of Technology}\\
Old Westbury, NY \\}
\and
\IEEEauthorblockN{Ahmadreza Baghaie}%,~\IEEEmembership{Member,~IEEE}}
