    \centering
    \includegraphics[scale =1]{DTOneSide.pdf}
    \caption{Illustration of $T$ corresponding to a set $S= \{u_1,\ldots, u_k\}$. Here, for $i\in [k]$, $v_i$ is a test node with $f(v_i)=u_i$ and $\lambda(v_i) = 0$. Moreover, the right child $l_i$ of $v_i$ is a negative leaf, and the left child $l'$ of $v_k$ is a positive leaf.}
    \label{fig:oneSide}
\end{figure}


Let $B_i$, for $i\in \eta$, be a block of $E$, and $T$ be a \DT for $E$. Then, we say that a (dummy) test node $v$ of $T$ \textit{intersects} $B_i$ if $f(v) =d_0$ and $2(i-1)m+1 \leq \lambda(v) \leq 2im$.  Observe that a (dummy) test node can intersect at most one block $B_i$. Thus, $T$ can have at most $|T|$ many blocks that are intersected by some test, and hence at least $\eta -|T|$ (we assume that $\eta \geq |T|$) blocks of $E$ are not intersected by any test node of $T$. Let $l'$ be a leaf of a \DT $T$ for $\mathcal{E}$. Moreover, we say that a block $B_i$ is \textit{contained} in $l'$ if each positive example $e$ of $B_i$ is in $T_{E}(l')$, i.e., $T_{E}(l') \cap E^+ \cap B_i = B_i \cap E^+$. Finally, we have the following observation. 
\begin{observation}\label{O:hardness}
    If a block $B_i$ is not intersected by any test node of $T$, then $B_i$ is contained in some leaf of $T$. Thus, there are at least $\eta -|T|$ blocks of $E$ that are contained in some leaf of $T$.
\end{observation}
\begin{proof}
 Recall that any two distinct positive examples of $E$ differ in exactly one feature, which is $d_0$. Targeting contradiction, assume that there are two distinct positive examples $e$ and $e'$ of some block $B_i$ such that $B_i$ is not intersected by any test node and $e$ and $e'$ end up in different leaves. Hence, there exists at least one test node $v$ such that $f(v) = d_0$ and $\lambda(v)$ is such that either $e(d_0) \leq \lambda(v)$ and $e'(d_0) >\lambda(v)$ or  $e'(d_0) \leq \lambda(v)$ and $e(d_0) >\lambda(v)$. WLOG, let us assume that $e(d_0) \leq \lambda(v)<e'(d_0)$. Thus, by the construction of $E$, we have that $2(i-1)m+1 \leq \lambda(v) < 2im$, which in turn implies that the test node $v$ intersects $B_i$, a contradiction. The rest of the proof follows from the fact that at least $\eta -|T|$ blocks of $E$ are not intersected by any test node of $T$. 
\end{proof}

Let $T$ be a \DT for $E$. Moreover, let $B$ be a block of $E$ such that $B$ is contained in some leaf $l$ of $T$. Then, let $N(l,B)$ denote the set of negative examples of block $B$ that are in $T_E(l)$, i.e., $N(l,B) = \{B\cap E^-  \cap T_{E}(l) \}$. Next, we have the following lemma.

 \begin{lemma}\label{L:HI1}
        If $|N(l,B)| > \ell$ for each block $B$ such that $B$ is contained in some leaf $l$ of $T$, then $|O(T,E)|\geq  (\eta -|T|) (\ell+1)$.
    \end{lemma}
    \begin{proof}
        Consider a leaf $l$ of $T$ such that the block $B$ is contained in $l$. First, observe that the number of outliers the block $B$ contributes to the leaf $l$ is at least $N(l,B)$. This is trivial if $l$ is a positive leaf, and if $l$ is a negative leaf, then observe that $B\cap E^+  = m \geq |N(l,B)|$. Thus, $B$ contributes at least $|N(l,B)|$ many outliers to $O(T,E)$. Finally, since we have at least $\eta -|T|$ blocks such that each of these blocks is contained in some leaf, due to Observation~\ref{O:hardness}, and every such block $B$ contributes at least $|N(l,B)| \geq \ell+1$ outliers to $T$, we have that $|O(T,E)|\geq  (\eta -|T|) (\ell+1)$.
    \end{proof}

The following lemma  establishes that if there is some block $B$ of $E$ such that $B$ is contained in some leaf $l$ of $T$ and $|N(l,b)| \leq \ell$, then $G$ has a partial vertex cover of size at most $dep(T)$ that hits at least $p = m-\ell$ edges.
\begin{lemma}\label{L:HI2}
    Let $T$ be a \DT for $E$. If there exists some block $B$ of $E$ such that $B$ is contained in some leaf $l$ of $T$ and $|N(l,B)| \leq \ell$, then $(G,dep(T),p)$ is a Yes-instance of \textsc{PVC}.
\end{lemma}
\begin{proof}
    Let $v_0$ be the root of $T$. Consider the unique $(v_0,l)$-path $P$ in $T$. We claim that the the set $S = \{ f(v)~|~ v\in V(P)\} \setminus \{d_0\}$ is a partial vertex cover of $G$ that hits at least $p$ edges. Since $B$ is not intersected by any dummy test node (due to Observation~\ref{O:hardness}), each negative example of $B$ that is not in $T_E(l)$ is hit by some vertex feature on the path $P$. Since $|N(l,B)| \leq \ell$, the number of negative examples of $B$ hit by vertex test nodes in $P$ is at least $m-\ell$. Since each negative example in $B$ corresponds to a unique edge of $G$, the set $S$ hits at least $m-\ell = m- (m-p) = p$ edges of $E(G)$. This completes our proof.
\end{proof}


\subsection{W[1]-hardness proofs.} Now, we present our main lemmas. The following lemma completes our reduction for \DTSO. 
\begin{lemma}\label{L:DTSO}
    Let $\eta = s(\ell+2)$. Then, $(G,k,p)$ is a Yes-instance of \textsc{PVC} iff $(E,s,t)$ is a YES-instance of \DTSO.
\end{lemma}
\begin{proof}
    The proof of one direction follows from Lemma~\ref{L:Onesideboth}. 

    In the other direction, let $(E,s,t)$ be a YES-instance of \DTSO, and let $T$ be a \DT such that $|O(T,E)| \leq t  =\eta \ell = s\ell(\ell+2)$ and $|T| =s$. Due to Lemma~\ref{L:HI1}, if $|N(l,B)| >\ell$ for each block $B$ of $E$ such that $B$ is contained in some leaf of $T$, then $|O(T,E)| \geq (\eta -|T|)(\ell+1)$. Since $|T| =s$ and $\eta = s(\ell+2)$, $|O(T,E)| \geq  (s(\ell+2)-s)(\ell+1) = s(\ell+2-1)(\ell+1) = s(\ell+1)^2$. Since $s(\ell^2+2\ell+1) > s(\ell^2+2\ell)  = \ell \eta = t$, it contradicts the fact that $(E,s,t)$ is a YES-instance of \DTSO. Hence, there is at least one block $B$ of $E$ such that $B$ is contained in some leaf $l$ of $T$ and $|N(l,B)|\leq \ell$. Therefore, due to Lemma~\ref{L:HI2} and the fact that $dep(T) \leq s = k$, $(G,k,p)$ is a Yes-instance of \textsc{PVC}.
\end{proof}

Next, we have the following lemma that completes our reduction for \DTDO.

\begin{lemma}\label{L:DTDO}
Let $\eta = 2^d(\ell+2)$. Then, $(G,k,p)$ is a Yes-instance of \textsc{PVC} iff $(E,d,t)$ is a YES-instance of \DTDO.
\end{lemma}
\begin{proof}
    The proof of one direction follows from Lemma~\ref{L:Onesideboth}. 

    In the other direction, let $(E,d,t)$ be a YES-instance of \DTDO, and let $T$ be a \DT such that $|O(T,E)| \leq t =\eta \ell = 2^d(\ell+2) \ell$ and $dep(T) =d$. Since $T$ is a binary tree, observe that $|T| \leq 2^d$.  Now, due to Lemma~\ref{L:HI1}, if $|N(l,B)| >\ell$ for each block $B$ of $E$ such that $B$ is contained in some leaf $l$ of $T$, then $|O(T,E)| \geq (\eta -|T|)(\ell+1)$. Since $|T| \leq 2^d$ and $\eta = 2^d(\ell+2)$, $|O(T,E)| \geq  (2^d(\ell+2)-2^d)(\ell+1) = 2^d(\ell+1)^2$. Since $2^d(\ell^2+2\ell+1) > 2^d(\ell^2+2\ell)  = \ell \eta = t$, it contradicts the fact that $(E,d,t)$ is a YES-instance of \DTDO. Hence, there is at least one block $B$ of $E$ such that $B$ is contained in some leaf $l$ of $T$ and $|N(l,B)|\leq \ell$. Therefore, due to Lemma~\ref{L:HI2} and the fact that $dep(T) \leq d = k$, we have that $(G,k,p)$ is a Yes-instance of \textsc{PVC}.
\end{proof}


Finally, we have the following theorem.
\WHard*

\begin{proof}
    Recall that in our construction of \CI $E$ from an instance $(G,k,t)$, $\delta_{max} \leq 3$. Moreover, we have that $d = s = k$.  Hence, the proof follows from our construction, Lemmas~\ref{L:DTSO} and \ref{L:DTDO}, and Preposition~\ref{P:pvcHard}.
\end{proof}

\section{\textsc{FPT} algorithms for \DTSO and \DTDO}
In this section, we complement Theorem~\ref{th:Whard} by establishing that \DTSO and \DTDO are \FPT when parameterized by $s+\delta_{max}+t$ and $d+\delta_{max}+t$, respectively. In regard to previous literature, we consider the size of our \CI $E$ as $||E||=|E|\cdot(|F(E)|+1)\cdot \log D_{max}$.  Our \FPT algorithm extends the \FPT algorithms for \DTD and \DTS parameterized by $d+\delta_{max}$ and $s+\delta_{max}$ provided by Eiben et al.~\cite{eibenLargeDomain}. The algorithm of~\cite{eibenLargeDomain} builds upon the algorithm of Ordyniak and Szeider~\cite{ordyniak}. Our algorithm follows the steps of their algorithm, and to avoid repetition, we provide details only about the parts that are new and non-trivial.
One important component of both these algorithms is that we can enumerate all the minimal support sets of size $k$ in \FPT (parameterized by $k+\delta_{max}$) time. 

Let $T$ be a \DT that classifies $E$. Then, observe that $F(T)$ is a support set for $E$~\cite{ordyniak}. We extend this notion to our setting. Consider $E$ and a subset $S\subseteq F(E)$. Let $E_1,\ldots,E_p$ be a partition of examples in $E$ such that for $i\in [p]$, each example in $E_i$ agrees on every feature in $S$. Moreover, for each $E_i$, $i\in j$, let $E^+_i$ denote the set of positive examples in $E_i$ and $E^-_i$ denote the set of negative examples in $E_i$. Then, we say that $E_i$ has $\min\{|E^+_i| ,|E^-_i|\}$ outliers for $S$, and we denote it by $B(S,E_i) = \min\{|E^+_i| ,|E^-_i|\}$. Finally, we say that $S$ is a \textit{support set with} $B(S,E) = \sum_{i\in [p]}B(S,E_i)$ \textit{outliers} for $E$. Our first easy observation is the following.
\begin{observation}\label{L:supportOurs}
    Let $T$ be a \DT such that $|O(T,E)| \leq t$. Then, $B(F(T),E) \leq t$, that is, $F(T)$ has at most $t$ outliers for $E$.
\end{observation}

Ordyniak and Szeider~\cite{ordyniak} established that we can enumerate all mininal support sets of size at most $k$ in time \FPT in $\delta_{max}$ and $k$. 
\begin{lemma}[\cite{ordyniak}]\label{L:enumerate}
    Let $E$ be a \CI and $k$ be an integer. Then, there is an algorithm that in time $\mathcal{O}(\delta_{max}^k |E|)$ enumerates all (of the at most $\delta_{max}^k$) minimal support sets of size at most $k$ for $E$.
\end{lemma}
We adapt Lemma~\ref{L:enumerate} to our setting in the following manner. We remark that this part is the most non-trivial extension and the rest of the proof roughly follows the algorithm from~\cite{eibenLargeDomain} with the only change being that instead of checking if $T$ classifies $E$, we check if $|O(T,E)|\leq t$.
\begin{lemma}\label{L:enumerateOurs}
    Let $E$ be a \CI and $k$ be an integer. Then, there is an algorithm that enumerates all (of the at most $\delta_{max}^k(t+1)^{2k}$) minimal  support sets allowing at most $t$ outliers for $E$ and of size at most $k$ in time $\mathcal{O}((\delta_{max}+2)^{k+t})|E|^{\mathcal{O}(1)}$.   
\end{lemma}
\begin{proof}
    We have the following branching-based algorithm. We keep two sets $S$ and $O$, representing the solution set and the set of outliers, respectively. Initially, we set $S=\emptyset$ and $O=\emptyset$. When $|S|>k$ or $|O|>t$, we backtrack. Else, if $B(S,E)\leq t$, then we report $S$ and backtrack. Else, pick some $\mathsf{p}\in E^+\setminus O$ and $\mathsf{n} \in E^-\setminus O$ such that $S$ does not distinguish $\mathsf{p}$ and $\mathsf{n}$; consider $\delta(\mathsf{p},\mathsf{n})+2$ branches: for each feature $f\in \delta(\mathsf{p},\mathsf{n})$, consider a branch where $S=S\cup \{f\}$, and consider two additional branches where in one add $\mathsf{p}$ to $O$ and in the other add $\mathsf{n}$ to $\mathsf{O}$. Validity of our algorithm follows as for any $\mathsf{p}\in E^+$ and  $\mathsf{n} \in E^-$, either at least one feature of $\delta_{max}$ should be in (the final) $S$ or at least one of $\mathsf{n}$ and $\mathsf{p}$ should contribute to $B(S,E)$. 
    Each branching step has at most $\delta_{max}+2$ branches, and the branching tree has at most $k+t$ depth. So, the number of leaves in our branching tree is at most  $(\delta_{max}+2)^{k+t}$. Since each branch can be implemented in poly-time, the algorithm takes  $\mathcal{O}((\delta_{max}+2)^{k+t})|E|^{\mathcal{O}(1)}$ time in total. 
\end{proof}

\Cref{L:enumerateOurs} establishes that we can enumerate all minimal support sets of size at most $k$ that allow at most $t$ outliers in \FPT (parameterized by $k+\delta_{max}+t$) time. Then, the remaining ingredient of our algorithm is the notion of maintaining $t$ outliers in each of their (\cite{ordyniak} and ~\cite{eibenLargeDomain}) definitions.  Moreover, in each check, instead of checking if $T$ is a valid \DT for $E$, we check if $|O(T,E)| \leq t$, which increases the dependency on the running time of their procedures by time \FPT in $t$. To avoid repetition, we use some of the terms from their paper in the sketch below without explicitly defining them. Hence, following their algorithm, we can first enumerate all minimal support sets of size at most $k$ ($k=s$ for \DTSO and $k=2^d$ for \DTDO) that allow at most $t$ outliers. Then, for each such support set $S$, we build all possible \DT \textit{patterns} $T$ such that $F(T) = S\cup \{\blacksquare\}$ of size at most $s$ (resp., $2^d$) for \DTSO (resp., \DTDO). Then, for each of these \DT patterns, we compute the \textit{branching sets} $(S,|T|)$. Finally, for each subset $S'$ of $(S,|T|)$ \textit{branching set} we construct the minimum sized (resp., minimum depth) \DT $T'$ with feature set $S' \cup F(T)$. Finally, we have the following theorem.



