                \displaystyle \frac{(2^{s_b} - 1)\cdot(2^{r_a} + 2^{s_a} - 1)}{2^{m_2 - 1}} & \text{ , if }\tau \in R_b\\
                \displaystyle \frac{(2^{r_a} - 1)\cdot(2^{r_b} + 2^{s_b} - 1)}{2^{m_2 - 1}} & \text{ , if }\tau \in S_a\\
                \displaystyle \frac{(2^{r_b} - 1)\cdot(2^{r_a} + 2^{s_a} - 1)}{2^{m_2 - 1}} & \text{ , if }\tau \in S_b\\
            \end{cases}
        \]

