\begin{eqnarray*}
p^{-\tau_3}(W_i) &=& \sum_{W^\prime \in \mc{W}: \  W^\prime \smallsetminus \{\tau_3\} = W_i} p(W^\prime) = 0, \ \ \  i=,\ldots,3. \\
p^{-\tau_3}(W_4) &=& \sum_{W^\prime \in \mc{W}: \ W^\prime \smallsetminus \{\tau_3\} = W_4} p(W^\prime) = p(W_3) + p(W_4) =  0.55.\\
