    \section{Proofs of Results}\label{sec:appendix}

    \noindent {\bf Proof of Proposition \ref{prop:world_q-separable}. \ }
        We prove this by contradiction. Assume $\mc{Q}[W] = 1$ and $\mc{Q}[W_i] = 0$ for $i=1,\ldots,s$. It follows that there exists some $W^\star \in \nit{MSS}(D,\mc{Q})$, such  that $W^\star \subseteq W$, Furthermore, since $D$ is $\mc{Q}$-separable, there exists some value $k \in \{1,\ldots,s\}$ such $W^\star \in \nit{MSS}(D_k,\mc{Q})$. If this is true, then $\mc{Q}[W_k] = 1$, which is a contradiction. \boxtheorem

\vspace{2mm}
    \noindent {\bf Proof of Proposition \ref{prop:scores_q-separable}. \ } Let $\mc{Q}$ be a MBQ, $D$ a $\mc{Q}$-separable database instance with partition $(D_1,\ldots,D_s)$ and $\tau \in D_k$. We first prove the proposition for {\sf Resp}. By definition, {\sf Resp} for tuple $\tau$ is:
        \[
        \rho(D,\mc{Q},\tau) = \left(1 + \min_{_{\Gamma \in \mbox{\scriptsize \nit{Cont}}(D,\mc{Q},\tau)}} |\Gamma| \right)^{\!\!-1}.
        \]
        Notice that, by Proposition \ref{prop:world_q-separable}, each $\Gamma \in \nit{Cont}(D,\mc{Q},\tau)$ can be written as $\Gamma = \Gamma^\prime \cup \Gamma^\star$, where $\Gamma^\prime \in \nit{Cont}(D_k,\mc{Q},\tau)$, $\Gamma^\star \subseteq (D \smallsetminus D_k)$ and $\Gamma^\prime \cap \Gamma^\star = \emptyset$. Now, since the minimum size $\Gamma$ is required, $\Gamma^\prime$ and $\Gamma^\star$ must have minimum cardinality. This is achieved by minimizing both sets: (a) for $\Gamma^\prime$, $\min_{\Gamma^\prime \in \nit{Cont}(D_k,\mc{Q},\tau)} |\Gamma^\prime|$, and (b) for $\Gamma^\star$, $\min_{\Gamma^\star \subseteq D \smallsetminus D_k} |\Gamma^\star| = \min\{|\Delta| ~:~ \Delta \subseteq (D \smallsetminus D_k) \text{ and } \mc{Q}[D \smallsetminus \Delta] = 0\} = r(D \smallsetminus D_k)$. By algebraic manipulation, the result from the proposition is obtained:
        \begin{align*}
            \rho(D,\mc{Q},\tau) & = \frac{1}{\displaystyle 1 + \min_{\Gamma^\prime \in \nit{Cont}(D_k,\mc{Q},\tau)} |\Gamma^\prime| + r(D \smallsetminus D_k)}, \\
            & = \frac{1}{\dfrac{1}{\rho(D_k,\mc{Q},\tau)} + r(D \smallsetminus D_k)}, \\
            & = \frac{\rho(D_k,\mc{Q},\tau)}{1 + \rho(D_k,\mc{Q},\tau) \times r(D \smallsetminus D_k)}.
        \end{align*}


        Now we prove the proposition for {\sf CES}. Since $D$ is $\mc{Q}$- separable, we can compute each probability according to Equation (\ref{eq:indep_probability}), as:
        \[
        P_D(\mc{Q} | \nit{do}(\cdot)) \ = \ 1 \ - \prod_{i = 1,\ldots,s} (1 - P_{D_i}(\mc{Q}  ~|~ \nit{do}(.))),
        \]
        where $\nit{do}(.)$ is replaced by $\nit{do}(\tau \In)$ and $\nit{do}(\tau \Out)$. Since instance $D_i$, with $i \neq k$, does not contain $\tau$, \ $P_{D_i}(\mc{Q} | do(\tau \In)) = P_{D_i}(\mc{Q} | do(\tau \Out)) = P_{D_i}(\mc{Q})$. Then, by simply algebraic manipulation, the following is obtained:
        \begin{align*}
            \nit{CE}(D,\mc{Q},\tau) & = P_D(\mc{Q}~|~ \nit(do)(\tau \In)) - P_D(\mc{Q}~|~ \nit(do)(\tau \Out)) \\
            & = \left(1 - \prod_{i=1,\ldots,s} \left(1 - P_{D_i}(\mc{Q} ~|~ \nit{do}(\tau \In))\right) \right)  \\
            & ~~~~~~ - \left(1 - \prod_{i=1,\ldots,s} \left(1 - P_{D_i}(\mc{Q} ~|~ \nit{do}(\tau \In))\right) \right) \\
            & = P_{D_k}(\mc{Q} ~|~ \nit{do}(\tau \In)) \times \left(1 - \prod_{i\neq k} \left(1 - P_{D_i}(\mc{Q})\right) \right) \\
            & ~~~~~~ - P_{D_k}(\mc{Q} ~|~ \nit{do}(\tau \Out)) \times \left(1 - \prod_{i\neq k} \left(1 - P_{D_i}(\mc{Q})\right) \right) \\
            & = \nit{CE}(D_k,\mc{Q},\tau)\times \left(1 - \prod_{i\neq k} \left(1 - P_{D_i}(\mc{Q})\right) \right). \hspace{2.5cm}\blacksquare
        \end{align*}

        \noindent {\bf Proof of Proposition \ref{prop:dummy}. \ }
        The proof for (a) is trivial, since, as the tuple $\tau_d$ does not change the value of the query, it does not belong to any contingency set of $\tau$ for the answer of $\mc{Q}$. Therefore, the {\sf Resp} score stays  the same with or without $\tau_d$.

        For (b), we can compute the CES for a given tuple using the definition of the {\sf BPI}. \
        Notice that, for each $S \subseteq (D \smallsetminus \{\tau_d\})$, $\Delta(\mc{Q},S,\tau) = 1$ iff $\Delta(\mc{Q},S \cup \{\tau_d\},\tau) = 1$. Therefore, adding the tuple $\tau_d$ to $D \smallsetminus \{\tau_d\}$, the number of $\Delta(\mc{Q},S \cup \{\tau_d\},\tau)$, which are equal to one, is doubled. This change is countered by the increasing in the number of endogenous tuples by one, leaving the CES unchanged for all endogenous tuples.

        For (c), we recall a property of Shapley Value in relation with dummy tuples: for a given BCQ $\mc{Q}$ and an instance $D$, if $\tau$ is a dummy tuple, then $\nit{Shapley}(D,\mc{Q},\tau) = 0$ \cite{shapley1953original}. It follows that, if we remove the tuples from the instance, the Shapley value does not change. \boxtheorem

\vspace{2mm}
        \noindent {\bf Proof of Proposition \ref{proposition:ces_resp_1}. \ } Consider the BCQ $\mc{Q}_{R_n}$, and an instance $D$ without dummy tuples (according to Proposition \ref{prop:dummy}). For a given constant $c$, $D$ must contain all tuples of the form $R_i(c)$, with $i =
        1,\ldots,n$. \
        By the structure of $D$, it is clear that is $\mc{Q}_{R_n}$-separable with partition $\{D_1,\ldots,D_s\}$, where each $D_j$, for $j\in\{1,\ldots,s\}$, is the collection of tuples of all relations with the same constant. \
       All the $R_i$ in $D$ have the same number of tuples, say $r$. \ \
        Two cases arise:
        \begin{enumerate}[(i)]
            \item There is a subinstance $D_x$ with $x \in \{1,\ldots,s\}$ where all tuples are exogenous. Then,  for every $\tau_x \in D_x$, $\tau \in D^\nit{ex}$. It follows that $\rho(D,\mc{Q}_{R_n},\tau) = \nit{CE}(D,\mc{Q}_{R_n},\tau) = 0$, for all remaining tuples $\tau \in D^\nit{en}$, because $\mc{Q}_{R_n}[D_x] = 1$. Thus, the scores are aligned.
            \item There is no subinstance with the previous condition. If this is the case, $\rho(D,\mc{Q},\tau) = \frac{1}{1 + r}$ for any $\tau \in D^\nit{en}$. Since {\sf Resp} is constant, it follows that the scores are aligned.{\boxtheorem}
        \end{enumerate}

\noindent {\bf Proof of Proposition \ref{proposition:ces_resp_2}. \ }  Let $x,y \in \nit{Var}(\mc{Q})$, such that $\nit{Atoms}(y) \subsetneqq \nit{Atoms}(x)$. Now, select two atoms $R_x,R_y$ from $\nit{Atoms}(\mc{Q})$, such that $R_x \in (\nit{Atoms}(x) \smallsetminus \nit{Atoms}(y))$ and $R_y \in \nit{Atoms}(y)$.\
        We build an instance $D$ from instance $D_2$ in Example \ref{ex:counter_q2}, as follows:

        \vspace{1mm} \noindent (a) For each atom $U_R \in \nit{Atoms}(y)$ and for each tuple $\tau_R$ from the relation $R$ of $D_2$, we create a tuple from $U_R$ by putting in the $x$ and $y$'s position the value of $x$ and $y$ in the tuple $\tau_S$, and replacing by a constant $c^\prime$ the rest of variables. Only the tuples created from $R_y$ are endogenous.

        \vspace{1mm} \noindent (b) For each atom $U_S \in (\nit{Atoms}(x) \smallsetminus \nit{Atoms}(y))$ and for each tuple $\tau_S$ from the relation $S$ of $D_2$, we create a tuple from $U_S$ by putting in the $x$ and $y$'s position the value of $x$'s position the value of $x$ in the tuple $\tau_R$, and replacing by a constant $c^\prime$ the rest of variables. Only the tuples created from $R_x$ are endogenous, with exception of the tuple with a constant $a$ in the position of $x$, which will be exogenous.

        \vspace{1mm} \noindent (c) For each atom $U \not\in \nit{Atoms}(x)$, a tuple is created by replacing all variables in $U$ with a constant $c^\prime$. All tuples created in this way will be exogenous.

        It follows that {\sf CES} and {\sf Resp} are not aligned for $(\mc{Q},D)$. \boxtheorem

\vspace{2mm}
   \noindent {\bf Proof of Proposition \ref{prop:coinc}. \ }
        Let $\mc{Q}$, $\mc{Q}^\prime$, $D$ and $D^\prime$ as in the statement of Proposition \ref{prop:coinc}. We refer to them as \emph{original} and \emph{target}, query or database, resp. Denote with $x,y$ the coincident variables, and with $v \not\in \nit{Var}(\mc{Q})$ the new variable.

        Now $D^\prime$ is built, according to $\mc{Q}^\prime$, in the following way: (1) First, add all tuples from $D$ that are not from the relations of the atoms in $\nit{Atoms}(x)$. (2) Then, for each atom $U \in \nit{Atoms}(\mc{Q})$, introduce a fresh atom $U^\prime$, whose  predicate's arity is that of the predicate of $U$ minus 1, and it has the same variables as the atom $U$, but $x$ and $y$, which are replaced by a single variable $v$.
        (3) Finally, for each tuple $\tau$ from the relations of the atoms in $\nit{Atoms}(\mc{Q})$, create the tuple $\tau^\prime$ according to the following:
       \begin{itemize}
           \item[(a)] Start from the new atom $U^\prime$, and replace each variable in it, but $v$, with the constant found in its position in the atom $U$ from the tuple $\tau$.
           \item[(b)] Replace the variable $v$ in $U^\prime$ with a unique fresh constant for each unique combination of constants of $\tau$ in the $x$ and $y$'s position in  atom $U$.
       \end{itemize}



    Now, consider the transformation $f: D \to D^\prime$: \ For a tuple $\tau \in D$,
        \[
        f(\tau) \ := \ \begin{cases}
            \tau^\prime &,\text{ if $\tau$ as a ground atom has the same predicate as some} \ U \in \nit{Atoms}(x),\\
            \tau &, \text{ otherwise. }
        \end{cases}
        \]
       Here, $\tau^\prime$ is newly created tuple starting from $\tau$.

        By applying this transformation, any homomorphism that maps the atom $U$ to the tuple $\tau$ has its corresponding unique homomorphism $h^\prime$ that maps  the new atom $U^\prime$ to the corresponding tuple $f(\tau)$.

        We need to prove that $\mc{Q}[S] = \mc{Q}^\prime[S^\prime]$, for every $S \subseteq D$, and $S^\prime = \{f(\tau) : \tau \in S\}$. We do this by showing that every tuple $\tau$ is mapped to a unique tuple in $\tau^\prime$, which is equivalent to showing that $f$ is bijective.

        Consider two tuples $\tau,\tau^\prime \in D$. If $(a,b)$ and $(a^\prime,b^\prime)$ are pairs of constants in the positions of $x$ and $y$ for $\tau$ and $\tau^\prime$, respectively, $f(\tau) = f(\tau^\prime)$ only if $\tau = \tau^\prime$, which means that $f$ is injective. This occurs even when $\tau$ is not from a relation appearing in  $\nit{Atoms}(x)$, because $f(\tau) = \tau$ in this case. \
        Furthermore, by the way $D^\prime$ is created, every tuple in it will have its correspondent tuple in $D$, implying that $f$ is surjective. Then, $f$ is a bijection.

        Since $\mc{Q}[S] = \mc{Q}^\prime[S^\prime]$, for every $S \subseteq D$, the bijection also holds with a non-empty set of exogenous tuples, because each subset of the original (and of the target) instance now needs to contain $D^\nit{ex}$ ($D^{\prime^\nit{ex}}$, resp.). {\boxtheorem}

\vspace{2mm}
\noindent {\bf Proof of Proposition \ref{lemma:coin_var}. \ }
        Appealing to Proposition \ref{prop:coinc}, let $f^\nit{red}$ be the transformation function that outputs $D^\nit{red}$. Since $\mc{Q}[S] = \mc{Q}^\nit{red}[S^\nit{red}]$, for every $S \subseteq D$, and $S^\nit{red} = \{f^\nit{red}(\tau) : \tau \in S\}$, it follows that, for every $\tau \in D^\nit{en}$, \  $\nit{CE}(D,\mc{Q},\tau) = \nit{CE}(D^\nit{red},\mc{Q}^\nit{red},f_R(\tau))$ and $\rho(D,\mc{Q},\tau) = \rho(D^\nit{red},\mc{Q}^\nit{red},f^\nit{red}(\tau))$. \ Then, {\sf CES} and {\sf Resp} are aligned for $(\mc{Q},D)$ iff they are aligned for $(\mc{Q}^\nit{red},D^\nit{red})$.\boxtheorem

\vspace{2mm}
\noindent {\bf Proof of Proposition \ref{prop:multicomp_pos}. \ }
        Consider $\mc{Q}_n\!: \ \exists x_1 \cdots \exists x_n(R_1(x_1) \land \ldots R_n(x_n))$, and an instance $D$. \  $\mc{Q}_n$ has $n$ components, and it is the reduced version of any query with more that one component, with one atom each. Denote with $r_i$ the number of tuples in relation $R_i$ of $D$. Consider $\mc{Q}_i\!: \ \exists x_i (R_i(x_i))$, for  $i = 1,\ldots,n$.  \ {\sf Resp} and {\sf CES} for an endogenous tuple $\tau \in D^\nit{en}$ from  $R_i$, with no exogenous tuples, are given by:
        $$\rho(D,\mc{Q},\tau) = \frac{1}{r_i}, \ \ \ \ \ \ \mbox{and}  \ \ \ \ \
            \nit{CE}(D,\mc{Q},\tau) = \frac{2}{2^{r_i} - 1} \cdot \prod_{i=1,\ldots,n} P(\mc{Q}_1).$$
        Furthermore, $\rho(D,\mc{Q},\tau) =  \nit{CE}(D,\mc{Q},\tau) = 0$ if $R_i$ has exogenous tuples. \
        Notice that: (1) for  {\sf CES}, the product $\prod_{i=1,\ldots,n }P(\mc{Q}_i)$ is constant for all tuples, and (2) all tuples from the same relation will have the same {\sf Resp} and {\sf CES}. \\

        Now, consider two endogenous tuples from any two different relations, say $\tau_j$ and $\tau_k$ from $R_j$ and $R_k$, respectively. Then, the following two cases arise:
        \begin{enumerate}[(i.)]
            \item No exogenous tuples exists from relations $R_i$ and $R_j$. It follows that $r_i \leq r_j$ iff $\rho(D,\mc{Q},\tau_i) \geq \rho(D,\mc{Q},\tau_j)$ iff $\nit{CE}(D,\mc{Q},\tau_i) \geq \nit{CE}(D,\mc{Q},\tau_j)$.
            \item There exists an exogenous tuple in relation $R_i$ and/or $R_j$. If this is the case, one or both tuples will have score $0$.
        \end{enumerate}
        Then, by Proposition \ref{lemma:coin_var}, since the scores are aligned for $\mc{Q}_{n}$ for any instance, the scores are aligned for any BCQ with $n$ components, where each component has a single atom. \boxtheorem

\vspace{2mm}
        \noindent {\bf Proof of Proposition \ref{prop:q_2comp}. \ }
        First, consider two components, $C_1$ and $C_2$, from the query, such that $|C_2| \geq 2$.
\ From $C_1$ select one atom, denoted with $A_R$. It will be assumed that $A_R \in \nit{Atoms}(x)$. Similarly, from $C_2$ select two atoms, $A_S$ and $A_T$, such that, for a variable $y$, $A_S, A_T \in \nit{Atoms}(y)$.

We build an instance $D$ from $D^\star$ in Example \ref{ex:counter_q_2comp},  as follows:

        \vspace{1mm} \noindent (a) For each atom $U_x \in \nit{Atoms}(x)$ and for each tuple $\tau_R$ from the relation $R$ of $D^\star$, we create a tuple from $U_R$ by putting in the $x$'s position the value of $x$ in the tuple $\tau_R$, and replacing by a constant $c^\prime$ the rest of variables. Only the tuples created from $A_R$ are endogenous.

        \vspace{1mm} \noindent (b) For each atom $U_S,U_T \in \nit{Atoms}(y)$ and for each tuple $\tau_S$ and $\tau_T$ from the relations $S$ and $T$ of $D^\star$, we create a tuple from $U_S$ and $U_T$ by putting in the $y$'s position the value of $y$ in the tuple $\tau_S$ and $\tau_T$, respectively, and replacing by a constant $c^\prime$ the rest of variables. Only the tuples created from $A_S$ and $A_T$ are endogenous, the rest will be exogenous.

        \vspace{1mm} \noindent (c) For each atom $U \not \in (\nit{Atoms}(x) \cup \nit{Atoms}(y))$,  a tuple is created by replacing all variables in $U$ with a constant $c^\prime$. All tuples created in this way will be exogenous.

        By construction of $D$,  each endogenous tuple in it has its corresponding tuple in $D^\star$, and  {\sf CES} and {\sf Resp} of each are the same as in $D^\star$. It follows that both scores are not aligned for $(\mc{Q},D)$. {\boxtheorem}

    \vspace{2mm}
  \noindent {\bf Proof of Theorem \ref{theo:ces_resp_aligned}.} \
        Consider a BCQ with a single component $\mc{Q}$ and its reduced version $\mc{Q}^\nit{red}$. \ Since $|\nit{Coin}(\mc{Q})| = |\nit{Var}(\mc{Q}^\nit{red})|$, Propositions \ref{proposition:ces_resp_1} and  \ref{proposition:ces_resp_2} apply to $\mc{Q}^\nit{red}$. \ By Proposition \ref{lemma:coin_var}, they  also apply to $\mc{Q}$. It follows that, if $\mc{Q}$ has a single component, then the claim of the theorem holds.

        Now, for a query $\mc{Q}$ with at least two components, Proposition \ref{prop:multicomp_pos} and Proposition \ref{prop:q_2comp} hold. It follows that, if $\mc{Q}$ has more than one component, the claim of Theorem \ref{theo:ces_resp_aligned} holds. \boxtheorem

\vspace{2mm}
     \noindent {\bf Proof of Corollary \ref{coro:multi_single_alignment}. \ }
        Assume that {\sf CES} and {\sf Resp} are aligned for $(\mc{Q},D)$, where $D$ is an arbitrary instance. \ By Propositions \ref{prop:multicomp_pos} and \ref{prop:q_2comp}, all the components of $\mc{Q}$ have a single atom.

        By Proposition \ref{lemma:coin_var}, the two scores are aligned for a single-atom query $\mc{Q}_i$  iff they are aligned for its reduced version $\mc{Q}^\nit{red}_i$, which is a single-atom and single-variable query. \ By Proposition \ref{proposition:ces_resp_1}, the scores are aligned for each query $\mc{Q}^\nit{red}_i$, which proves the statement. {\boxtheorem}


\vspace{1mm}
    \noindent {\bf Proof of Proposition \ref{prop:ces_resp_2_noex}. \ }
        The case $|\nit{Atoms}(\mc{Q})| = 1$ is included  in Proposition \ref{proposition:ces_resp_1}.\
        We first consider a query $\mc{Q}$ with a single component and without non-trivial sets of coincident variables. We will extend the result for such a query using Proposition \ref{lemma:coin_var}.

        Consider the case $|\nit{Atoms}(\mc{Q})| = 2$, and $|\nit{Var}(\mc{Q})| = 2$ or $3$. We proceed by showing that  {\sf CES} and {\sf Resp} are aligned for any pair $(\mc{Q}_{\sf RS},D)$, where $D$ is an instance with or without exogenous tuples, and $\mc{Q}_{\sf RS}$ (also used in Example \ref{ex:comp_ces_shapley}) is the following query:
        \begin{equation}
            \mc{Q}_{\sf RS}\!: \  \exists x \exists y \exists z(R(x,y) \land S(x,z)),
        \end{equation}
        Notice that $|\nit{Atoms}(\mc{Q}_{\sf RS})| = 2$, and $|\nit{Var}(\mc{Q}_{\sf RS})| = 3$. Moreover, if  {\sf CES} and {\sf Resp} are aligned for this case, the scores will be also aligned for a query $\mc{Q}^\prime$, such that $|\nit{Atoms}(\mc{Q}^\prime)| = 2$ and $|\nit{Var}(\mc{Q}^\prime)| = 2$.

        Consider an  instance $D$ without dummy tuples. Then, two scenarios arise:

        \noindent (1) All tuples in $D$ share the same constant in the $x$'s position of the atoms in $\mc{Q}_{\sf RS}$; or

        \noindent (2) $D$ contains at least two tuples where the constants in the $x$'s position of each tuple are different.

        We first consider case (1). Let $\tau_R$ ($r$) and $\tau_S$ ($s$) be a tuple (number of tuples) from (in) relations $R$ and $S$, respectively. Notice that all tuples $\tau_R$ have the same score ({\sf Resp} and {\sf CES}). The same holds for all tuples $\tau_S$. This implies that obtaining the alignment only requires comparing the relative ordering of $\tau_R$ and $\tau_S$. We now compute {\sf Resp} and {\sf CES} for each tuple:
        \begin{align*}
            \rho(D,\mc{Q}_{\sf RS},\tau_{R}) &= \frac{1}{r}, \\
            \nit{CE}(D,\mc{Q}_{\sf RS},\tau_{R}) &= P_D(\mc{Q}_{\sf RS}) \times \frac{2}{2^r - 1}, \\
            \rho(D,\mc{Q}_{\sf RS},\tau_{S}) &= \frac{1}{s}, \\
            \nit{CE}(D,\mc{Q}_{\sf RS},\tau_{S}) &= P_D(\mc{Q}_{\sf RS}) \times \frac{2}{2^s - 1}.
        \end{align*}
        It is clear that $r >,<,= s$ iff $\rho(D,\mc{Q}_{\sf RS},\tau_{R}) <,>,= \rho(D,\mc{Q}_{\sf RS},\tau_{S})$ iff $\nit{CE}(D,\mc{Q}_{\sf RS},\tau_{R}) <,>,= \nit{CE}(D,\mc{Q}_{\sf RS},\tau_{S})$. Therefore, the scores are aligned for these tuples.


        Now, for case (2), $D$ becomes $\mc{Q}$-separable with the partition $\{D_{c_1},\ldots,D_{c_s}\}$, where each $D_{c_i}$ contains all the tuples that have the constant $c_i$ in $x$'s position of the atoms in $\mc{Q}_{\sf RS}$.\
        Consider two tuples $\tau_i$ and $\tau_j$ in $D_{c_i}$ and $D_{c_j}$, resp., with $i,j \in \{1,\ldots,s\}$. \ By Proposition \ref{prop:scores_q-separable}, ${\sf sc}(D,\mc{Q}_{\sf RS},\tau_i) >,<,= {\sf sc}(D,\mc{Q}_{\sf RS},\tau_j)$ iff ${\sf sc}(D_{c_i} \cup D_{c_j},\mc{Q}_{\sf RS},\tau_i) >,<,= {\sf sc}((D_{c_i} \cup D_{c_j},\mc{Q}_{\sf RS},\tau_j)$, with ${\sf sc}(\cdot)$ being {\sf Resp} or {\sf CES}. It follows that we only need to show that the scores are aligned for $D_{c_i} \cup D_{c_j}$.

        Two cases arise: (a) $i = j$, implying that $D_{c_i} \cup D_{c_j} = D_{c_i} = D_{c_j}$, and (b) $i \neq j$. Case (a) was already shown for case (1) above. \
        For (b), let $D_{c_i,c_j} = D_{c_i} \cup D_{c_j}$. Additionally, denote $\tau_{R,i}$ ($r_i$) and $\tau_{S,i}$ ($s_i$) a tuple (number of tuples) in $D_{c_i}$ from (in) relations $R$ and $S$. Similarly, $\tau_{R,j}$ ($r_j$) and $\tau_{S,j}$ ($s_j$) denote a tuple and the number of tuples in $D_{c_j}$ from (in) relations $R$ and $S$.

        Since all tuples from the same relation and database have the same score, it suffices to show that the scores are aligned for any combination of two tuples from $\{\tau_{R,i}, \tau_{S,i}, \tau_{R,j}, \tau_{S,j}\}$: (i) $\tau_{R,i}$ and $\tau_{S,i}$, (ii) $\tau_{R,i}$ and $\tau_{R,j}$ , (iii) $\tau_{R,i}$ and $\tau_{S,j}$ , (iv) $\tau_{S,i}$ and $\tau_{R,j}$ , (v) $\tau_{S,i}$ and $\tau_{S,j}$ and (vi) $\tau_{R,j}$ and $\tau_{S,j}$.

        Notice that comparisons (i) and (vi) were shown in case (1) above; and, therefore, we only need to show the remaining cases.
\ We now compute the {\sf Resp} and {\sf CES} for each tuple:
        \begin{align*}
            \rho(D_{c_i,c_j},\mc{Q}_{\sf RS},\tau_{R,i}) &= \frac{1}{r_i + \min\{r_j,s_j\}}, \\
            \nit{CE}(D_{c_i,c_j},\mc{Q}_{\sf RS},\tau_{R,i}) &= P_{D_{c_i}}(\mc{Q}_{\sf RS}) \times \frac{1}{2^{r_i}-1} \times (1 - P_{D_{c_j}}(\mc{Q}_{\sf RS})), \\
            \rho(D_{c_i,c_j},\mc{Q}_{\sf RS},\tau_{R,j}) &= \frac{1}{r_j + \min\{r_i,s_i\}}, \\
            \nit{CE}(D_{c_i,c_j},\mc{Q}_{\sf RS},\tau_{R,j}) &= P_{D_{c_j}}(\mc{Q}_{\sf RS}) \times \frac{1}{2^{r_j}-1} \times (1 - P_{D_{c_i}}(\mc{Q}_{\sf RS})), \\
            \rho(D_{c_i,c_j},\mc{Q}_{\sf RS},\tau_{S,i}) &= \frac{1}{s_i + \min\{r_j,s_j\}}, \\
            \nit{CE}(D_{c_i,c_j},\mc{Q}_{\sf RS},\tau_{S,i}) &= P_{D_{c_i}}(\mc{Q}_{\sf RS}) \times \frac{1}{2^{s_i}-1} \times (1 - P_{D_{c_j}}(\mc{Q}_{\sf RS})), \\
            \rho(D_{c_i,c_j},\mc{Q}_{\sf RS},\tau_{S,j}) &= \frac{1}{s_j + \min\{r_i,s_i\}}, \\
            \nit{CE}(D_{c_i,c_j},\mc{Q}_{\sf RS},\tau_{S,j}) &= P_{D_{c_j}}(\mc{Q}_{\sf RS}) \times \frac{1}{2^{s_j}-1} \times (1 - P_{D_{c_i}}(\mc{Q}_{\sf RS})),
        \end{align*}
        with $P_{D_{c_i}}(\mc{Q}_{\sf RS}) = \frac{(2^r_i - 1) \times (2^s_i - 1)}{2^{r_i} \times 2^{s_i}}$ and $P_{D_{c_j}}(\mc{Q}_{\sf RS}) = \frac{(2^r_j - 1) \times (2^s_j - 1)}{2^{r_j} \times 2^{s_j}}$. \
        For simplicity, we will assume $r_i < s_i$ and $r_j < s_j$, but all the steps steps can be achieved by establishing different relations, say $r_i > s_i$ and $r_j > s_j$. \
        This initial assumption will simplify the amounts $\min\{r_i, s_i\}$ and $\min\{r_j, s_j\}$ to $r_i$ and $r_j$, respectively.

        Now, we show that the scores are aligned for each of the remaining cases.

        For (ii),  $\rho(D_{c_i,c_k},\mc{Q}_{\sf RS},$ $\tau_{R,i}) = \rho(D_{c_i,c_k},\mc{Q}_{\sf RS},\tau_{R,j})$, and therefore, the scores will be always aligned for these tuples. For (iii), we have that $\rho(D_{c_i,c_k},\mc{Q}_{\sf RS},\tau_{R,i}) > \rho(D_{c_i,c_k},\mc{Q}_{\sf RS},\tau_{S,j})$, which is directly obtained by comparing the given expressions. Therefore, we need to show that $\nit{CE}(D_{c_i,c_k},\mc{Q}_{\sf RS},\tau_{R,i}) > \nit{CE}(D_{c_i,c_k},\mc{Q}_{\sf RS},\tau_{S,j})$. This can be obtained by simple algebraic manipulation:
        \begin{align*}
            \nit{CE}(D_{c_i,c_k},\mc{Q}_{\sf RS},\tau_{R,i}) &> \nit{CE}(D_{c_i,c_k},\mc{Q}_{\sf RS},\tau_{S,j})? \\
            \frac{(2^{s_i} - 1)}{2^{r_i} \times 2^{s_i}} \times \frac{(2^{r_j} + 2^{s_j} - 1)}{2^{r_j} \times 2^{s_j}} &> \frac{(2^{r_j} - 1)}{2^{r_j} \times 2^{s_j}} \times \frac{(2^{r_i} + 2^{s_i} - 1)}{2^{r_i} \times 2^{s_i}}? \\
            (2^{s_i} - 1) \times (2^{r_j} + 2^{s_j} - 1) &> (2^{r_j} - 1) \times (2^{r_i} + 2^{s_i} - 1)? \\
            1 + \frac{2^{s_j}}{2^{r_j} - 1} &> 1 + \frac{2^{r_i}}{2^{s_i}-1}?
        \end{align*}
       The last inequality is true, by our first assumption that $r_i > s_i$ and $r_j > s_j$. It follows that, for these two tuples, the scores will be always aligned.

        Now, for (iv), notice that it is equivalent to (iii), subject to replacement of tuples: $\tau_{R,j}$ instead of $\tau_{R,i}$, and $\tau_{S,i}$ instead of $\tau_{S,j}$.

        Finally, for (v), $\rho(D_{c_i,c_k},\mc{Q}_{\sf RS},\tau_{S,i})>\rho(D_{c_i,c_k},\mc{Q}_{\sf RS},\tau_{S,j})$ iff $s_i - r_i < s_j - r_j$,\footnote{In the same way, we can show that $s_i - r_i > s_j - r_j$ iff $\rho(D_{c_i,c_k},\mc{Q}_{\sf RS},\tau_{S,i}) < \rho(D_{c_i,c_k},\mc{Q}_{\sf RS},\tau_{S,j})$ iff $\nit{CE}(D_{c_i,c_k},\mc{Q}_{\sf RS},\tau_{S,i}) < \nit{CE}(D_{c_i,c_k},\mc{Q}_{\sf RS},\tau_{S,j})$.} which is obtained directly by comparing the {\sf Resp} expressions. Now, we check that $\nit{CE}(D_{c_i,c_k},\mc{Q}_{\sf RS},\tau_{S,i})>\nit{CE}(D_{c_i,c_k},\mc{Q}_{\sf RS},\tau_{S,j})$ iff $s_i - r_i < s_j - r_j$, which can be verified by algebraic manipulation of the {\sf CES} expressions:
        \begin{align*}
            \nit{CE}(D_{c_i,c_k},\mc{Q}_{\sf RS},\tau_{S,i}) &> \nit{CE}(D_{c_i,c_k},\mc{Q}_{\sf RS},\tau_{S,j})? \\
            \frac{(2^{r_i} - 1)}{2^{r_i} \times 2^{s_i}} \times \frac{(2^{r_j} + 2^{s_j} - 1)}{2^{r_j} \times 2^{s_j}} &> \frac{(2^{r_j} - 1)}{2^{r_j} \times 2^{s_j}} \times \frac{(2^{r_i} + 2^{s_i} - 1)}{2^{r_i} \times 2^{s_i}}? \\
            (2^{r_i} - 1) \times (2^{r_j} + 2^{s_j} - 1) &> (2^{r_j} - 1) \times (2^{r_i} + 2^{s_i} - 1)? \\
            1 + \frac{2^{s_j}}{2^{r_j} - 1} &> 1 + \frac{2^{s_i}}{2^{r_i}-1}? \\
            2^{s_j - r_j} - \frac{1}{2^{s_j}} &< 2^{s_i - r_i} - \frac{1}{2^{s_i}}? \\
            \frac{1}{2^{s_i}} - \frac{1}{2^{s_j}} &< 2^{s_i - r_i} - 2^{s_j - r_j}?
        \end{align*}
        In the last inequality, the RHS is greater than one, while the LHS is smaller than one. Therefore, the scores are aligned for (v). It follows that, since the scores are aligned for any arbitrary pair of tuples in $D$, the scores are aligned for any possible instance. \boxtheorem

\vspace{2mm}
        \noindent {\bf Proof of Proposition \ref{prop:ces_reps_qrnsm_noexo}. \ }
        By Proposition \ref{lemma:coin_var}, we can consider the reduced form of the query, as in Remark \ref{rem:red}, which will be denoted with
        $\mc{Q}^\nit{red}_{R_{1},S_{m}}\!: \  \bar{\exists} (R_1(x,y) \wedge S_1(x) \wedge \ldots \wedge S_m(x))$. Notice that the case  $m = 1$ is already covered by Proposition \ref{prop:ces_resp_2_noex}. From now on, we will assume $m \geq 2$.

        Now, consider an instance $D$ without dummy tuples. Two cases arise:

        \noindent (1) All tuples in $D$ share the same constant in the $x$'s position of the atoms in $\mc{Q}^\nit{red}_{R_{1},S_{m}}$; or

        \noindent (2) $D$ contains at least two tuples where the constants in the $x$'s position of each tuple are different.

        We first deal with case (1). \ Let $\tau_R$ and $\tau_{s_i}$ a tuple from relation $R$ and $S_i$, respectively, with $i \in \{1,\ldots,m\}$, and $r$ the total number of tuples in the relation $R$. Note that all tuples $\tau_R$ have the same scores ({\sf Resp} and {\sf CES}). The same holds for all tuples $\tau_{S_i}$ with $i \in \{1,\ldots,m\}$. This implies that obtaining alignment only requires comparing the relative ordering of $\tau_R$ and $\tau_{S_i}$. We now compute {\sf Resp} and {\sf CES} for each tuple:
        \begin{align*}
            \rho(D,\mc{Q}^\nit{red}_{R_{1},S_{m}},\tau_R) &= \frac{1}{1+r}, \\
            \nit{CE}(D,\mc{Q}^\nit{red}_{R_{1},S_{m}},\tau_R) &= 2^{-(r+m-1)}, \\
            \rho(D,\mc{Q}^\nit{red}_{R_{1},S_{m}},\tau_{S_i}) &= \frac{1}{2}, \\
            \nit{CE}(D,\mc{Q}^\nit{red}_{R_{1},S_{m}},\tau_{S_i}) &= 2^{-(r+m-1)}.
        \end{align*}
        Since $ \nit{CE}(D,\mc{Q}^\nit{red}_{R_{1},S_{m}},\tau_R) = \nit{CE}(D,\mc{Q}^\nit{red}_{R_{1},S_{m}},\tau_{S_i})$,  the scores are aligned.

        Now, for case (2), we have that $D$ is $\mc{Q}^\nit{red}_{R_{1},S_{m}}$-separable with partition $\{D_{c_1},\ldots,D_{c_s}\}$, with each $D_{c_i}$ containing all tuples for which the constant $c_i$ appears in the $x$'s position. Denote with $\tau$ and $\tau^\prime$ two arbitrary tuples from $D$. Two scenarios arise:

        \noindent (a) $\tau,\tau^\prime \in D_{c_j}$ for a given $i \in \{c_1,\ldots,c_s\}$. Then, the scores will be aligned for $D$ iff they are aligned $D_{c_j}$ (see Proposition \ref{prop:scores_q-separable}). By case (1) above, this holds, and, therefore, the scores are aligned for these pair of tuples.

        \noindent
        (b) $\tau \in D_{c_j}$ and $\tau^\prime \in D_{c_k}$, with $j,k \in \{1,\ldots,s\}$, $j \neq k$. Let $\tau_{R,j}$ ($r_j$), $\tau_{R,k}$ ($r_k$), $\tau_{S_i,j}$ and $\tau_{S_i,k}$ be a tuple (number of tuples) from relations $R$ in $D_{c_j}$, $R$ in $D_{c_k}$, $S_i$ in $D_{c_j}$ and $S_i$ in $D_{c_k}$, respectively.

        In order to show that the scores are aligned, we do it for the following individual cases: (i) $\tau_{R,j}$ and $\tau_{R,k}$, (ii) $\tau_{R,j}$ and $\tau_{S_i,j}$, (iii) $\tau_{R,j}$ and $\tau_{S_i,k}$, (iv) $\tau_{R,k}$ and $\tau_{S_i,j}$, (v) $\tau_{R,k}$ and $\tau_{S_i,k}$; and  (vi) $\tau_{S_i,j}$ and $\tau_{S_i,k}$. Notice that cases (ii) and (v) were shown in case (1) above. Additionally, cases (iii) and (iv) are the same, subject to tuple permutation. Therefore, we only need to show (i), (iii) and (vi). We now compute the {\sf Resp} and {\sf CES} for each of them:
        \begin{align*}
            \rho(D,\mc{Q}^\nit{red}_{R_{1},S_{m}},\tau_{R,j}) &= \frac{1}{1+r_j}, \\
            \nit{CE}(D,\mc{Q}^\nit{red}_{R_{1},S_{m}},\tau_{R,j}) &= P_{D_{c_j}}(\mc{Q}^\nit{red}_{R_{1},S_{m}}) \times \frac{2}{2^{r_j} - 1} \times \left( 1 - P_{D_{c_k}}\left(\mc{Q}^\nit{red}_{R_{1},S_{m}}\right) \right), \\ %---------------------
            \rho(D,\mc{Q}^\nit{red}_{R_{1},S_{m}},\tau_{R,k}) &= \frac{1}{1+r_k}, \\
            \nit{CE}(D,\mc{Q}^\nit{red}_{R_{1},S_{m}},\tau_{R,k}) &= P_{D_{c_k}}(\mc{Q}^\nit{red}_{R_{1},S_{m}}) \times \frac{2}{2^{r_k} - 1} \times \left( 1 - P_{D_{c_j}}\left(\mc{Q}^\nit{red}_{R_{1},S_{m}}\right) \right), \\  %---------------------
            \rho(D,\mc{Q}^\nit{red}_{R_{1},S_{m}},\tau_{S_i,j}) &= \frac{1}{2}, \\
            \nit{CE}(D,\mc{Q}^\nit{red}_{R_{1},S_{m}},\tau_{S_i,j}) &= P_{D_{c_j}}(\mc{Q}^\nit{red}_{R_{1},S_{m}}) \times 2 \times \left( 1 - P_{D_{c_k}}\left(\mc{Q}^\nit{red}_{R_{1},S_{m}}\right) \right), \\ %---------------------
            \rho(D,\mc{Q}^\nit{red}_{R_{1},S_{m}},\tau_{S_i,k}) &= \frac{1}{2}, \\
            \nit{CE}(D,\mc{Q}^\nit{red}_{R_{1},S_{m}},\tau_{S_i,k}) &= P_{D_{c_k}}(\mc{Q}^\nit{red}_{R_{1},S_{m}}) \times 2 \times \left( 1 - P_{D_{c_j}}\left(\mc{Q}^\nit{red}_{R_{1},S_{m}}\right) \right), %---------------------
        \end{align*}
        with $P_{D_{c_j}}\left(\mc{Q}^\nit{red}_{R_{1},S_{m}}\right) = \frac{(2^{r_j} - 1)}{2^{r_j + m}}$ and  $P_{D_{c_k}}\left(\mc{Q}^\nit{red}_{R_{1},S_{m}}\right) = \frac{(2^{r_k} - 1)}{2^{r_k + m}}$.

        For (i), it is clear that $r_j >,<,= r_k$ iff $\rho(D,\mc{Q}^\nit{red}_{R_{1},S_{m}},\tau_{R,j})) <,>,= \rho(D,\mc{Q}^\nit{red}_{R_{1},S_{m}},\tau_{R,k})$ iff $\nit{CE}(D,\mc{Q}^\nit{red}_{R_{1},S_{m}},\tau_{R,j}) <,>,= \nit{CE}(D,\mc{Q}^\nit{red}_{R_{1},S_{m}},\tau_{R,k})$.

