% \end{definition}

%     Note that a $(m, \alpha, \beta)$-subsamplable set $X$ is also a $(m, \alpha, \beta)$-$I$-linear-approximation of itself with $I$ denoting the identity matrix.

\paragraph{Notations.} Let \( \mathcal{S}^{d-1} \) denote The \textit{unit sphere} in \( \mathbb{R}^{d} \), which is defined as the set of all points in \( d \)-dimensional Euclidean space that have unit norm, i.e.,
$
\mathcal{S}^{d-1} = \{ x \in \mathbb{R}^{d} \mid \| x \|_2 = 1 \}
$.
Here, the superscript \( d-1 \) indicates that the unit sphere is an object of intrinsic dimension \( d-1 \) embedded in \( \mathbb{R}^{d} \).
\\
Let $\rm GUE(\sigma^2)$ denote the distribution over $d \times d$ symmetric matrices $N$ where for all $i \leq j$, we have $N_{ij} \sim \mathcal{N}(0, \sigma^2)$ i.i.d.. From basic random matrix theory, we have the following guarantee.



\begin{fact}[see e.g. \cite{taotopics} Corollary 2.3.6]\label{fact:gaussian-bound}
    For $d$ sufficiently large, there exist absolute constants $C, c > 0$ such that:
    $ \Pr\limits_{N \sim \rm GUE(\sigma^2)}[\|N\|_2 > A\sigma\sqrt{d}] \leq C e^{-cAd}$    for all $A \geq C$.
\end{fact}

\begin{definition}[Differential Privacy~\citep{Dwork06}]
A randomized algorithm $\mathcal{A}$ satisfies $(\epsilon, \delta)$-differential privacy if, for all datasets $D$ and $D'$ differing in at most one element, and for all measurable subsets $S$ of the output space of $\mathcal{A}$, it holds that:
\[
\Pr[\mathcal{A}(D) \in S] \leq e^{\epsilon} \Pr[\mathcal{A}(D') \in S] + \delta.
\]
%Here, $\epsilon > 0$ is the privacy loss parameter, which controls the level of privacy, and $\delta \geq 0$ represents the probability of a privacy breach.
\end{definition}

\begin{definition}[Zero-Concentrated Differential Privacy (zCDP)~\citep{bun2016concentrateddifferentialprivacysimplifications}]
A randomized algorithm $\mathcal{A}$ satisfies $\rho$-zero-concentrated differential privacy ($\rho$-zCDP) if, for all datasets $D$ and $D'$ differing in at most one element, and for all $\alpha > 1$, the Rényi divergence of order $\alpha$ between the output distributions of $\mathcal{A}$ on $D$ and $D'$ is bounded by $\rho \alpha$, i.e.,
$
D_{\alpha}(\mathcal{A}(D) \| \mathcal{A}(D')) \leq \rho \alpha
$.
Here, $\rho \geq 0$ is the privacy parameter that controls the trade-off between privacy and utility, and $D_{\alpha}$ denotes the Rényi divergence of order $\alpha$.
\end{definition}

\begin{theorem}[\cite{bun2016concentrateddifferentialprivacysimplifications}]
If a randomized algorithm $\mathcal{A}$ satisfies $\rho$-zero-concentrated differential privacy ($\rho$-zCDP), then $\mathcal{A}$ also satisfies $(\epsilon, \delta)$-differential privacy for any $\delta > 0$, where:
$
\epsilon = \rho + \sqrt{2\rho \ln\left(\frac{1}{\delta}\right)}
$.
\end{theorem}

\begin{theorem}[Composition Theorem for \(\rho\)-zCDP]
    Let \(\mathcal{M}_1\) and \(\mathcal{M}_2\) be two independent mechanisms that satisfy \(\rho_1\)-zCDP and \(\rho_2\)-zCDP, respectively. Then their composition \(\mathcal{M}_1 \circ \mathcal{M}_2\) satisfies \((\rho_1 + \rho_2)\)-zCDP.
\end{theorem}

\section{Technical Analysis}
 \subsection{Baseline}
\label{subsec:base-SMDP}

In this section, we provide a baseline for the problem of 2nd-moment estimation using subsample and aggregate framework~\citep{NissimRS07}. For the lack of space we move the entire discussion of the baseline to Appendix~\ref{apx_sec:base-SMDP}, and only cite here the conclusion.

\begin{theorem}
Let $\xi$, $\epsilon$, $\delta$ be parameters, and let $X \subseteq \mathbb{R}^d$ be a $(m, \alpha, \beta)$-subsamplable set of $n$ points. Then, there exists an algorithm for which the following properties hold:
\begin{enumerate}
    \item The algorithm is $(2\epsilon, 4e^{\epsilon}\delta)$-Differential Private.
    \item The algorithm returns $\tilde{\Sigma}$ satisfying $\|\Sigma^{-1/2}\tilde\Sigma \Sigma^{-1/2}  -I \| \leq 2\alpha$, where $\Sigma = \frac{1}{n}XX^\top$.
\end{enumerate}
These guarantees hold under the following conditions:
\begin{enumerate}
    \item The dataset size satisfies:
    $n \geq 800m \cdot$~  \resizebox{0.6\textwidth}{!}{
    $\max\left\{
    \sqrt{\frac{2d(d + \nicefrac{1}{\eta^2})}{\epsilon}}, 
    \frac{8d\sqrt{\ln(\nicefrac{2}{\delta})}}{\epsilon}, 
    \frac{8\ln(\nicefrac{2}{\delta})}{\epsilon}, 
    \frac{12\sqrt{d\ln(\nicefrac{2}{\delta})}}{\epsilon\eta}, 
    \frac{\ln\left(1 + \frac{e^\epsilon - 1}{2\delta}\right)}{80\epsilon}
    \right\}$}
    where $\eta = \frac{\alpha}{48C(\sqrt{d} + \sqrt{\ln(\nicefrac{4}{\xi})})}$ for a sufficiently large constant $C>0$.
    \item The subsamplability parameters satisfy $m \geq {2\beta n}/{\xi}.$
\end{enumerate}
\end{theorem}
In particular, Item 1 suggests a sample complexity bound of $n=\Omega( \frac{d\cdot m(\alpha,\beta)}{\epsilon \alpha} )$.



\subsection{Finding Initial Parameters}
\label{subsec:Initial_parameters}

Our recursive algorithm requires as input two parameters that characterize the ``aspect ratio'' of the input, namely ~-- $R_{\max}$, 
the maximum distance of any point from the origin, and $\lambda_{\min}$, the minimum eigenvalue of the input. These two parameters give us the initial bounds, as they imply that $\lambda_{\min} I \preceq \Sigma \preceq R_{\max}^2 I$.
Due to space constraints, we move the entire discussion, regarding how to apply off-the-shelf algorithms, or modify such algorithms, to obtain these initial parameters to Appendix~\ref{apx_sec:Initial_parameters}.







\subsection{Main Algorithm and Theorem}
\label{subsec:main-alg}

Next, we detail our algorithm that approximates the second moment of the input. Its starting point is the assumption that the input has a known bound on the $L_2$-norm of each point $R$, and that the second moment matrix of the input, $\Sigma$, satisfies $I \preceq \Sigma \preceq R^2 I$.

\begin{algorithm}[hb]
    \caption{DP Second Moment Estimation}
    \label{alg:dpsme}
     \textbf{Input:} a $(m, \alpha, \beta)$-subsamplable set of $n$ points $X \subseteq \mathbb{R}^d$, parameters: error parameter $\xi \in (0,1)$, privacy parameter $\rho$, covering radius $R$.
    \begin{algorithmic}[1]
     % Input:
     % Output:
     \STATE  Set: $\eta \gets \nicefrac{1}{2}, \quad T \gets \log_{\nicefrac{7}{3}}\left(\frac{(\frac{1}{1-\alpha})R^2}{640m}\right)$, $\quad \psi \gets \frac{1}{10m}$,
      $c \gets \frac{1}{80m}, \quad C \gets 640m, \quad \kappa \gets R^2$
     \STATE $\tilde\Sigma \gets \hyperref[alg:rec-psme]{\rm RecDPSME}$ $(\sqrt{(\frac{1}{1-\alpha})}X, \eta, \psi, C, c, (\frac{1}{1-\alpha})\kappa, \sqrt{(\frac{1}{1-\alpha})}R, T, \xi, \rho)$
     \STATE \textbf{return} $(1-\alpha)\tilde\Sigma$
    \end{algorithmic}
\end{algorithm}

\begin{algorithm}[ht]
    \caption{Recursive DP Second Moment Estimation (RecDPSME)}
    \label{alg:rec-psme}
    \textbf{Input:} a set of $n$ points $X \subseteq \mathbb{R}^d$, parameters:  linear shrinking $\eta < 1$, eigenvalue threshold $\psi < 1$, stopping value C, noise $c$, eigenvalue upper bound $\kappa$, radius $R$, iterations bound $T$, error parameter $\xi$, privacy loss $\rho$.\linebreak
    \begin{algorithmic}[1]
     % Input:
     % Output:
     \STATE Set $\sigma \gets \frac{4R^2 \sqrt{T}}{n \sqrt{2\rho}}$
     \STATE Sample $N\sim \rm GUE(\sigma^2)$
     \STATE $\Tilde{\Sigma} \gets \frac{1}{n}XX^T + N$
     \IF{$\kappa \leq C$}
     \STATE \textbf{return} $\Tilde{\Sigma}$.
     \ENDIF 
     \STATE $V \gets \text{Span}(\{v_i: \text{eigenvector of } \Tilde{\Sigma} \text{ with  eigenvalue } \geq \psi\kappa \})$
     \STATE  $\Pi \gets \eta\Pi_V + \Pi_{V^\perp}$  \hfill \COMMENT{$\Pi_U$ denotes the projection matrix onto $U$.}
     \STATE  $Y \gets \sqrt{\frac{8}{7}}\Pi X$.
     \STATE $X_{next} \gets S(Y)$ \hfill where $S(Y) = \left\{y \cdot \min\left\{1, \sqrt{\frac{\frac{3}{7}R}{\|y\|^2}}\right\} :~ y \in Y \right\}$
    \STATE  $\Sigma_{\text{rec}} \gets \hyperref[alg:rec-psme]{\rm RecDPSME}\left(X_{next}, \eta, \psi, C, c, \frac{3}{7}\kappa, \sqrt{\frac{3}{7}}R, T, \xi, \rho\right)$
     \STATE  \textbf{return} $\frac{7}{8}\Pi^{-1} \Sigma_{\text{rec}} \Pi^{-1}$
    \end{algorithmic}
\end{algorithm}

In our analysis, the following definition plays a key role.
\begin{definition}
    \label{def:tail}
    Let $X$ be a $(m, \alpha, \beta)$-subsamplable set. We denote $P_{\rm tail}$ as the set of points whose projection onto some direction $u$ in $\R^d$ is $m$ times greater than expected, namely\linebreak
\[P_{\text{tail}} = \left\{x \in X:~ \exists u \in \R^d:~ \langle x,u\rangle^2 > m(1+\alpha)\cdot \frac{1}{n}\sum\limits_{x \in X} \innerproduct{x}{u}^2\right\}\]
\end{definition}



\begin{theorem}\label{thm:main}
     Fix parameters $\xi \in (0,1)$, $\rho > 0, \gamma > 0$ and $\kappa \geq 1$. Let $X\subset \R^d$ be a  $(m, \alpha, \beta)$-subsamplable set of $n$ points bounded in $L_2$ norm by $R^2$,  with $\alpha \leq \nicefrac{1}{2}$ and $\beta \leq \frac{\alpha}{4(1+\alpha)\log(\frac{R^2}{(1+\alpha)m})}$ s.t. $I \preceq \Sigma \preceq R^2 I$ where $\Sigma = \frac{1}{n}X X^T$. Then, denoting $T = \log_{\nicefrac{7}{3}}\left(\frac{(\frac{1}{1-\alpha})R^2}{640m}\right)=O(\log(\nicefrac R m))$, we have that for Algorithm~\ref{alg:dpsme}, if
    \[ n \geq \Omega\left(m\sqrt{\frac{d}{\rho}}\left(\sqrt{T}\log(\nicefrac{T}{\xi}) + \frac{\log(\nicefrac{1}{\xi})}{\gamma} \right)\right) \]
    Then
%    \begin{enumerate}
        (1)
        Algorithm~\ref{alg:dpsme} satisfies $\rho$-zCDP,\footnote{Note that the privacy of Algorithm~\ref{alg:dpsme} holds for any input $X$ with bounded $L_2$-norm, regardless of $X$ being subsamplable or not.}
        (2)
        $P_{\text{tail}}$ holds at most a $(\frac{\beta + \beta^2}{m})$-fraction of $|X|$, 
        and (3)
        w.p. $\geq 1 - 2\xi$ it outputs $\tilde\Sigma$ such that:
        \[ (1-\gamma)\Sigma_{\text{eff}} \preceq \tilde\Sigma \preceq (1+\gamma)\Sigma \]
        where $\Sigma_{\text{eff}} = \frac 1 n \sum\limits_{x\in X \setminus P_{\text{tail}}}x x^T$. 
%    \end{enumerate}

    % where $\Sigma_{\text{eff}}$ is the covariance matrix of at least $(1 - \frac{\beta + \beta^2}{m})$-fraction of the points.
\end{theorem}


\subsection{Algorithm's Analysis}
\label{subsec:analysis}

Next we prove Theorem~\ref{thm:main}. 
Momentarily we shall argue that Algorithm~\ref{alg:rec-psme} repeats for at most $T = \log_{\nicefrac{7}{3}}\left(\frac{(\frac{1}{1-\alpha})R^2}{640m}\right)$ iterations. Based on Fact~\ref{fact:gaussian-bound} and on the bound on the number of iterations, it is simple to argue that the following event holds w.p. $\geq 1-\xi$:
\[ \mathcal{E} := \text{in each iteration of Algorithm~\ref{alg:rec-psme} we have } \|N\|\leq cR^2 = c\kappa \]
which follows from the fact that in each iteration the upper bound on the largest eigenvalue of $\Sigma$ is at most $\kappa = R^2$. We continue our analysis conditioning on $\mathcal{E}$ holding.


The analysis begins with the following lemma, that shows that under $\mathcal{E}$ we have that in each iteration the eigenvalues of $\Sigma$ decrease. Its proof is very similar to the proof in~\cite{kamath2019privatelylearninghighdimensionaldistributions} and so it is deferred to Appendix~\ref{apx_sec:missing_proofs}.

\begin{lemma}\label{lem:eigenvalues}
Given $X = \{X_1,...,X_n\} \subset \mathbb{R}^d$, $C > 0, c > 0, 0 < \eta < 1, 0 < \psi < 1$, and $\kappa \geq 1$ s.t. $I \preceq \Sigma \preceq \kappa I$ where $\Sigma = \frac{1}{n}X X^T$. Let $V \gets \text{Span}(\{v_i: \lambda_i \geq \psi \kappa\})$ 
of the largest eigenvalues of the noisy $\tilde \Sigma$ 
and let $\Pi = \eta \Pi_V + \Pi_{V^\perp}$. Given that:
$n \geq \Omega\left(m\sqrt{\frac{dT}{\rho}} \ln(\nicefrac{T}{\xi})\right)$
Then:
\[ (1 - \frac{1}{\eta^2\psi - c} \cdot \frac{1}{\kappa})I \preceq \Pi\Sigma\Pi \preceq (\eta^2 + \psi + 2c)\kappa I \]
In particular, if $\kappa > C$ for some $C$ then:
$I \preceq \frac{1}{(1 - \frac{1}{\eta^2\psi - c})}\Pi\Sigma\Pi \preceq \frac{\eta^2 + \psi + 2c}{(1 - \frac{1}{C(\eta^2\psi - c)})}\kappa I$.
\end{lemma}




