    %    Let $\Sigma$ be a PSD matrix with least eigenvalue $\geq 1$ and let $N$ be a matrix such that $\|N\| \leq \gamma$. Then:
    %    $(1-\gamma)\Sigma \preceq \Sigma + N \preceq (1+\gamma)\Sigma$.
    %\end{proposition}
%   \begin{proof}
%      First, all eigenvalues of $\Sigma + N$ are greater than $1-\gamma$, so it holds that $\Sigma + N$ is a PSD matrix. 
%        Fix $v \in \mathcal{S}^{d-1}$. Our goal is to show that
 %       \[ -\gamma v^T \Sigma v \leq v^T N v \leq \gamma v^T \Sigma v \]
  %      which is true seeing as $|v^T N v| \leq \gamma$ and $v^T \Sigma v \geq 1$.
   %     \end{proof}
    \noindent We prove by recursion that:
    $
    (1-\gamma)\Sigma_{\text{eff}} \preceq \tilde{\Sigma} \preceq (1+\gamma)\Sigma
    $.

    \textbf{Stopping Rule:} Let $X^T$ be the input at the final iteration $T$ and let $P = X \setminus P_{\text{tail}}$. Denote $\Sigma(\cdot)$ as the second moment matrix operator. We know that throughout the algorithm, the points from $P$ were not shrunk. Moreover, Corollary~\ref{cor:always_least_eigenvalue_of_1} assures that the least eigen value of $\Sigma(X)$ is $\geq 1$. Additionally, our bound on $n$ yields that when $\kappa \leq C$ then the noise matrix $N$ we add satisfy that $\|N\|_2 \leq \gamma$ w.p. $\geq 1-\xi$.  It thus follows that
    $
    (1-\gamma)\Sigma(X^T) \preceq \Sigma + N \preceq (1+\gamma)\Sigma(X^T)
    $ as required.

    \textbf{Recursive Step:} Let $X^t$ be the input at iteration $t \leq T$. Then, by Lemma~\ref{lem:eigenvalues}, we have:
    $
    I \preceq \Sigma\left(\frac{8}{7} \Pi X^t\right) \preceq \frac{3}{7}\kappa I
    $.
    Lemma~\ref{lem:shrinking-only-red} ensures that $S(\Pi X^t)$ shrinks only points from $P_{\text{tail}}$ and  so Corollary~\ref{cor:always_least_eigenvalue_of_1} assures that the eigenvalue is $\geq 1$ throughout the recursive iterations. Hence, by the inductive hypothesis, our recursive call returns $\Sigma_{\text{rec}}$ such that:
    \[
    (1-\gamma)\Sigma_{\text{eff}}\left(\sqrt{\frac{8}{7}} \Pi X^t\right) \preceq {\Sigma}_{\text{rec}} \preceq (1+\gamma)\Sigma\left(\sqrt{\frac{8}{7}} \Pi X^t\right),
    \]
    which implies:
    \[
    (1-\gamma)\Sigma_{\text{eff}}(X^t) \preceq \frac{7}{8}\Pi^{-1}{\Sigma}_{\text{rec}}\Pi^{-1} \preceq (1+\gamma)\Sigma(X^t).
    \]
    Proving the required for any intermediate iteration of Algorithm~\ref{alg:rec-psme}.
\end{proof}






























\section{Applications: Coping with Outliers}
\label{sec:applications}
\newcommand{\D}{\mathcal{D}}

\subsection{Input Drawn from `Nice' Distributions}
First, we show  our algorithm returns an approximation of the 2nd-moment matrix when the input is drawn from a distribution $\D$. Throughout this section, we apply the Matrix-Bernestein Inequality.

\begin{fact}
    \label{fact:Matrx-Bernestein-Inequality}
    Let $Z$ be the sum of $m$ i.i.d.~matrices $Z = \sum_i Z_i$, whose mean is $0$ and have norm bounded by $\|Z_i\|\leq R$ almost surely. Then, denoting $\sigma^2 = \| \E[Z Z^T] \| $, it holds that
    \[  \Pr[\|Z\| > t] \leq 2d\exp\left( \frac{-t^2/2}{\sigma^2 + Rt/3 } \right)  \]

\end{fact}

We can apply Fact~\ref{fact:Matrx-Bernestein-Inequality} above to measure how well the sample
    covariance estimator approximates the true covariance matrix of a general distribution using the following claim (proof deferred to Appendix~\ref{appendix:proof_concentration_any_dist}.)
\DeclareRobustCommand{\ClaimGeneralDist}{
