\begin{theorem}[Covariance Estimation via Matrix Chernoff Bound]
\label{thm:cov_estimation_chernoff}
Let \( x_1, \dots, x_n \in \mathbb{R}^d \) be i.i.d.~samples from a zero-mean distribution with covariance matrix \( \Sigma \succ 0 \). Suppose that each sample satisfies the bounded Mahalanobis norm condition:
\[
x_i^\top \Sigma^{-1} x_i \leq L \quad \text{almost surely.}
\]
Then, for any \( \alpha \in (0,1) \), with probability at least \( 1 - \beta \), the empirical covariance matrix
\[
\hat{\Sigma} := \frac{1}{n} \sum_{i=1}^n x_i x_i^\top
\]
satisfies the operator norm bound:
\[
\left\| \Sigma^{-\frac{1}{2}} \hat{\Sigma} \Sigma^{-\frac{1}{2}} - I \right\|_2 \leq \alpha,
\]
provided that
\[
n \geq \frac{2L \ln(2d/\beta)}{\alpha^2}.
\]
\end{theorem}

\begin{proof}
Define normalized vectors:
\[
y_i := \Sigma^{-1/2} x_i \in \mathbb{R}^d.
\]
Then we have:
\[
\mathbb{E}[y_i y_i^\top] = \Sigma^{-1/2} \mathbb{E}[x_i x_i^\top] \Sigma^{-1/2} = \Sigma^{-1/2} \Sigma \Sigma^{-1/2} = I_d,
\]
and the empirical covariance of these normalized vectors is:
\[
\hat{M} := \frac{1}{n} \sum_{i=1}^n y_i y_i^\top = \Sigma^{-1/2} \hat{\Sigma} \Sigma^{-1/2}.
\]
Note that each term \( y_i y_i^\top \) is positive semi-definite with operator norm:
\[
\|y_i y_i^\top\|_2 = \|y_i\|_2^2 = x_i^\top \Sigma^{-1} x_i \leq L.
\]
Thus, the random matrices \( \{ y_i y_i^\top \} \) are i.i.d., symmetric, PSD, with expectation \( \mathbb{E}[y_i y_i^\top] = I_d \), and bounded spectral norm \( \leq L \).

We apply the matrix Chernoff bound for the sum \( \hat{M} = \frac{1}{n} \sum_{i=1}^n y_i y_i^\top \). From the matrix Chernoff inequality (e.g., Tropp 2012), for \( 0 < \alpha < 1 \):
\[
\Pr\left( \left\| \hat{M} - I_d \right\|_2 \geq \alpha \right) \leq 2d \cdot \exp\left( - \frac{n \alpha^2}{2L \ln 2} \right).
\]
To ensure this probability is at most \( \beta \), it suffices that:
\[
2d \cdot \exp\left( - \frac{n \alpha^2}{2L \ln 2} \right) \leq \beta
\quad \Longleftrightarrow \quad
n \geq \frac{2L \ln(2d/\beta)}{\alpha^2}.
\]

This completes the proof.
\end{proof}


\begin{theorem}[Robust Covariance Estimation via Median-of-Means]
\label{thm:robust_cov_mahalanobis}
Let \( x_1, \dots, x_n \in \mathbb{R}^d \) be i.i.d.~samples from a zero-mean distribution with covariance matrix \( \Sigma \succ 0 \). Suppose the Mahalanobis norm has finite fourth moment:
\[
\mathbb{E}\left[(x^\top \Sigma^{-1} x)^2\right] \leq M.
\]
Then there exists an estimator \( \hat{\Sigma}_{\mathrm{rob}} \) computable in polynomial time such that for any \( \delta \in (0,1) \), with probability at least \( 1 - \delta \), it holds that:
\[
\left\| \Sigma^{-1/2} \hat{\Sigma}_{\mathrm{rob}} \Sigma^{-1/2} - I \right\|_2 \leq C \sqrt{ \frac{M \log(d/\delta)}{n} },
\]
where \( C > 0 \) is a universal constant.
\end{theorem}

\begin{proof}[Proof Sketch]
Let \( y_i = \Sigma^{-1/2} x_i \), so that \( \mathbb{E}[y_i y_i^\top] = I_d \) and \( \|y_i\|^2 = x_i^\top \Sigma^{-1} x_i \). The assumption implies:
\[
\mathbb{E}\left[\|y_i\|^4\right] = \mathbb{E}[(x_i^\top \Sigma^{-1} x_i)^2] \leq M.
\]

Now apply the \emph{Median-of-Means} (MoM) technique:
\begin{enumerate}
    \item Divide \( \{y_1, \dots, y_n\} \) into \( B = \Theta(\log(1/\delta)) \) equal-sized blocks \( I_1, \dots, I_B \).
    \item For each block \( I_b \), compute:
    \[
    \hat{M}_b := \frac{1}{|I_b|} \sum_{i \in I_b} y_i y_i^\top.
    \]
    \item Return the geometric median (or coordinate-wise trimmed mean) of the matrices \( \hat{M}_1, \dots, \hat{M}_B \) in operator norm as \( \hat{M}_{\mathrm{rob}} \), and define:
    \[
    \hat{\Sigma}_{\mathrm{rob}} := \Sigma^{1/2} \hat{M}_{\mathrm{rob}} \Sigma^{1/2}.
    \]
\end{enumerate}

Standard concentration for the spectral norm of the block-averaged outer products \( y_i y_i^\top \), combined with robust aggregation, yields:
\[
\left\| \hat{M}_{\mathrm{rob}} - I \right\|_2 \leq C \sqrt{ \frac{M \log(d/\delta)}{n} }.
\]
Thus,
\[
\left\| \Sigma^{-1/2} \hat{\Sigma}_{\mathrm{rob}} \Sigma^{-1/2} - I \right\|_2 = \left\| \hat{M}_{\mathrm{rob}} - I \right\|_2 \leq C \sqrt{ \frac{M \log(d/\delta)}{n} }.
\]
\end{proof}




\begin{theorem}[Covariance Estimation via Matrix Rosenthal Inequality]
\label{thm:covariance_rosenthal}
Let \( x_1, \dots, x_n \in \mathbb{R}^d \) be i.i.d.~samples from a zero-mean distribution with covariance matrix \( \Sigma \succ 0 \), and define:
\[
\hat{\Sigma} := \frac{1}{n} \sum_{i=1}^n x_i x_i^\top.
\]
Assume that the fourth moment of the Mahalanobis norm is bounded:
\[
\mathbb{E}\left[(x^\top \Sigma^{-1} x)^2\right] \leq M.
\]
Then there exists a constant \( C > 0 \) such that:
\[
\mathbb{E}\left[ \left\| \Sigma^{-1/2} \hat{\Sigma} \Sigma^{-1/2} - I \right\|_2 \right]
\leq C \sqrt{ \frac{M \log d}{n} }.
\]
\end{theorem}

\begin{proof}[Proof Sketch]
Let \( y_i = \Sigma^{-1/2} x_i \), so that \( \mathbb{E}[y_i y_i^\top] = I \). Then:
\[
\Sigma^{-1/2} \hat{\Sigma} \Sigma^{-1/2} = \frac{1}{n} \sum_{i=1}^n y_i y_i^\top.
\]

Define:
\[
Z_i := y_i y_i^\top - \mathbb{E}[y_i y_i^\top], \quad \text{so} \quad \mathbb{E}[Z_i] = 0.
\]

We wish to bound:
\[
\mathbb{E}\left\| \frac{1}{n} \sum_{i=1}^n Z_i \right\|_2.
\]

Using the **non-commutative Rosenthal inequality** for independent, mean-zero, self-adjoint matrices (see \cite{tropp2012user, bandeira2016concentration}), we get:
\[
\mathbb{E} \left\| \sum_{i=1}^n Z_i \right\|_2
\leq C \cdot \max \left\{ \left\| \sum_{i=1}^n \mathbb{E}[Z_i^2] \right\|_2^{1/2}, \;
\mathbb{E} \left[ \max_{i \leq n} \| Z_i \|_2 \right] \cdot \log d \right\}.
\]

From the assumption:
\[
\|Z_i\|_2 = \|y_i y_i^\top - I\|_2 \leq \max\{ \|y_i\|_2^2, 1 \} + 1,
\]
and \( \mathbb{E}[\|y_i\|^4] = \mathbb{E}[(x^\top \Sigma^{-1} x)^2] \leq M \), so one can show:
\[
\left\| \sum_{i=1}^n \mathbb{E}[Z_i^2] \right\|_2 \leq n M.
\]

Hence:
\[
\mathbb{E}\left\| \frac{1}{n} \sum_{i=1}^n Z_i \right\|_2 \leq C \sqrt{ \frac{M \log d}{n} }.
\]

This yields:
\[
\mathbb{E}\left[ \left\| \Sigma^{-1/2} \hat{\Sigma} \Sigma^{-1/2} - I \right\|_2 \right] \leq C \sqrt{ \frac{M \log d}{n} }.
\]
\end{proof}
}





















