\section{Baseline}
\label{apx_sec:base-SMDP}

In this section, we provide a baseline for the problem of 2nd-moment estimation using subsample and aggregate framework (\cite{NissimRS07}). 




In this baseline, we work with the following notion of a convex semimetric space. The key property
to keep in mind is that for semimetric spaces, we only have an approximate triangle inequality, as
long as the points are \emph{significantly close} to one another.

\begin{definition}
    Let $\mathcal{Y}$ be a convex set and let $\text{dist}: \mathcal{Y} \times \mathcal{Y} \to \mathbb{R}_{\geq 0}$. We say $(\mathcal{Y}, \text{dist})$ is a convex semimetric space if there exist absolute constants $t \geq 1$, $\phi \geq 0$, and $r > 0$ such that for every $k \in \mathbb{N}$ and every $Y, Y_1, Y_2, \dots, Y_k \in \mathcal{Y}$, the following conditions hold:
    \begin{enumerate}
        \item $\text{dist}(Y, Y) = 0$ and $\text{dist}(Y_1, Y_2) \geq 0$.
        \item \textbf{Symmetry.} $\text{dist}(Y_1, Y_2) = \text{dist}(Y_2, Y_1)$.
        \item \textbf{$t$-approximate $r$-restricted triangle inequality.} If both $\text{dist}(Y_1, Y_2), \text{dist}(Y_2, Y_3) \leq r$, then
        \[
        \text{dist}(Y_1, Y_3) \leq t \cdot (\text{dist}(Y_1, Y_2) + \text{dist}(Y_2, Y_3)).
        \]
        \item \textbf{Convexity.} For all $\alpha \in \Delta_k$, 
        \[
        \text{dist}\left(\sum_{i} \alpha_i Y_i, Y\right) \leq \sum_{i} \alpha_i \text{dist}(Y_i, Y).
        \]
        \item \textbf{$\phi$-Locality.} For all $\alpha, \alpha' \in \Delta_k$,
        \[
        \text{dist}\left(\sum_{i} \alpha_i Y_i, \sum_{i} \alpha'_i Y_i\right) \leq \sum_{i} |\alpha_i - \alpha'_i| \left(\phi + \max_{i,j} \text{dist}(Y_i, Y_j)\right).
        \]
    \end{enumerate}

    \noindent where $\Delta_k$ denotes the $k$-dimensional probability simplex. When $r$ is unspecified, we take it to mean $r = \infty$ and refer to it as a $t$-approximate triangle inequality.
\end{definition}

The following technical lemma (whose proof appears in Appendix C in \cite{ashtiani2022private}) is helpful for learning second moment matrices.

\begin{lemma}\label{lem:convex-semimetric}
    Let $\mathcal{S}_d$ be the set of all $d \times d$ positive definite matrices. For $A, B \in \mathcal{S}_d$, let
    \[
    \text{dist}(A, B) = \max\{\|A^{-1/2} B A^{-1/2} - I\|, \|B^{-1/2} A B^{-1/2} - I\|\}.
    \]
    Then $(\mathcal{S}_d, \text{dist})$ is a convex semimetric which satisfies a $(\nicefrac{3}{2})$-approximate $1$-restricted triangle inequality and $1$-locality.
\end{lemma}

Based on Lemma~\ref{lem:convex-semimetric}, the following distance function forms a semimetric space for positive definite matrices:
\[
    \text{dist}(\Sigma_1, \Sigma_2) = 
\begin{cases}
    \max(\|\Sigma_2^{-\nicefrac{1}{2}}\Sigma_1\Sigma_2^{-\nicefrac{1}{2}} - I_d\|, \|\Sigma_1^{-\nicefrac{1}{2}}\Sigma_2\Sigma_1^{-\nicefrac{1}{2}} - I_d\|)& \text{if } \text{rank}\Sigma_1 = \text{rank}\Sigma_2 = d\\
    \infty              & \text{otherwise}
\end{cases}
\]

\begin{fact} \label{fact:matrices}
    Let $A,B$ be $d \times d$ matrices and suppose that $\|A^{-\nicefrac{1}{2}}BA^{-\nicefrac{1}{2}} - I\| \leq \gamma \leq \nicefrac{1}{2}$. Then $\|B^{-\nicefrac{1}{2}}AB^{-\nicefrac{1}{2}} - I\| \leq 4\gamma$
\end{fact}

\begin{algorithm}[H]
    \caption{Baseline DP Second Moment Estimation}
    \label{alg:base-psm}
    % \hspace*{\algorithmicindent}
     \textbf{Input:} a set of $n$ points $X \subseteq \mathbb{R}^d$, subsamplability parameters $m, \alpha, \beta$,
     %\hspace*{\algorithmicindent} 
     error parameter $\xi \in (0,1)$, privacy parameters $\epsilon, \delta$.
    \begin{algorithmic}[1]
     % Input:
     % Output:
     \STATE Randomly split $X$ into $T = \lfloor \nicefrac{n}{m} \rfloor$ subgroups $X_1, \dots, X_T$ of size $m$.
     \FOR{$t \in [T]$} 
        \STATE $\Sigma_t \gets \frac{1}{m}X_tX_t^T$ 
     \ENDFOR
     \FOR{$t \in [T]$}
        \STATE $q_t \gets \frac{1}{T}|\{t' \in [T]:\text{dist}(\Sigma_t, \Sigma_{t'}) \leq \frac{2\alpha}{1-\alpha}\}|$
     \ENDFOR
     \STATE $Q \gets \frac{1}{T}\sum_{t \in [T]}q_t$
     \STATE $Z \sim \text{TLap}(\nicefrac{2}{T}, \epsilon, \delta)$
     \STATE $\Tilde{Q} \gets Q + Z$
     \IF{$\Tilde{Q} < 0.8 + \frac{2}{T\epsilon}\ln(1 + \frac{e^{\epsilon} - 1}{2\delta})$}
        \STATE fail and return $\perp$
     \ENDIF
     \FOR{$t \in [T]$}
        \STATE $w_t = \min(1, 10\max(0, q_t - 0.6))$
     \ENDFOR
     \STATE $\Hat{\Sigma} \gets \sum_{t \in [T]} w_t\Sigma_t / \sum_{t \in [T]} w_t$
     \STATE $N \sim \mathcal{N}(0, 1)_{d \times d}$
     \STATE $\eta \gets \frac{\alpha}{48C(\sqrt{d} + \sqrt{\ln(\nicefrac{4}{\beta})})}$ \COMMENT{$C$ some large constant}
     \STATE \textbf{return} $\Tilde{\Sigma} = \Hat{\Sigma}^{\nicefrac{1}{2}}(I + \eta N)(I + \eta N)^T \Hat{\Sigma}^{\nicefrac{1}{2}}$
    \end{algorithmic}
    \label{alg:baseline}
\end{algorithm}


\begin{lemma}\label{lem:baseline-utility}(Utility Analysis)
    Let $\Sigma = \frac{1}{n}XX^T$ and set $\eta = \frac{\alpha}{48C(\sqrt{d} + \sqrt{\ln(\nicefrac{4}{\xi})})}$ for a sufficiently large constant $C>0$. Then w.p. $\geq 1-\xi$ Algorithm~\ref{alg:base-psm} returns $\Tilde{\Sigma}$ such that $\text{dist}(\Sigma, \Tilde{\Sigma}) \leq 2\alpha$ given that:
    $$n \geq \frac{10m}{\epsilon}\ln(1 + \frac{e^\epsilon - 1}{2\delta}) \quad \text{and} \quad m \geq \frac{2\beta n}{\xi}$$
\end{lemma}

\begin{proof}
    Indeed, we have that
    \begin{equation*}
    \begin{split}
    \|\Hat{\Sigma}^{-\nicefrac{1}{2}}\Tilde{\Sigma}\Hat{\Sigma}^{-\nicefrac{1}{2}} - I\| & = \|(I + \eta N)(I + \eta N)^T - I\| \\
     & \leq 2\eta \|N\| + \eta^2 \|NN^T\| \\
     & \leq 2\eta C(\sqrt{d} + \sqrt{\ln(\nicefrac{4}{\xi})}) + \eta^2(C(\sqrt{d} + \sqrt{\ln(\nicefrac{4}{\xi})}))^2
    \end{split}
    \end{equation*}
    where we used the fact that $\|N\| \leq C(\sqrt{d} + \sqrt{\ln(\nicefrac{4}{\xi})})$ w.p. $\geq 1-\nicefrac{\xi}{2}$.
    Applying $\eta$ as defined in the lemma gives that:
    $$\|\Hat{\Sigma}^{-\nicefrac{1}{2}}\Tilde{\Sigma}\Hat{\Sigma}^{-\nicefrac{1}{2}} - I\| \leq \nicefrac{\alpha}{12}$$
    Following from Fact~\ref{fact:matrices} we have that:
    $$\|\Tilde{\Sigma}^{-\nicefrac{1}{2}}\Hat{\Sigma}\Tilde{\Sigma}^{-\nicefrac{1}{2}} - I\| \leq \nicefrac{\alpha}{3}$$
    So we have that $\text{dist}(\Tilde{\Sigma}, \Hat{\Sigma}) \leq \nicefrac{\alpha}{3}$.

    \noindent Now we show that $\text{dist}(\Sigma, \Hat{\Sigma}) \leq \alpha$ w.p. $\geq 1 - \nicefrac{\xi}{2}$: \\ Based on the subsamplability assumption, we know that w.p. $\geq (1 - \beta)^T$:
    \[
    \forall t \in [T]:~ \text{dist}(\Sigma_t, \Sigma) \leq \alpha
    \]
    It means that w.p. $\geq (1 - \beta)^T$  all $t \neq t' \in [T]$ satisfy:
    \[
    \left\{
    \begin{aligned}
        \text{dist}(\Sigma_t, \Sigma) \leq \alpha \\
        \text{dist}(\Sigma_{t'}, \Sigma) \leq \alpha
    \end{aligned}
    \right.
    \quad \implies \quad
    \text{dist}(\Sigma_t, \Sigma_{t'}) \leq \frac{2\alpha}{1-\alpha}
    \]
    Hence w.p. $\geq (1 - \beta)^T \geq e^{-\frac{2\beta n}{m}} \geq 1 - \nicefrac{\xi}{2}$ all $t \in [T]$ satisfy:
    \[
    q_t = \frac{1}{T}\left|\left\{t' \in [T]:\text{dist}(\Sigma_t, \Sigma_{t'}) \leq \frac{2\alpha}{1-\alpha}\right\}\right| = 1
    \]
    Finally, $Q = 1 > 0.8 + \frac{2}{T\epsilon}\ln(1 + \frac{e^{\epsilon} - 1}{2\delta})$ w.p. $\geq 1 - \nicefrac{\xi}{2}$ and therefore the algorithm does not fail w.p. $\geq 1 - \xi$.

    Now obviously $\text{dist}(\Sigma, \Hat{\Sigma}) \leq \alpha$ since $\Hat{\Sigma}$ is a weighted average of $\Sigma_t$.

    \noindent So we have that $\text{dist}(\Tilde{\Sigma}, \Hat{\Sigma}) \leq \nicefrac{\alpha}{3}$ and $\text{dist}(\Sigma, \Hat{\Sigma}) \leq \alpha$ w.p. $\geq 1 - \xi$. Applying the $\nicefrac{3}{2}$-approximate triangle inequality for the dist function, we get:
    \[ \|\Sigma^{-\nicefrac{1}{2}}\Tilde{\Sigma}\Sigma^{-\nicefrac{1}{2}} - I\| \leq \frac{3}{2}(\alpha + \frac{\alpha}{3}) = 2\alpha \qedhere \]
\end{proof}

\begin{lemma}\label{lem:baseline-privacy}(Privacy Analysis)
    Suppose that:
    $$n \geq 800m\cdot\left(\max\left\{\sqrt{\frac{2d(d + \nicefrac{1}{\eta^2})}{\epsilon}}, \frac{8d\sqrt{\ln(\nicefrac{2}{\delta})}}{\epsilon}, \frac{8\ln(\nicefrac{2}{\delta})}{\epsilon}, \frac{12\sqrt{d\ln(\nicefrac{2}{\delta})}}{\epsilon\eta}\right\}\right)$$
    Then Algorithm~\ref{alg:base-psm} is $(2\epsilon, 4e^{\epsilon}\delta)$-DP.
\end{lemma}

\begin{proof}
    By basic composition of Truncated Laplace Mechanism and Lemma 3.6 of \cite{ashtiani2022private}.
\end{proof}

\noindent Both Lemma~\ref{lem:baseline-utility} and Lemma~\ref{lem:baseline-privacy} together imply the following theorem:

\begin{theorem}
Let $\xi$, $\epsilon$, $\delta$ be parameters, and let $X \subseteq \mathbb{R}^d$ be a $(m, \alpha, \beta)$-subsamplable set of $n$ points. Then, for Algorithm~\ref{alg:base-psm}, the following properties hold:
\begin{enumerate}
    \item Algorithm~\ref{alg:base-psm} satisfies $(2\epsilon, 4e^{\epsilon}\delta)$-Differential Privacy.
    \item The algorithm returns $\tilde{\Sigma}$ such that $dist(\Sigma, \tilde{\Sigma}) \leq 2\alpha$, where $\Sigma = \frac{1}{n}XX^\top$.
\end{enumerate}
These guarantees hold under the following conditions:
\begin{enumerate}
    \item The dataset size satisfies:
    $$n \geq 800m \cdot \left(\max\left\{
    \sqrt{\frac{2d(d + \nicefrac{1}{\eta^2})}{\epsilon}}, 
    \frac{8d\sqrt{\ln(\nicefrac{2}{\delta})}}{\epsilon}, 
    \frac{8\ln(\nicefrac{2}{\delta})}{\epsilon}, 
    \frac{12\sqrt{d\ln(\nicefrac{2}{\delta})}}{\epsilon\eta}, 
    \frac{\ln\left(1 + \frac{e^\epsilon - 1}{2\delta}\right)}{80\epsilon}
    \right\}\right).$$
    where $\eta = \frac{\alpha}{48C(\sqrt{d} + \sqrt{\ln(\nicefrac{4}{\xi})})}$ for a sufficiently large constant $C>0$.
    \item The subsamplability parameters satisfy $m \geq \frac{2\beta n}{\xi}.$
\end{enumerate}
\end{theorem}

















\section{Finding Initial Parameters}
\label{apx_sec:Initial_parameters}

Our recursive algorithm requires as input two parameters that characterize the ``aspect ratio'' of the input, namely ~-- $R_{\max}$, 
the maximum distance of any point from the origin, and $\lambda_{\min}$, the minimum eigenvalue of the input. These two parameters give us the initial bounds, as they imply that $\lambda_{\min} I \preceq \Sigma \preceq R_{\max}^2 I$.
We detail here the algorithms that allow us to retrieve these parameters. Finding $R_{\max}$ is fairly simple, as it requires us only to apply off-the-shelf algorithms that find an enclosing ball of the $n$ input points (\cite{Nissim_2016, nissim2017clusteringalgorithmscentralizedlocal, mahpud2022differentiallyprivatelineartimefptas}). Finding the minimal eigenvalue is fairly simple as well, and we use a subsample-and-aggregate framework. Details follow.

\paragraph{Finding a Covering Radius of The Data}
\label{subsubsec:finding_R_max}

% \begin{theorem}[(GoodRadius) from \cite{Nissim_2016}]
%     Let $X = (X_1, \dots, X_n) \in \R^d$.
%     Suppose the smallest ball in $\R^d$ that contains all the points in $X$ has radius $r_{opt}$. Then for all $\epsilon, \delta, \beta > 0$ there exists a poly$(n, d, log |X|)$ $(\epsilon, \delta)$-differentially private algorithm (GoodRadius) that takes $X$ as input, and outputs $r$ such that $r \leq 4r_{opt}$ w.p. $\geq 1 - \beta$.
% \end{theorem}

\begin{definition}
     A \emph{1-cluster problem} $(X^d, n, t)$ consists of a $d$-dimensional domain $X^d$ and parameters $n \geq t$. We say that algorithm $\mathcal{M}$ solves $(X^d, n, t)$ with parameters $(\Delta, \omega, \beta)$ if for every input database $S \in (X^d)^n$ it outputs, with probability at least $1 - \beta$, a center $c$ and a radius $r$ such that: (i) the ball of radius $r$ around $c$ contains at least $t - \Delta$ points from $S$; and (ii) $r \leq w \cdot r_{\text{opt}}$, where $r_{\text{opt}}$ is the radius of the smallest ball in $X^d$ containing at least $t$ points from $S$.
\end{definition}

\begin{theorem}[\cite{nissim2017clusteringalgorithmscentralizedlocal}]
    Let $n, t, \beta, \epsilon, \delta$ be s.t.
    \[
    t \geq O\left(\frac{n^{0.1}\cdot\sqrt{d}}{\epsilon}\log\left(\frac{1}{\beta}\right)\log\left(\frac{nd}{\beta\delta}\right)\sqrt{\log\left(\frac{1}{\beta\delta}\right)}\cdot 9^{\log^*(2|X|\sqrt{d})}\right)
    \]
    There exists an $(\epsilon, \delta)$-differentially private algorithm that solves the $1$-cluster problem $X^d, n, t$ with parameters $(\Delta, \omega)$ and error probability $\beta$, where $\omega = O(1)$ and
    \[
    \Delta = O\left(\frac{n^{0.1}}{\epsilon}\log\left(\frac{1}{\beta\delta}\right)\log\left(\frac{1}{\beta}\right)\cdot 9^{\log^*(2|X|\sqrt{d})}\right)
    \]
\end{theorem}

In words, there exists an efficient $(\epsilon, \delta)$-differentially private algorithm that (ignoring logarithmic factors) is capable of identifying a ball of radius $O(r_{opt})$ containing $t - \tilde O(\frac{n^{0.1}}{\epsilon})$ points, provided that $t \geq \tilde O(n^{0.1}\cdot\nicefrac{\sqrt{d}}{\epsilon})$.

