%      \State $\hat\lambda_{min} \gets \rm PrivateMedian(\lambda_{min}^1, ..., \lambda_{min}^T)$
%      \State \Return $(\hat\lambda_{max}, \hat\lambda_{min})$
%     \end{algorithmic}
% \end{algorithm}

The algorithm described in \cite{kamath2022privatecomputationallyefficientestimatorunbounded} (Section 3) privately estimates all eigenvalues of the second moment matrix of the data. However, for the purpose of this study, we focus solely on identifying the minimum eigenvalue while maintaining the privacy guarantees provided by the algorithm. To adapt the algorithm, we modify its structure to prioritize the computation of the minimum eigenvalue directly, rather than estimating the full spectrum of eigenvalues. This simplification not only reduces computational overhead but also aligns with the specific objectives of our work. Below, we detail the adjusted methodology and highlight the changes made to the original theorem.

\begin{algorithm}[H]
    \caption{DP Minimum Eigenvalue Estimator}
    \label{alg:min-eigenvalue}
     %\hspace*{\algorithmicindent}
     \textbf{Input:} a set of $n$ points $X \subseteq \mathbb{R}^d$, subsamplability parameters $m, \alpha, \beta$, error parameter $\xi \in (0,1)$, privacy parameters $\epsilon, \delta$.
    \begin{algorithmic}[1]
     \STATE Randomly split $X$ into $T = \lfloor \nicefrac{n}{m} \rfloor$ subgroups $X_1, \dots, X_T$ of size $m$.
     \FOR{$t \in [T]$} 
        \STATE Let $\lambda_{min}^t$ be the minimum eigenvalue of $\frac{1}{m}X_tX_t^T$.
     \ENDFOR
     \STATE $\Omega \gets \{\dots, [(1-\alpha)^2, 1-\alpha), [1-\alpha, 1), [1, \frac{1}{1-\alpha}), [\frac{1}{1-\alpha}, \frac{1}{(1-\alpha)^2}), \dots\} \cup \{[0,0]\}$.
     \STATE Divide $[0, \infty)$ into $\Omega$.
     \STATE Run $(\epsilon, \delta)$-DP histogram on all $\lambda_{min}^t$ over $\Omega$.
     \IF{no bucket is returned}
        \STATE \textbf{return}  $\perp$.
     \ENDIF 
     \STATE Let $[\ell, u]$ be a non-empty bucket returned and set $\tilde\lambda_{min} \gets \ell$.
     \STATE \textbf{return} $\tilde\lambda_{min}$
    \end{algorithmic}
\end{algorithm}

\begin{theorem}{((Differentially Private EigenvalueEstimator) from \cite{kamath2022privatecomputationallyefficientestimatorunbounded})}
    For every $\epsilon, \delta, \xi > 0$, the following properties hold for Algorithm~\ref{alg:min-eigenvalue}:
    \begin{enumerate}
        \item The algorithm is $(\epsilon, \delta)$-differentially private.
        \item The algorithm runs in time $\text{poly}(\nicefrac{n}{m}, \ln(\nicefrac{1}{\epsilon\xi}))$
        \item if:
        \[
        n \geq O\left(\frac{m\ln(\nicefrac{1}{\delta\xi})}{\epsilon}\right) \quad \text{and} \quad m \geq \frac{2\beta n}{\ln{(\frac{1}{1 - \nicefrac{\xi}{2}})}}
        \]
        then it outputs $\tilde\lambda_{min}$ such that with probability at least $1 - \xi$, $\tilde\lambda_{min} \in [(1-\alpha)\lambda_{min}, (1+\alpha)\lambda_{min}]$ where $\lambda_{min}$ is the minimum eigenvalue of $\frac{1}{n}XX^T$.
    \end{enumerate}
\end{theorem}

\begin{proof}
    Privacy and running time is proven by the theorem of stability-based private histograms (See Lemma 2.6 in \cite{kamath2022privatecomputationallyefficientestimatorunbounded}). Now, we move on to the accuracy guarantees. By subsamplability, with probability at least $1 - \nicefrac{\xi}{2}$, the non-private estimates of $\lambda_{min}$ must be within a factor of $(1 \pm \alpha)$ due to our subsample complexity. Therefore, at most two consecutive buckets would be filled with $\lambda_{min}^t$’s. Due to our sample complexity and private histograms utility, those buckets are released with probability at least $(1 - \nicefrac{\xi}{2})$, which proves our theorem.
\end{proof}



