\begin{lemma}\label{apx_lem:eigenvalues}(Lemma~\ref{lem:eigenvalues} restated.)
Given $X = \{X_1,...,X_n\} \subset \mathbb{R}^d$, $C > 0, c > 0, 0 < \eta < 1, 0 < \psi < 1$, and $\kappa \geq 1$ s.t. $I \preceq \Sigma \preceq \kappa I$ where $\Sigma = \frac{1}{n}X X^T$. Let $V \gets \text{Span}(\{v_i: \lambda_i \geq \psi \kappa)$ and $\Pi \gets \eta \Pi_V + \Pi_{V^\perp}$. Given that:
$n \geq O\left(m\sqrt{\frac{dT}{\rho}} \ln(\nicefrac{T}{\xi})\right)$
Then:
\[ (1 - \frac{1}{\eta^2\psi - c} \cdot \frac{1}{\kappa})I \preceq \Pi\Sigma\Pi \preceq (\eta^2 + \psi + 2c)\kappa I \]
In particular, if $\kappa > C$ for some constant $C$ then:
\[ I \preceq \frac{1}{(1 - \frac{1}{\eta^2\psi - c})}\Pi\Sigma\Pi \preceq \frac{\eta^2 + \psi + 2c}{(1 - \frac{1}{C(\eta^2\psi - c)})}\kappa I \]
\end{lemma}



\begin{proof}
    First we prove the upper bound.
        Note that $\|\Pi\Sigma\Pi\|_2 = \|\Pi(\Tilde{\Sigma} - N)\Pi\| \leq \|\Pi\Tilde{\Sigma}\Pi\| + \| N \|$. So we bound the two terms separately. 
        Using Fact~\ref{fact:gaussian-bound} with $A = O(\frac{1}{d}\ln(\nicefrac{1}{\xi}))$ for sufficiently large $n$ we get $\| N \|_2 \leq c\kappa$ w.p. $1 - \nicefrac{\xi}{2}$.
        Additionally $\|\Pi\Tilde{\Sigma}\Pi\|_2 \leq \eta^2 \|\Pi_V \Tilde{\Sigma}\Pi_V\| + \|\Pi_{V^\perp}\Tilde{\Sigma}\Pi_{V^\perp}\| \leq \eta^2 (\kappa + c) + \psi \kappa \leq (\eta^2 + \psi + c)\kappa$.
        So overall,
        \[ \|\Pi\Sigma\Pi\|_2 \leq (\eta^2 + \psi + 2c)\kappa \]

    Next we prove the lower bound.
        Let $u \in \mathcal{S}^{d-1}$. Our lower bound requires we show that $u^T\Pi \Sigma \Pi u \geq (1 - \frac{1}{\eta^2\psi - c} \cdot \frac{1}{\kappa}) $.
        We consider two cases:

        \begin{itemize}
            \item Case 1: \quad $\|\Pi_V u\|^2 < \frac{1}{\eta^2\psi - c} \cdot \frac{1}{\kappa}$.
            \\Since $\|\Pi_{V^\perp} u\|^2 + \|\Pi_V u\|^2 = 1$ we have $\|\Pi_{V^\perp}u\|^2 > (1 - \frac{1}{\eta^2\psi - c} \cdot \frac{1}{\kappa})$, hence, using the fact that $\Sigma \succeq I$ we have that
            \[u^T\Pi \Sigma \Pi u \geq \|\Pi u\|^2 \geq \|\Pi_{V^\perp} u\|^2 > (1 - \frac{1}{\eta^2\psi - c} \cdot \frac{1}{\kappa})\]
            \item Case 2: \quad $\|\Pi_V u\|^2 \geq \frac{1}{\eta^2\psi - c} \cdot \frac{1}{\kappa}$.\\
            Note that $u^T\Pi \Sigma \Pi u = u^T\Pi (\Tilde{\Sigma} - N) \Pi u = u^T\Pi \Tilde{\Sigma} \Pi u - u^T\Pi N \Pi u$. So we bound each term separately. We know that
            \[u^T\Pi \Tilde{\Sigma} \Pi u \geq u^T\Pi_V \Tilde{\Sigma} \Pi_V u \geq \eta^2\psi\kappa \|\Pi_V u\|^2\]
            Additionally, based on the bound on the spectral norm of $N$ we have that  ~ $u^T\Pi N \Pi u \leq c \kappa \|\Pi u\|^2 \leq c \kappa \|\Pi_V u\|^2$. 
            So overall:
            \[ u^T\Pi \Sigma \Pi u \geq (\eta^2\psi - c)\kappa \|\Pi_V u\|^2 \geq 1 \qedhere \]
        \end{itemize}

    \end{proof}

\begin{claim}\label{appendix:proof_bad-points-fraction}(Claim~\ref{clm:bad-points-fraction} restated.)
    Analogously to Definition~\ref{def:tail}, fix any $m'\geq m$ and define $P_{\text{tail}}(m') = \{x \in X:~ \exists u \in \R^d:~ (x^Tu)^2 > m'(1+\alpha)\frac 1 n \sum_i (x_i^T u)^2\}$.
    Then it holds that 
    \[ \Pr_{x \in_R X}[x \in P_{\text{tail}}(m')] \leq \frac{\beta + \beta^2}{m'}. \]
\end{claim}

\begin{proof}
    Let $x \in X$ be a datapoint and $\hat{X} = \{\hat{X}_1, \dots, \hat{X}_{m'}\}$ be a subsample of $m'$ points i.i.d from $X$. From subsamplability we know that: 
    $ \Pr[ (1-\alpha)\Sigma \preceq \hat \Sigma \preceq (1+\alpha)\Sigma  ] \geq 1-\beta $
    where $\Sigma = \frac{1}{n}\sum\limits_{x\in X}x x^T$ and $\hat \Sigma = \frac {1} {m'} \sum\limits_{i \in [m']} \hat X_i \hat X_i^T$. In other words:
    \[ \Pr[\forall u \in \R^d:~ (1-\alpha)u^T \Sigma u \leq u^T \hat{\Sigma} u \leq (1+\alpha)u^T \Sigma u] \geq 1 - \beta. \]
    Clearly, if even a single $x_0\in P_{\text{tail}}(m')$ belongs to $\hat X$ then we'd have that for some direction $u$ we have
    \[  u^T \hat{\Sigma} u  = \frac 1 {m'} \sum_{i}  (\hat X_i^T u)^2 \geq \frac 1 {m'} (x_0^T u)^2 > (1+\alpha)u^T \Sigma u \] contradicting subsamplability. It follows that w.p. $\geq 1-\beta$ no point in $\hat X$ belongs to $P_{\text{tail}}(m')$. Thus, if we denote $p = \Pr\limits_{x \in_R X}[x \in P_{\text{tail}}(m')]$ then we get that
    $
        1-\beta \leq (1-p)^{m'}
    $.
    Using known inequalities we get $e^{-pm'} \geq (1-p)^{m'} \geq 1-\beta \geq e^{-\beta-\beta^2}$ therefore $p \leq \frac{\beta+\beta^2}{m'}$.
\end{proof}


\begin{lemma}\label{appendix:proof_eigenvalue-without-tail}(Lemma~\ref{lem:eigenvalue-without-tail} restated.)
    Let $X$ be a $(m,\alpha,\beta)$-subsamplable with  $\beta \leq \frac{\alpha}{4(1+\alpha)\log(\frac{R^2}{(1+\alpha)m})}$. Let $P = X \setminus P_{tail}$. Then:
    \[ \forall u \in \R^d:~ \frac{1}{n}\sum\limits_{x \in P} \innerproduct{x}{u}^2 \geq (1-\alpha)\frac{1}{n}\sum\limits_{x \in X} \innerproduct{x}{u}^2\]
\end{lemma}
\vspace{-5mm}


\begin{proof}
Fix direction $u$, and denote $\lambda^P = \frac{1}{n}\sum\limits_{x \in P} \innerproduct{x}{u}^2$ and $\lambda = \frac{1}{n}\sum\limits_{x \in X} \innerproduct{x}{u}^2$. Our goal is to prove that $\lambda - \lambda^P \leq \alpha\lambda$. 

Assume that $P_\text{tail}$ holds a $p$-fraction of $X$, and denote also $\lambda^{\text{tail}} = \frac{1}{|P_{\text{tail}}|}\sum\limits_{x \in P_{\text{tail}}} \innerproduct{x}{u}^2$. Hence:
    \[
    \lambda = p\lambda^{\text{tail}} + \lambda^P \implies \lambda - \lambda^P = p\lambda^{\text{tail}}
    \]
    which implies that our goal is to prove that $p\lambda^{\text{tail}} \leq \alpha \lambda$.

    Now split the interval $[(1 + \alpha)m\lambda, R^2]$, the interval of $P_{\text{tail}}$, into buckets $B_0, B_1, B_2, ..., B_k$ where
    \[
     B_i = \big[2^i(1 + \alpha)m\lambda, 2^{i+1}(1 + \alpha)m\lambda\big)
    \] and $k = \log(\frac{R^2}{(1+\alpha)m\lambda}) \leq \log(\frac{R^2}{(1+\alpha)m})$, and clearly we have $\Pr\limits_{x \in X}[\innerproduct{x}{u}^2>m(1+\alpha)\lambda] = \Pr\limits_{x \in X}[x \in \bigcup\limits_{i=0}^{k} B_i]$.
    Recall that Claim~\ref{clm:bad-points-fraction} implies that for any $i$ we can set $m' = 2^i m$ and get:
    \[
    \Pr\limits_{x \in X}[x \in B_i] \leq \frac{\beta + \beta^2}{2^i m}
    \]
    Now we can bound $p\lambda^{P_\text{tail}}$ using $B_i$: 
    \begin{equation*}
    \begin{split}
    p\lambda^{\text{tail}} & \leq \sum\limits_{i=0}^{k} \Pr\limits_{x \in X}[x \in B_i] \cdot 2^{i+1}(1 + \alpha)m\lambda \\
    & \leq \sum\limits_{i=0}^{k} \frac{\beta + \beta^2}{2^i m} \cdot 2^{i+1}(1 + \alpha)m\lambda
     \leq 2\beta\cdot2k(1+\alpha)\lambda
    \end{split}
    \end{equation*}
    which is upper bounded by $\lambda$  for $\beta \leq \frac{\alpha}{4(1+\alpha)k}$.
\end{proof}

\begin{lemma}\label{appendix:proof_shrinking-only-red}(Lemma~\ref{lem:shrinking-only-red} restated.)
At each iteration $t$ of Algorithm~\ref{alg:rec-psme}, only points belonging to $P_{\text{tail}}$ are subjected to shrinking, given that $\alpha < \nicefrac{1}{2}$, $\psi = \frac{1}{10m}$ and $c = \frac{1}{80m}$.
\end{lemma}


\begin{proof}
The proof works by induction on the iterations of the algorithm. Clearly, at $t=0$, before the algorithm begins, no points were subjected to shrinking so the argument is vacuously correct.

Let $t \leq T$ and let $x \in X^t$ denote a point that undergoes shrinking \emph{for the first time} at iteration $t$, with $X^t$ denoting the input of the $t$-th time we apply Algorithm~\ref{alg:rec-psme}. 
Our goal is to show that $x$ stems from a point in $P_{\text{tail}}$. Since $x$ hasn't been shrunk prior to iteration $t$, then there exists some $x_i$ in the original input such that $x=  \Lambda^t x_i$ for the linear transformation $\Lambda^t = \Pi^t \cdot \Pi^{t-1} \cdot ... \cdot \Pi^1$. Our goal is to show that $x_i \in P_{\text{tail}}$.

We assume $x$ is shrunk at iteration $t$. This shrinking happens since  $x^T \Pi_{V^\perp} x > \tfrac 3 7 R^2$. With $\alpha \leq \frac{1}{2}$ we have $\frac{3}{7} \geq \frac{1+\alpha}{4}$, then it follows that $x$ satisfies:
\[
x^T \Pi_{V^\perp} x > \frac{1}{4}(1+\alpha)R^2 = \frac{1}{4}(1+\alpha)\kappa,
\]
For the given parameters $\psi$ and $c$, observe that:
\[
x^T \Pi_{V^\perp} x >\frac{1}{4}(1+\alpha)\kappa >2m(1+\alpha)(\psi+c)\kappa + c\kappa.
\]
Recall that $V^\perp$ denotes the subspace spanned by all eigenvectors of $\tilde{\Sigma} = \Sigma + N$ corresponding to eigenvalues $\leq \psi\kappa$ and that $\|N\| \leq c\kappa$. 
Now denote $U^\perp$ the subspace spanned by all eigenvectors of $\Sigma$ corresponding to eigenvalues $\leq (\psi+c)\kappa$. By Weyl's theorem it holds that
\[  x^T \Pi_{U^\perp} x \geq x^T \Pi_{V^\perp} x - c\kappa \geq 2m(1+\alpha)(\psi+c)\kappa \]
Thus we infer the existence of $u \in U^\perp$ (unit length vector in the direction $\Pi_{U^{\perp}}x$) such that:
\[
(x^T u)^2 > 2m(1+\alpha)(\psi+c)\kappa
.\]
But as $U^{\perp}$ is spanned by all eigenvalues $\leq (\psi+c) \kappa$ of $\Sigma$ then it holds that $\frac 1 n \sum_{x\in X^t} (x^T u)^2 \leq (\psi+c) \kappa$, so 
\begin{equation}(x^T u)^2 > 2m(1+\alpha) \cdot \frac 1 n \sum_{x\in X^t} (x^T u)^2 \label{eq:x_is_large}\end{equation}

Now recall that $x$ undergoes shrinking for the first time at iteration $t$. That means that there exists some $x_i$ in the original input such that $x=  \Lambda^t x_i$ for the linear transformation $\Lambda^t = \Pi^t \cdot \Pi^{t-1} \cdot ... \cdot \Pi^1$. Moreover, by the induction hypothesis all points that were shrunk upto iteration $t$ are from $P_{\text{tail}}$. So for any point  $z\in X^t \setminus P_{\text{tail}}$ it holds that $z = \Lambda^t y$ for the corresponding $y$ in the original input $X$. We get that
\resizebox{0.5\textwidth}{!}{
$\frac 1 n \sum\limits_{x\in X^t} (x^T u)^2 \geq  \frac 1 n \sum\limits_{x\in X^t\setminus P_{\text{tail}}} (x^T u)^2 =  \frac 1 n \sum\limits_{y\in X\setminus P_{\text{tail}}} (y^T \Lambda^T u)^2$.
}

We now apply Lemma~\ref{lem:eigenvalue-without-tail} to infer that
\begin{align*}
\frac 1 n \sum\limits_{y\in X\setminus P_{\text{tail}}} (y^T \Lambda^T u)^2 &\geq (1-\alpha) \frac 1 n \sum\limits_{y\in X} (y^T \Lambda^T u)^2 \geq \frac 1 {2n} \sum\limits_{y\in X} (y^T \Lambda^T u)^2
\end{align*}
 seeing as $\alpha \leq\nicefrac 1 2$. Plugging this into Equation~\eqref{eq:x_is_large} we 
\[  \innerproduct{x_i}{\Lambda^T u}^2 =  (x^T u)^2  > m(1+\alpha) \cdot \frac 1 {n} \sum_{y\in X} \innerproduct{y} {\Lambda^T u}^2 \] which by definition proves that $x_i$ belongs to $P_{\text{tail}}$.
\end{proof}

\begin{corollary}\label{appendix:proof_always_least_eigenvalue_of_1}(Corollary~\ref{cor:always_least_eigenvalue_of_1} restated.)
    In all iterations of the algorithm it holds that $\Sigma \succeq I$, namely, that the least eigenvalue of the second moment matrix of the input is $\geq 1$.
\end{corollary}

\begin{proof}
    Again, we prove this by induction of $t$, the iteration of Algorithm~\ref{alg:rec-psme}. In fact, denoting $X^t$ as the input of of Algorithm~\ref{alg:rec-psme} at iteration $t$, then we argue that the least eigenvalue of the matrix $\frac 1 n \sum\limits_{x\in X^t \setminus P_{\text{tail}}} x x^T$ is at least $1$.

    Consider $t=0$, prior to the execution of Algorithm~\ref{alg:rec-psme} even once. Apply Lemma~\ref{lem:eigenvalue-without-tail} with $u$ being the direction of the least eigenvalue of $\Sigma$, and we get that
    $
    \frac 1 n \sum\limits_{x\in X \setminus P_{\text{tail}}} x x^T  \geq (1-\alpha) \cdot 1
    $.
    Observe that Algorithm~\ref{alg:dpsme} invokes Algorithm~\ref{alg:rec-psme} on the input multiplied a $\frac 1 {1-\alpha}$-factor, and so it holds that $\frac 1 n \sum\limits_{x\in X^0 \setminus P_{\text{tail}}} x x^T\geq 1$ for $X^0$, the very first input on which Algorithm~\ref{alg:rec-psme} is run.

    Consider now any intermediate $t$, where we assume that input satisfies $\frac 1 n \sum\limits_{x\in X^t \setminus P_{\text{tail}}} x x^T\geq 1$. We can apply Lemma~\ref{lem:eigenvalues} and Corollary~\ref{cor:eigenvalues} solely to the points in $X^t \setminus P_{\text{tail}}$ and have that $\frac 1 n \sum\limits_{x\in X^t \setminus P_{\text{tail}}} \frac 8 7  x \Pi x^T\geq 1$. Since Lemma~\ref{lem:shrinking-only-red} asserts no point in $X^t \setminus P_{\text{tail}}$ is shrunk then we get that the required also holds at the invocation of the next iteration.
\end{proof}

