    where 
    \begin{align} \label{eq:one_step_optimal_stage_cost}
        \opt{\ell_i}(x_i, r_i) \coloneqq \min_{u_i} \quad & \ell_i(x_i, u_i, r_i) \quad 
        \textrm{s.t.} \quad  x_i \in \X_i, u_i \in \U_i.
    \end{align}

    is minimized by the input $\opt{u}_i = u_i^r$ .

    Additionally, there exist $k_{0,i}^l, k_{1,i}^l > 0$ such that for any two reachable references $\rti, \hat{r}_{\subi}$, it holds
    \begin{equation*}
        \ell_i(x_i, u_i, \rti[k]) \leq k_{0,i}^l \ell_i(x_i, u_i, \hat{r}_{\subi[k]}) + k_{1,i}^l \mynorm{\rti[k] - \hat{r}_{\subi[k]}}^2.
    \end{equation*}
\end{assumption}
\end{comment}

The following tracking MPC formulation is used to track the reachable reference $\rti$ for agent $i$.
\begin{subequations} \label{eq:tracking_feasible_trajectory}
\begin{align} 
    \VNi(x_{i,t}, \rt, \W_{i,\cdot|t}) =& \, \min_{\uti} \JNi(\xti, \uti, \rti) \\
    \textrm{s.t.} \quad & \xti[0] = x_{i,t},  \\
    & \xti[k+1] = f(\xti[k], \uti[k]), \\
    \label{mpc_state_and_input_constraints}
    & \xti[k] \in \X_i, \uti[k] \in \U_i  \\ 
    \label{mpc_partition_constraints}
    & p_{i,k \mid t} := C x_{i,k \mid t} \in \Wbar_{i,k \mid t},\\ 
    & k = 0, \ldots, N_i - 1.
\end{align}
\end{subequations}
Solving \eqref{eq:tracking_feasible_trajectory} yields an input trajectory $\optt{\uti}$ and a corresponding state trajectory $\optt{\xti}$ of length $N_i$. The loop is closed by applying the first input of $\optt{\uti}$, i.e.
\begin{equation} \label{eq:closed_loop_standard_tracking}
    x_{i,t+1} = f(x_{i,t}, \optt{\uti[0]}).
\end{equation}

We further require a local stabilizability condition \cite[Assumption 1]{grune2017nonlinear} for the discussion on the stability properties of the tracking MPC.
\begin{assumption} \label{assumption:local_controllability}
    There exist $\gamma_i, c_i > 0$ such that for any \mbox{$N_i \in \mathbb{N}$}, any reachable reference $\rti$, and any $x_{i,t}$ with \mbox{$\mynorm{x_{i,t}-x_{i,0|t}^r}^2_{Q_i} \leq c_i$}, we have 
    \begin{equation*} \label{eq:local_controllability}
        \VNi(x_{i,t}, \rti) \leq \gamma_i \mynorm{x_{i,t} -x_{i,0|t}^r}^2_{Q_i} .
    \end{equation*}
\end{assumption}
Note that Assumption \ref{assumption:local_controllability} is valid if the linearized
dynamics are stabilizable \cite{grune2017nonlinear}.

Furthermore, the following theorem summarizes the properties of the tracking MPC

\begin{theorem} \label{theorem:stability_of_tracking_mpc}
    (\cite[Thm.~1]{koehlerECO})
    Let Assumption~\ref{assumption:local_controllability} hold, suppose that $r_{i,\cdot|t}$ is a reachable reference (Def.~\ref{def:reachable_reference}) with $r_{i,\cdot|t+1}:=r_{i,\cdot+1|t}$, and consider an initial condition satisfying $\VNi(x_{i,t}, \rti) \leq V_{\max,i}$ at $t=0$. Then, for any constants $V_{\max,i}>0$, $\alpha_{N,i} \in (0,1)$, $\Bar{\gamma}_i \coloneqq \max\left\{\gamma_i, \frac{V_{\max,i}}{c_i}\right\}$, there exists a horizon $N_{0,i}\in\mathbb{N}$, such that for all $N_i\geq N_{0,i}$ Problem~\eqref{eq:tracking_feasible_trajectory} is recursively feasible, the closed-loop system~\eqref{eq:closed_loop_standard_tracking} converges exponentially to the reachable reference $\rti$, and the value function satisfies
    \begin{subequations}
    \begin{align}
    \begin{split} \label{eq:smth}
        &\VNi(x_{i,t}, \rti) \leq \Bar{\gamma}_i \mynorm{x_{i,t} - x_{i,0|t}^r}^2_{Q_i},\\
    \end{split}\\
    \begin{split} \label{eq:lyapunov_decrease_standard_tracking}
     &\VNi(x_{i,t+1}, \rtiplus) - \VNi(x_{i,t}, \rti) \\
    & \quad \quad \leq - \alpha_{N,i} \ell_i(x_{i,t}, \opt{\uti[0]}, \rti[0]).
    \end{split}
    \end{align}
    \end{subequations}
%    Let Assumption~\ref{assumption:local_controllability} hold, and consider any constants $V_{\max,i}>0$, $\Bar{\gamma}_i \coloneqq \max \{\gamma_i, \frac{V_{\max,i}}{c_i}\}$ and $\alpha_{N,i} \in (0,1)$. Further, there exists an $N_{0,i} \in \mathbb{N}$ such that for all $N_i \geq N_{0,i}$ it holds that $\VNi(x_{i,t}, \rti) \leq V_{\max,i}$ at $t=0$.
%    Then, problem \eqref{eq:tracking_feasible_trajectory} is recursively feasible, and the closed-loop system~\eqref{eq:closed_loop_standard_tracking} converges exponentially to the reachable reference $\rti$.     
\end{theorem}

