\subsection{Periodic Coverage Planner}
\label{section:decoupled_coverage_planner}
It is important to note that running the reference planner independently of the tracking MPC results in references that do not satisfy the conditions outlined in Theorem~\ref{theorem:stability_of_tracking_mpc}, thereby losing all closed-loop guarantees of the tracking MPC. For this reason, we leverage the following proposition.
\begin{proposition}
\label{proposition:coupling_constraint}
Let Assumption~\ref{assumption1} hold and consider the closed-loop system according to Algorithm~\ref{alg:decoupled_coverage_control}. There exists a constant $\LipV>0$ such that, given a reachable reference $\opt{r}_{\subi}$ and partition sequence $\mathbb{W}_{i, \sub}$, any new reachable reference trajectory $\opt{r}_{\subiplusk}$ satisfying 
\begin{align} \label{eq:periodic_coupling_constraint_derivation}
\begin{split}
    & \mynorm{\opt{r}_{\subi[K:K+N]} - \opt{r}_{\subiplusk[0:N]}}\\
    &\quad\leq  \frac{1}{\LipV} \left( V_{\max, i} - \left( 1 - \frac{\alpha_{N,i}}{\gammabari} \right)^K \VNit  \right) := \C(\VNit),
\end{split}
\end{align}
with $\VNit = \VNi(x_{i, t}, \opt{r}_{i,\cdot|t},\W_{i,\cdot|t})\leq \Vmaxi$ ensures that at time $t+K$, the optimal cost of the tracking MPC fulfills 
\begin{equation} \label{eq:ref_v_max}
    \VNi(x_{i, t+K}, \opt{r}_{\subiplusk}, \mathbb{W}_{i, \subplusk}) \leq V_{\max, i}.
\end{equation}
\end{proposition}
% we derive an additional \textit{coupling} constraint to \eqref{eq:planner}
\begin{proof}
Given that $\X, \U$ are compact (Ass. \ref{assumption1}), and $\ell_i$ is quadratic as shown in \eqref{eq:bounds_on_stage_cost}, the cost $\JNi$ is Lipschitz continuous in $\rti$ with constant $\LipV > 0$. Given that the feasibility of \eqref{eq:tracking_feasible_trajectory} is independent of $\rti$, $\VNi$ is also Lipschitz with $\LipV$, i.e., for any two references $\rti, \hat{r}_{i, \sub}$ it holds that
%\begin{align}
%\label{eq:lipschitz_of_tracking_cost_wrt_ref}
%\begin{split}
%    | \VNi&(x_{i, t}, \rti, \mathbb{W}_{i,\sub}) - \VNi(x_{i, t}, \hat{r}_{i, \sub}, \mathbb{W}_{i,\sub}) | \\
%    &\leq | \JNi(\xti, \uti, \rti) - \JNi(\xti, \uti, \hat{r}_{i, \sub}) | \\
%    &\leq \LipV \mynorm{\rti[0:N_i] - \hat{r}_{i, \sub[0:N_i]}},
%\end{split}
%\end{align}
%
\begin{align}
\label{eq:lipschitz_of_tracking_cost_wrt_ref}
\begin{split}
\VNi&(x_{i, t}, \hat{r}_{i, \sub}, \mathbb{W}_{i,\sub}) \leq \JNi(\Tilde{x}_{i,\cdot|t}, \Tilde{u}_{i,\cdot|t}, \hat{r}_{i, \sub})\\
&\leq \JNi(\Tilde{x}_{i,\cdot|t}, \Tilde{u}_{i,\cdot|t}, r_{i, \sub}) + \LipV \mynorm{\rti[0:N_i] - \hat{r}_{i, \sub[0:N_i]}}\\
&= \VNi(x_{i, t}, \rti, \mathbb{W}_{i,\sub}) + \LipV \mynorm{\rti[0:N_i] - \hat{r}_{i, \sub[0:N_i]}},
\end{split}
\end{align}
where $(\Tilde{x}_{i,\cdot,t}, \Tilde{u}_{i,\cdot,t})$ is the optimal solution to Problem~\eqref{eq:tracking_feasible_trajectory} for the reference $\rti$. Given this reference, Theorem~\ref{theorem:stability_of_tracking_mpc} ensures the tracking cost decreases exponentially \eqref{eq:lyapunov_decrease_standard_tracking}, i.e., for any time $t+\delta$ with $\delta \in \mathbb{N}$ it holds that
%Given Theorem \ref{theorem:stability_of_tracking_mpc}, the tracking cost shows an exponential decrease over time for a given reference, hence \eqref{eq:lyapunov_decrease_standard_tracking} with Assumption~\ref{assumption:local_controllability} implies that the tracking cost at some time $t+\delta$ with $\delta \geq 0$ can be upper bounded by 
\begin{align}
\begin{split}
\label{eq:fast_coverage_exp_cost_decrease_K_steps}
    \VNi(x_{i, t+\delta},& \opt{r}_{i,\cdot + \delta|t}, \W_{i,\cdot + \delta|t}) \\
    &\leq \left( 1 - \frac{\alpha_{N,i}}{\gammabari} \right)^\delta \VNi(x_{i, t}, \opt{r}_{i,\cdot |t},\W_{i,\cdot|t}).
\end{split}
\end{align}
Finally, \eqref{eq:ref_v_max} follows by combining the previous equations:
\begin{align}
\label{eq:derivation_coupling_constraint}
\begin{split}
     & \quad \VNi(x_{i, t+K}, \opt{r}_{\subiplusk}, \mathbb{W}_{i, \subplusk}) \\
     & \quad \stackrel{\eqref{eq:lipschitz_of_tracking_cost_wrt_ref}}{\leq} \VNi(x_{i, t+K}, \opt{r}_{i,\cdot + K|t}, \W_{i,\cdot + K|t}) \\
     &\quad \quad + \LipV \mynorm{r_{\subi[K:K+N]} - r_{\subiplusk[0:N]}}\\
     & \quad \stackrel{\eqref{eq:fast_coverage_exp_cost_decrease_K_steps}}{\leq} \left( 1 - \frac{\alpha_{N,i}}{\gammabari} \right)^K \VNi(x_{i, t}, \opt{r}_{i,\cdot | t},\W_{i,\cdot|t}) \\
     &\quad \quad + \LipV \mynorm{\opt{r}_{\subi[K:K+N]} - \opt{r}_{\subiplusk[0:N]}}
     \stackrel{\eqref{eq:ref_v_max}}{\leq} V_{\max, i},
\end{split}
\end{align}
where the last inequality is enforced.
\end{proof}
This proposition ensures that any reference with the \textit{coupling} constraint~\eqref{eq:periodic_coupling_constraint_derivation} lies within the region of attraction of the tracking MPC. 
Hence, we enforce inequality~\eqref{eq:periodic_coupling_constraint_derivation} directly in the computation of a new reference $\opt{r}_{\subiplusk}$:
\begin{subequations} \label{eq:periodic_reference_planner}
\begin{align} 
    %\opt{r}_{\subiplusk}(\rti, \mathbb{W}_{i,\sub}, \VNit) \coloneqq \\
    \opt{r}_{\subiplusk} &\coloneqq
    \argmin_{r_{\subiplusk}} \quad H_i^T(p_{\subiplusk}, \W_{i,\sub[\cdot + K]}, t+K) \\
    \textrm{s.t.} &\quad \eqref{eq:planner1}, \eqref{eq:planner2}, \eqref{eq:planner3}, \eqref{eq:planner4}, \eqref{eq:planner5},\\
     &\quad \mynorm{\opt{r}_{\subi[K:K+N]} - \opt{r}_{\subiplusk[0:N]}} \leq \C(\VNit).\label{eq:periodic_coupling_constraint}
\end{align}
\end{subequations}

%To ensure convergence of the algorithm, $r_{i,\cdot | t + K} = \opt{r}_{i,\cdot + K|t}$ is used if the coverage cost is not strictly lower than that of the previous solution.

Similar to the approach in Problem~\eqref{eq:planner}, we select $\opt{r}_{i,\cdot | t + K} = \opt{r}_{i,\cdot + K|t}$ if the optimal coverage cost is not strictly lower than that of the previous optimal solution.

\subsection{Partition Update Verification}
\label{subsection:partition_update}
Once a new collection of reference trajectories is determined for each agent, we proceed to update the Voronoi partition sequence $\mathbb{W}_{\cdot|t+K}$, which will be utilized in the subsequent iteration at time $t + K$. However, it must be verified that a partition update is feasible for the tracking MPC, given its independence from the planner. This verification is important since the closed-loop trajectories from the tracker generally differ from the planned ones.

Thus, we consider the candidate partition sequence $\hat{\mathbb{W}}_{\cdot|t+K} := \mathbb{W}_{\opt{p}_{\cdot|t+K}}$ computed with (\ref{eq:voronoi_partition}), and define the following candidate trajectory, constructed from the optimal trajectory calculated by the tracking MPC at time $t$
\begin{equation}\label{eq:fast_coverage_candidate_sequence}
\begin{aligned}
    \hat{u}_{i, \cdot | t}   &= [ \optt{\utim[1]},\dots,\optt{\utim[N_i-2]},\: \opt{\utim[N_i-1]} , \opt{\utim[N_i]}], \\
    \hat{x}_{i, \cdot | t}   &= [ \optt{\xtim[1]},\dots, \optt{\xtim[N_i-2]} , \\
    & \quad \optt{\xtim[N_i-1]}, \hat{x}_{i, N_i-1 | t} , \hat{x}_{i, N_i | t}],
\end{aligned}
\end{equation}
where the last elements in the sequence are computed with the reference inputs $\opt{u}$ and we define $\hat{x}_{i, N_i-1 | t}, \hat{x}_{i, N_i | t}$ as 
\begin{align*}
\hat{x}_{i, N_i-1 | t} &= f(\optt{\xtim[N_i-1]}, \opt{\utim[N_i-1]}),\\
\hat{x}_{i, N_i | t} &= f(\hat{x}_{i, N_i-1 | t}, \opt{\utim[N_i]}). 
\end{align*}
Then, we verify whether the candidate reference trajectory of each agent fulfills the following conditions at time $t+K$
\begin{equation} \label{eq:partition_update_condition}
\begin{aligned}
     &\hat{x}_{\subiplusk[k]} \in \mathbb{X}_i, \\
     &C\hat{x}_{\subiplusk[k]}=:\hat{p}_{\subiplusk[k]} \in \hat{\Wbar}_{i,\subplusk[k]},\\
     &\forall k \in \{ 0, \dots, N_i \}.
\end{aligned}
\end{equation}

If the candidate sequences \eqref{eq:fast_coverage_candidate_sequence} fulfill the update conditions~\eqref{eq:partition_update_condition} for all agents, the new partition sequence is applied: $\mathbb{W}_{\cdot|t+K} = \hat{\mathbb{W}}_{\subplusk}$. Otherwise, the previously computed shifted partition sequence is applied, i.e., $\W_{\cdot|t+K} =\W_{\cdot+K|t}$.

\subsection{Theoretical Analysis}
In the following, we provide formal guarantees of Algorithm~\ref{alg:decoupled_coverage_control}. To this end, we introduce the following proposition, which provides a bound on the tracking MPC cost after performing a partition update.

\begin{proposition} \label{proposition:V_max_reference} Let Assumption~\ref{assumption1} hold. Given a partition sequence $\Wsub$ and reachable references $\opt{r}_{\subplusk}$ computed with \eqref{eq:periodic_reference_planner},
    suppose that $\VNi(x_{i,t}, \rti, \Wsubi) \leq \Vmaxi$ for all agents $i \in \M$ and $N_i > \max\{\opt{N}_i, N_{0,i}\}$ with $\opt{N}_i$ from \eqref{eq:n_star_lower_bound}, and let the candidate $\hat{\W}_{\subplusk} := \W_{\opt{p}_{\subplusk}}$ be the corresponding Voronoi partition sequence based on $\opt{r}_{\subplusk}$. If condition \eqref{eq:partition_update_condition} is fulfilled at time $t+K$, then it holds that 
    \begin{equation} \label{eq:V_max_reference_in_new_partitions}
        \VNi(x_{i, t+K}, \opt{r}_{\subiplusk}, \hat{\W}_{\subiplusk}) \leq V_{\max, i}. 
    \end{equation}
\end{proposition}
The proof can be found in Appendix~\ref{appendix:proof_V_max_reference}.
Further, the update conditions in \eqref{eq:partition_update_condition} are guaranteed to be fulfilled in finite time given the following proposition. 
\begin{proposition} \label{proposition:finite_time_partition_update}
%\textcolor{blue}{There exists a uniform bound $\tau$, such that for any $t\in\mathbb{N}$, there exists $t'\in[t,t+\tau]$, such that the reference is updated $r_{\cdot+1|t'}\neq r_{\cdot|t'+1}$ or the candidate trajectory $\hat{x}_{i, \cdot | t' + 1}$~\eqref{eq:fast_coverage_candidate_sequence} fulfill the conditions~\eqref{eq:partition_update_condition} at $t'$.}

     %There exists a uniform bound $\tau$ for any partition sequence $\Wsub$ and reachable references $\rt$ that are fixed, i.e. $r_{\cdot|t+k}=r_{\cdot+k|t} \, \forall k\in \mathbb{N}$, with $\VNi(x_{i,t}, \rti, \Wsubi) \leq \Vmaxi \, \forall i \in \M$, such that the candidate trajectories $\hat{x}_{i, \cdot | t' + 1}$~\eqref{eq:fast_coverage_candidate_sequence} constructed at time $t' \in \left[t, t + \tau \right]$ fulfill the conditions~\eqref{eq:partition_update_condition}.

    % There exists a uniform bound $\tau$, such that for any $t\in\mathbb{N}$, there exists a time $t'\in[t,t+\tau]$ at which the candidate trajectories $\hat{x}_{i, \cdot | t' + 1}$~\eqref{eq:fast_coverage_candidate_sequence} fulfill the conditions~\eqref{eq:partition_update_condition}, given that the reference is fixed, i.e. $r_{\cdot+k|t} = r_{\cdot|t + k} \, \forall k \in \mathbb{N}$, and $\VNi(x_{i,t}, \rti, \Wsubi) \leq \Vmaxi \, \forall i \in \M$.

Let Assumption~\ref{assumption1} and~\ref{assumption:local_controllability} hold. Suppose that after some $t\in\mathbb{N}$, the  
reference trajectories are reachable and fixed, i.e., $r_{i,\cdot|t + k} = r_{i,\cdot+k|t}$ and $\VNi(x_{i,t}, \rti, \Wsubi) \leq \Vmaxi \, \forall i \in \M$ $\forall k \in [0,\tau]$ for some uniform bound $\tau>0$. Then, there exists a time $t'\in[t,t+\tau]$ at which the candidate trajectories $\hat{x}_{i, \cdot | t' + 1}$~\eqref{eq:fast_coverage_candidate_sequence} satisfy the conditions~\eqref{eq:partition_update_condition}.
\end{proposition}
The proof of Proposition~\ref{proposition:finite_time_partition_update} can be found in Appendix~\ref{appendix:close_enough}. 
Subsequently, we can summarize the theoretical guarantees of Algorithm~\ref{alg:decoupled_coverage_control} in
the following theorem.
\begin{theorem} \label{theorem:decoupled_coverage_control}
    Let Assumptions~\ref{assumption1},~\ref{assumption:fintie_centroidal_periodic_configuration},  and~\ref{assumption:local_controllability} hold, and consider the initialization in Algorithm~\ref{alg:decoupled_coverage_control}. Then, for a horizon $N > \max \{N_{0,i}, \opt{N}\}$, it holds that

        \textit{I)} (Recursive feasibility) All the optimization problems in  Algorithm~\ref{alg:decoupled_coverage_control} are feasible for all $t\in\mathbb{N}$.

        \textit{II)} (Constraint satisfaction) The resulting closed-loop trajectories from Algorithm~\ref{alg:decoupled_coverage_control} satisfy the state and input constraints~\eqref{mpc_state_and_input_constraints} and ensure collision avoidance~\eqref{collision_avoidance}.

        \textit{III)} The update condition \eqref{eq:partition_update_condition} is fulfilled after a finite number of time steps.

        \textit{IV)} The closed-loop trajectories converge asymptotically to an optimal periodic configuration (Def. \ref{def:optimal_periodic_configuration}).
\end{theorem}

\begin{proof}\text{ }\\
    \textit{I)} The initial feasibility of the planner is ensured by the steady-state of all agents at $t=0$, which is given at initialization. Additionally, each planner iteration of \eqref{eq:periodic_reference_planner} remains recursively feasible with the candidate trajectory $r_{i,\cdot|t+K} = \opt{r}_{i,\cdot + K|t}$, which always lies within the updated partition sequence $\W_{\opt{p}_{\cdot + K|t}}$, as established by Lemma~\ref{lemma:feasible_partition_update}. 

    Similarly, the tracking MPC is feasible at $t=0$ since the vehicles start at a steady-state. Furthermore, the initial reference trajectory $\opt{r}_{\cdot|0}$ satisfies all constraints in \eqref{eq:tracking_feasible_trajectory}, and ensures that $\VNi(x_{i, 0}, \opt{r}_{i, \cdot|0}, \mathbb{W}_{i, \cdot|0}) \leq V_{\max, i}$. Every subsequent reference computation is reachable and adheres to \eqref{eq:periodic_coupling_constraint}, maintaining the bound $\VNi(x_{i, t}, \rti, \Wsubi) \leq V_{\max, i}$ as of Proposition~\ref{proposition:coupling_constraint}, ensuring that the agents stay within the region of attraction of the tracking MPC. Condition \eqref{eq:partition_update_condition} ensures that the partition update is only performed if feasible, and Proposition \ref{proposition:V_max_reference} guarantees the upper bound $\VNi(x_{i, t+K}, \opt{r}_{\subiplusk}, \W_{\opt{p}_{i,\subplusk}}) \leq V_{\max, i}$ on the tracking cost after any partition update. Therefore, the tracking MPC is recursively feasible by Theorem~\ref{theorem:stability_of_tracking_mpc}. 

    \textit{II)} The tracking MPC \eqref{eq:tracking_feasible_trajectory} enforces the state and input constraints~\eqref{mpc_state_and_input_constraints} at all times. Moreover, the constraints~\eqref{mpc_state_and_input_constraints} guarantee that each agent stays within its tightened partition sequence, thereby ensuring collision avoidance~\eqref{collision_avoidance}.

    \textit{III)} Suppose, for contradiction, that condition~\eqref{eq:partition_update_condition} is not satisfied $\forall t' \in \left [ t, \Tilde{t} \right]$ with some finite $t, \Tilde{t} \in \mathbb{R}_{+}$, and the partitions are not updated, i.e., they are only shifted at each time step with \eqref{eq:shifed_partition_periodic}.

    We first show that the references converge to a fixed trajectory. Since it holds that $\C(V_{i,t}) \geq \C(\Vmaxi) > 0$ with $V_{i,t} \leq \Vmaxi$ from \textit{Part I}, the planner cost is non-increasing with each iteration of \eqref{eq:periodic_reference_planner}, which is lower-bounded by zero. Further, by convention $r^\star_{i,\cdot | t + K} = \opt{r}_{i,\cdot + K|t}$ is used if the coverage cost remains constant with the minimizer. Given the compact constraints in \eqref{eq:periodic_reference_planner}, the sequence of reference updates $\opt{r}_{i, \cdot | t + n K}$ converges for some finite $n \in \mathbb{N}$. Hence, there exists a finite $\hat{t} \geq t$ at which the reference trajectories are not updated, i.e., $\opt{r}_{\cdot | \hat{t} + K} = \opt{r}_{\cdot + K | \hat{t}}$. Note that Problem~\eqref{eq:periodic_reference_planner} is equivalent to the planning Problem~\eqref{eq:planner} with an additional trust-region constraint on the maximal change of the reference~\eqref{eq:periodic_coupling_constraint}. Consequently, constraint \eqref{eq:periodic_coupling_constraint} becomes inactive at the convergence of the reference, and the solution of \eqref{eq:periodic_reference_planner} equivalently represents a local minimizer of \eqref{eq:planner}. For such fixed references, Proposition~\ref{proposition:finite_time_partition_update} guarantees a finite time $\Tilde{t} \in \left[ \hat{t}, \hat{t} + \tau \right]$ such that the closed-loop trajectories converge close enough (Appendix~\ref{appendix:close_enough}) to these references, fulfilling \eqref{eq:partition_update_condition}. This contradicts the initial assumption and hence condition \eqref{eq:partition_update_condition} is met at time $t' \in \left [ t, \Tilde{t} \right]$.

    \textit{IV)} This part follows the steps in the proof of Proposition~\ref{proposition:planner_convergence}. \textit{Part III} shows that the partition update condition \eqref{eq:partition_update_condition} is satisfied for some $t' \in \left [t,\hat{t} + \tau \right ]$. Therefore, the coverage cost using Algorithm~\ref{alg:decoupled_coverage_control} decreases with each iteration, forming a descent function:
    \begin{subequations}
    \begin{align}
    \begin{split} \label{eq:descent_3}
        & H^T(\opt{p}_{\cdot|t}, \W_{\opt{p}_{\cdot|t}}, t)\\
        &\geq H^T(\opt{p}_{\cdot|t+1}, \W_{\opt{p}_{\cdot + 1|t}}, t + 1)\\
        &\geq \dots \geq H^T(\opt{p}_{\cdot|t'}, \W_{\opt{p}_{\cdot + t' - t|t}}, t')\\
    \end{split}\\
    \begin{split} \label{eq:descent_4}
        &\geq H^T(\opt{p}_{\cdot|t'}, \W_{\opt{p}_{\cdot|t'}}, t')\\
        &\geq 0, \forall \, t \in \mathbb{N}.
    \end{split}
    \end{align}
    \end{subequations}
    The first inequalities~\eqref{eq:descent_3} hold from the cost decrease and convergence of the planner \eqref{eq:planner} from \textit{Part III}. The last two inequalities~\eqref{eq:descent_4} follow the argumentation of the proof of Proposition~\ref{proposition:planner_convergence}. 
    Therefore, Algorithm~\ref{alg:decoupled_coverage_control} has a descent function and converges \cite[Prop. 3.3]{Corts2002CoverageCF}.

    %Algorithm~\ref{alg:decoupled_coverage_control} converges to an optimal periodic configuration (Def. \ref{def:optimal_periodic_configuration}) of \eqref{eq:periodic_reference_planner} . 

    Assume, for contradiction, that the configuration that the algorithm converges to is not a minimizer of \eqref{eq:planner}. Convergence to any periodic configuration implies convergence of the partition sequence $\lim_{t\to\infty}  \W_{\opt{p}_{\cdot,t}}$. From \textit{Part III}, the solution of \eqref{eq:periodic_reference_planner} equivalently represents a local minimizer of \eqref{eq:planner} at convergence. Consequently, \eqref{eq:periodic_reference_planner} converges to a minimizer of \eqref{eq:planner} for a fixed periodic partition sequence, contradicting the assumption. Therefore, Algorithm~\ref{alg:decoupled_coverage_control} converges to an optimal periodic configuration of problem \eqref{eq:planner} (Def. \ref{def:optimal_periodic_configuration}).

    With the convergence of the reference trajectories $\lim_{t\to\infty} r^\star_{\cdot|t}$, the closed-loop systems exhibit exponential convergence to these trajectories, as established by Theorem~\ref{theorem:stability_of_tracking_mpc}.
\end{proof}

It follows from Theorem~\ref{theorem:decoupled_coverage_control} that the closed-loop trajectories of Algorithm~\ref{alg:decoupled_coverage_control} converge to an optimal periodic configuration of \eqref{eq:planner} while satisfying all constraints and ensuring collision avoidance.

\section{Nonperiodic coverage MPC}
\label{section:nonperiodic_coverage_control_mpc}
This section presents a practical approach to coverage control for nonperiodic density functions. The proposed method introduces targeted modifications to Algorithm \ref{alg:decoupled_coverage_control}. We start by presenting the following minimization problem solved by the planner at time $t$.
\begin{subequations} \label{eq:nonperiodic_reference_planner}
\begin{align} 
    %\hat{r}_{\subiplusk}(\rti, \mathbb{W}_{i,\sub}, \VNit) \coloneqq \\
    \opt{r}_{\subiplusk} \coloneqq
    \argmin_{r_{\subiplusk}} &\quad H_i^T(p_{\subiplusk}^r, \W_{i,\sub[\cdot + K]}, t+K) \\
    \textrm{s.t.} \quad &(\ref{eq:planner1}), (\ref{eq:planner3}), (\ref{eq:planner4}), (\ref{eq:planner5}),\\
    &x_{i, T - 1 \mid t} = f_i(x_{i,T - 1 \mid t}, u_{i,T - 1 \mid t}), \label{eq:nonperiodic_steady_state_constraint} \\
     &r_{\subi[K:K+N_i]} = r_{\subiplusk[0:N_i]}.\label{eq:nonperiodic_coupling_constraint}
\end{align}
\end{subequations}
Notably, we consider a horizon $T$ which is no longer associated with the period of the density function. To accommodate the nonperiodic density function, we remove the periodic constraint on the reference in \eqref{eq:planner3}. Instead, we enforce a steady-state constraint on the last element of the reference, which will ensure recursive feasibility. Therefore, reference trajectories and partition sequences are defined beyond the horizon $T$, which is necessary for computing a new partition sequence for the next iteration at time $t + K$. Therefore, we define partitions and trajectories shifted by $n \in \mathbb{N}$ steps in time for the nonperiodic algorithm as
\begin{subequations}
\begin{align}
    \label{eq:shifed_partition_nonperiodic}
     \mathbb{W}_{\cdot + n|t} &\coloneqq \{ \mathbb{W}_{\sub[n]}, \dots , 
     \mathbb{W}_{\sub[T-1]}, \dots,  \mathbb{W}_{\sub[T-1]} \},\\
     \label{eq:shifted_reference_nonperiodic}
     r_{\cdot + n|t} &\coloneqq \{ r_{n|t}, \dots,
        r_{T-1|t}, \dots, r_{T-1|t}  \},
\end{align}
\end{subequations}
where the last $n$ elements in the sequence can be repeated since they satisfy the dynamics constraints.

Consequently, we introduce a new scheme which extends Algorithm \ref{alg:decoupled_coverage_control} for nonperiodic density functions.
\begin{algorithm}
\caption{Nonperiodic Coverage Control MPC}
\label{alg:nonperiodic_coverage_control}
  \SetAlgoLined
    \textbf{Algorithm}~\ref{alg:decoupled_coverage_control} with Problem~\eqref{eq:periodic_reference_planner} replaced by Problem~\eqref{eq:nonperiodic_reference_planner}\\
        Shifting operations \eqref{eq:shifted_reference_periodic}-\eqref{eq:shifed_partition_periodic} replaced by \eqref{eq:shifed_partition_nonperiodic}-\eqref{eq:shifted_reference_nonperiodic}
\end{algorithm}

The properties of the previous algorithm are summarized in the following theorem.

\begin{theorem} \label{theorem:decoupled_coverage_control_nonperiodic}
    Let Assumptions~\ref{assumption1} and~\ref{assumption:local_controllability} hold. Then, for a horizon $N_i \geq \max \{N_{0,i}, \opt{N}_i\}$, it holds that

    \textit{I)} (Recursive feasibility) All the optimization problems in  Algorithm~\ref{alg:nonperiodic_coverage_control} are feasible for all $t\in\mathbb{N}$.

    \textit{II)} (Constraint satisfaction) The resulting closed-loop trajectories from Algorithm~\ref{alg:nonperiodic_coverage_control} satisfy the state and input constraints~\eqref{mpc_state_and_input_constraints} and ensure collision avoidance \eqref{collision_avoidance}.

    \textit{III)} The update condition \eqref{eq:partition_update_condition} is fulfilled after a finite number of time steps.

\end{theorem}


\begin{proof} $\quad$\\
    \textit{I)} The optimization problem of the planner \eqref{eq:nonperiodic_reference_planner} is always feasible since the shifted reference $\rti[\cdot + K]$ with \eqref{eq:shifted_reference_nonperiodic} is a feasible candidate for problem \eqref{eq:periodic_reference_planner} at time $t+K$ due to the incorporation of the steady-state. 
    The recursive feasibility of the tracking MPC follows analogously to Theorem~\ref{theorem:decoupled_coverage_control}.\\
    \textit{II)} The argumentation follows the proof of Theorem~\ref{theorem:decoupled_coverage_control}.\\
    \textit{III)} We leverage Proposition~\ref{proposition:finite_time_partition_update} to show the finite-time partition update condition for Algorithm~\ref{alg:nonperiodic_coverage_control}. Although this proposition requires a fixed reference trajectory, we show that this is still valid for a reference trajectory that is updated over time with the consistency constraint in \eqref{eq:nonperiodic_coupling_constraint}. 
    In particular, consider $r = \left [ r_{0:K|t}, r_{0:K|t + K}, \ldots,  r_{0:K|t + nK}\right ] \forall n \in \mathbb{N}$. 
    This reference trajectory is reachable, and the operation of the tracking MPC depends solely on this part of the reference, which can be treated as fixed. Thus, the arguments in Proposition~\ref{proposition:finite_time_partition_update} leveraging the convergence of the tracking MPC remain valid, i.e., the update condition \eqref{eq:partition_update_condition} are satisfied after at most $\tau$ steps. 
%    For instance, consider  the reference trajectory $r = \left [ r_{0:K|t}, r_{0:K|t + K}, \ldots,  r_{0:K|t + nK}\right ] \forall n \in \mathbb{N}$, which is constructed as a concatenation of all references that are applied to the tracking MPC until a partition update occurs. It follows that $r$ is not modified and therefore fixed from the tracking MPC perspective since it only observes the first $N_i + K$ elements of the reference at each time $t$. Additionally, $r$ is still reachable and satisfies the dynamics constraints \eqref{eq:planner1} due to the equality constraint \eqref{eq:nonperiodic_coupling_constraint}. Hence, Proposition~\ref{proposition:finite_time_partition_update} ensures a partition update at time $t' \in \left[t, t + \tau \right]$ for some finite and uniform bound $\tau$.
\end{proof}
