\subsection{Proof of Proposition \ref{proposition:V_max_reference}}
\label{appendix:proof_V_max_reference}
We show that Proposition \ref{proposition:V_max_reference} guarantees the bound $\Vmaxi$ on the tracking cost in \eqref{eq:fast_coverage_exp_cost_decrease_K_steps} after applying a partition update.
\begin{proof}
Consider a reachable reference $\opt{r}_{\subiplusk}$ satisfying constraints in \eqref{eq:periodic_reference_planner} and the candidate partition sequence $\hat{\mathbb{W}}_{\subplusk} := \W_{\opt{p}_{\subplusk}}$. The update condition~\eqref{eq:partition_update_condition} ensures that the candidate sequence $(\hat{x}_{\subiplusk}, \hat{u}_{\subiplusk})$ from \eqref{eq:fast_coverage_candidate_sequence} is a feasible solution to problem~\eqref{eq:tracking_feasible_trajectory} with the updated partition sequence, i.e., $\hat{\mathbb{W}}_{i,\subplusk}$. Further, the following relation holds
\begin{align} \label{eq:bound_on_value_function_with_new_partition}
    \begin{split}
        \VNi&(x_{i, t+K}, \opt{r}_{\subi[\cdot + K]}, \hat{\mathbb{W}}_{i,\subplusk})\\
        &\leq \;  \JNi(\hat{x}_{\subiplusk}, \hat{u}_{\subiplusk},  \opt{r}_{\subi[\cdot + K]}) \\
        & \stackrel{\eqref{eq:fast_coverage_candidate_sequence}}{=} \sum_{k=1}^{N_i-2} \ell_i(\optt{x_{i, k | t+K-1}}, \optt{u_{i, k | t+K-1}},  \opt{r}_{\subi[K + k - 1]}) \\
        & \quad + \ell_i(\optt{x_{i, N_i-1 | t+K-1}}, \opt{u_{i, K+N_i-2| t}},  \opt{r}_{\subi[K+N_i - 2]}) \\ 
        & \quad + \ell_i(\hat{x}_{i, N_i-1 | t+K}, \opt{u_{i, K+N_i-1 | t}},  \opt{r}_{\subi[K+N_i - 1]})  \\
        & \leq \VNi(x_{i, t+K-1},  \opt{r}_{\subi[\cdot + K - 1]}, \mathbb{W}_{i,\cdot + K - 1 | t}) \\
        & \quad - \ell_i(\optt{x_{i, 0 | t+K-1}}, \optt{u_{i, 0 | t+K-1}},  \opt{r}_{\subi[K - 1]}) \\
        & \quad + \ell_i(\hat{x}_{i, N_i-1 | t+K}, \opt{u_{i, K+N_i-1 | t}},  \opt{r}_{i, K+N_i-1 | t}). \\
    \end{split}
\end{align}

We bound the last term in \eqref{eq:bound_on_value_function_with_new_partition} using the bounds on the stage cost~\eqref{eq:bounds_on_stage_cost} and Lipschitz continuity of the dynamics (Asm.~\ref{assumption1}):
    \begin{align*}
    \begin{split}
        &\ell_i(\hat{x}_{i, N_i-1 | t+K}, \opt{u_{i, K+N_i-1 | t}},  \opt{r}_{i, K+N_i-1 | t})\\
        & \quad \stackrel{\eqref{eq:bounds_on_stage_cost}}{\leq} \alpha_{2,i} \mynorm{\hat{x}_{i, N_i-1 | t+K} - \opt{x_{i, K+N_i-1 | t}}}^2 \\ 
        &  \quad \stackrel{\mathrm{Asm.} \ref{assumption1}}{\leq} \alpha_{2,i} \mathcal{L}_{f_i}^2 \mynorm{\optt{x_{i, N_i-1 | t+K-1}} - \opt{x_{i, K+N_i-2 | t}}}^2 \\ 
        &  \quad \stackrel{\eqref{eq:bounds_on_stage_cost}}{\leq} \frac{\alpha_{2,i}}{\alpha_{1,i}} \mathcal{L}_{f_i}^2 \ell_i(\optt{x_{i, N_i-1 | t+K-1}}, \opt{u_{i, K+N_i-2| t}},  \opt{r}_{i, K+N_i-2 | t}) \\
        &  \quad \leq \frac{\alpha_{2,i}}{\alpha_{1,i}} \mathcal{L}_{f_i}^2 \gammabari \left( \frac{\gammabari - 1}{\gammabari} \right)^{N_i} \\
        & \quad  \quad \times\ell_i(\optt{x_{i, 0 | t+K-1}}, \optt{u_{i, 0 | t+K-1}},  \opt{r}_{\subi[K - 1]}),
        % & \leq \frac{\alpha_{2,i}}{\alpha_{1,i}} \mathcal{L}_{f_i}^2 \VNi(x_{i, t+K-1},  \opt{r}_{i, \cdot | t+K-1}, \mathbb{W}_{\cdot | t+K-1, i}),
    \end{split}
\end{align*}

    where the last equation follows from \cite[Eq. (20)-(21)]{koehlerECO}.
    Applying this bound in \eqref{eq:bound_on_value_function_with_new_partition} yields
    \begin{align*}
        \begin{split}
            \VNi(&x_{i, t+K},  \opt{r}_{\subi[\cdot + K]}, \hat{\mathbb{W}}_{i,\subplusk}) \\
            & \leq \VNi(x_{i, t+K-1},  \opt{r}_{\subi[\cdot + K - 1]}, \mathbb{W}_{i,\cdot + K - 1 | t}) \\
            &\quad + \underbrace{ \left( \frac{\alpha_{2,i}}{\alpha_{1,i}} \mathcal{L}_{f_i}^2 \gammabari \left( \frac{\gammabari - 1}{\gammabari} \right)^{N_i} - 1 \right) }_{\eqqcolon \rho_{N,i}} \\
            & \quad \times \ell_i(\optt{x_{i, 0 | t+K-1}}, \optt{u_{i, 0 | t+K-1}},  \opt{r}_{\subi[K - 1]}) \\
            & \leq (1 + \rho_{N,i}) \VNi(x_{i, t+K-1},  \opt{r}_{\subi[\cdot + K - 1]}, \mathbb{W}_{i,\cdot + K - 1 | t}).
        \end{split}
    \end{align*}
    By inspection, it holds that $1 + \rho_{N,i} \leq  1 - \frac{\alpha_{N,i}}{\gammabari}$ for
    \begin{align}
    \label{eq:n_star_lower_bound}
    N_i \geq \opt{N}_i \coloneqq \frac{\ln \left( \frac{\alpha_{2,i}}{\alpha_{1,i}} \mathcal{L}_{f_i}^2 \gammabari^2 \right) - \ln (\gammabari - \alpha_{N,i})}{\ln \gammabari - \ln (\gammabari - 1)}.
    \end{align}
    Then, using \eqref{eq:fast_coverage_exp_cost_decrease_K_steps} for $K-1$ steps, we get
    \begin{align*}
        &\VNi(x_{i, t+K},  \opt{r}_{\subi[\cdot + K]}, \hat{\mathbb{W}}_{i,\subplusk})\\
        &\quad \stackrel{\eqref{eq:fast_coverage_exp_cost_decrease_K_steps}}{\leq}  (1 + \rho_{N,i}) \left( 1 - \frac{\alpha_{N,i}}{\gammabari} \right)^{K-1}
        \VNi(x_{i, t}, \rti, \mathbb{W}_{i,\sub}).\\
        &\quad \stackrel{\eqref{eq:n_star_lower_bound}}{\leq} 
            \left( 1 - \frac{\alpha_{N,i}}{\gammabari} \right)^K
            \VNi(x_{i, t}, \rti, \mathbb{W}_{i,\sub}),
    \end{align*}

    Finally, considering that  $\VNi(x_{i, t}, \rti, \mathbb{W}_{i,\sub}) \leq V_{\max,i}$ and ${\gammabari} > \alpha_{N,i} > 0$, we get \eqref{eq:V_max_reference_in_new_partitions}.
\end{proof}

\subsection{Proof of Proposition \ref{proposition:finite_time_partition_update}}
\label{appendix:close_enough}
We show that the partition update condition is satisfied in finite time by following similar steps to the proof in \cite[Theorem 2]{rickenbach2023}. 
\begin{proof}
We consider a proof of contradiction, i.e., suppose the condition \eqref{eq:partition_update_condition} is not satisfied for $t' \in \left[t, t + \tau \right]$ with some finite $\tau \geq 0$, and hence condition~\eqref{eq:partition_update_condition} can not be satisfied for a fixed reachable reference. Note that for a periodic reference, i.e., $r_{i,\cdot|t+T} = r_{i,\cdot + T|t}\, \forall t > 0$, the reference is defined for an infinite horizon.

First, we derive a constant $V_\epsilon > 0$, such that $V_{i,t'}\leq V_\epsilon$ implies that conditions \eqref{eq:partition_update_condition} are satisfied. Further, we show that we can find some uniform $\tau \geq 0$ for a fixed, reachable reference and any $V_{i,t}\leq \Vmaxi$ we such that $V_{i,t+\tau} \leq V_\epsilon$ $\forall i \in \M$.

\textit{Part 1:} Let $\hat{\W}_{\cdot|t'+1} := \W_{\opt{p}_{\cdot|t'+1}}$. Condition \eqref{eq:partition_update_condition} requires the candidate sequence $(\hat{x}_{i,\cdot|t'+1}, \hat{u}_{i,\cdot|t'+1})$ from \eqref{eq:fast_coverage_candidate_sequence} to lie within the candidate partition sequence $\hat{\Bar{\W}}_{i,\cdot|t'+1}$. According to Lemma~\ref{lemma:feasible_partition_update}, this is ensured if the candidate sequence is close enough to the reference trajectory, i.e., 
\begin{equation}
\label{eq:close_enough}
    \mynorm{ \hat{p}_{i,k|t'+1} - \opt{p_{i,k|t'+1}}} \leq\|C_i\| \mynorm{ \hat{x}_{i,k|t'+1} - \opt{x_{i,k|t'+1}}} \leq \epsilon
\end{equation}
for $k = 0,\ldots, N_i$. Next, we derive a constant $V_\epsilon > 0$ such that this condition holds if $V_{i,t'} \leq V_\epsilon$. For this, we compute the following upper bound.
\begin{align} \label{eq:coverage_mpc_candidate_bound}
    \begin{split}                 
        %&\JNi(\hat{x}_{i,\cdot|t'+1}, \hat{u}_{,\cdot|t'+1}, \opt{r}_{i,\cdot|t'+1})\\
        & \sum_{k=0}^{N_i} \ell_i(\hat{x}_{i,k|t'+1}, \hat{u}_{i,k|t'+1}, \opt{r}_{i,k|t'+1})\\
        & \stackrel{\eqref{eq:fast_coverage_candidate_sequence}}{=} \; \sum_{k=1}^{N_i-2} \ell_i(\optt{x_{i,k|t'}}, \optt{u_{i,k|t'}}, \opt{r_{i,k|t'}}) \\
        & \quad + \ell_i(\optt{x_{i,N_i-1|t'}}, \opt{u_{i,N_i-1|t'}}, \opt{r_{i,N_i-1|t'}}) \\
        & \quad + \ell_i(\hat{x}_{i,N_i -1 | t' + 1}, \opt{u_{i,N_i | t'}}, \opt{r_{i,N_i | t'}}) \\
        & \quad + \ell_i(\hat{x}_{i,N_i | t' + 1}, \opt{u_{i,N_i+1 | t'}}, \opt{r_{i,N_i+1 | t'}}),  \\
        & \leq \JNi(\optt{x_{i, \cdot | t'}}, \optt{u_{i, \cdot | t'}}, \opt{r_{i, \cdot | t'}})\\
        & \quad + \ell_i(\hat{x}_{i,N_i -1 | t' + 1}, \opt{u_{i,N_i | t'}}, \opt{r_{i,N_i | t'}}) \\
        & \quad + \ell_i(\hat{x}_{i,N_i | t' + 1}, \opt{u_{i,N_i+1 | t'}}, \opt{r_{i,N_i+1 | t'}}),\\
    \end{split}
\end{align}
where we denoted $\hat{u}_{i,N_i|t'+1}:=\opt{u_{i,N_i+1|t'}}$.
In particular, the last two terms in \eqref{eq:coverage_mpc_candidate_bound} can be upper bounded using \eqref{eq:bounds_on_stage_cost} and Lipschitz continuity of $f_i$ from Assumption~\ref{assumption1}:  
\begin{align*}
\begin{split}
    &\ell_i(\hat{x}_{i,N_i -1 | t' + 1}, \opt{u_{i,N_i | t'}}, \opt{r_{i,N_i | t'}}) \\
        & \quad \quad \stackrel{\eqref{eq:bounds_on_stage_cost}, \,\mathrm{Asm.}  \ref{assumption1}}{\leq} \alpha_{2,i} \mathcal{L}_{f_i}^2 \mynorm{\optt{x_{i,N_i-1|t'}} - \opt{x_{i,N_i-1|t'}}}^2, \\
    &\ell_i(\hat{x}_{i,N_i | t' + 1}, \opt{u_{i,N_i+1 | t'}}, \opt{r_{i,N_i+1 | t'}})\\
        & \quad \quad \stackrel{\eqref{eq:bounds_on_stage_cost}, \, \mathrm{Asm.}  \ref{assumption1}}{\leq} \alpha_{2,i} \mathcal{L}_{f_i}^4 \mynorm{\optt{x_{i,N_i-1|t'}} - \opt{x_{i,N_i-1|t'}}}^2.
\end{split}
\end{align*}
Then, using $\VNit = \JNi( \optt{\xti}, \optt{\uti}, \opt{\rti} )$ and
\begin{align*}
\begin{split}
    &\mynorm{\optt{x_{i,N_i-1|t'}} - \opt{x_{i,N_i-1|t'}}}^2\\
    &\quad \stackrel{\eqref{eq:bounds_on_stage_cost}}{\leq} \frac{1}{\alpha_{1,i}} \mynorm{\optt{x_{i,N_i-1|t'}} - \opt{x_{i,N_i-1|t'}}}_{Q_i}^2
    \leq \frac{1}{\alpha_{1,i}} V_{i,t'},
\end{split}
\end{align*}
we obtain
\begin{equation}
\label{eq:sum_li_candidate_bound}
    %\JNi(\hat{x}_{i,\cdot|t'+1}, \hat{u}_{i,\cdot|t'+1}, \opt{r}_{i,\cdot|t'+1})
    \sum_{k=0}^{N_i} \ell_i(\hat{x}_{i,k|t'+1}, \hat{u}_{i,k|t'+1}, \opt{r}_{i,k|t'+1})
    \leq (1 + \beta_i) V_{i,t'},
\end{equation}
where $\beta_i = \frac{\alpha_{2,i}}{\alpha_{1,i}} (\mathcal{L}_{f_i}^2 + \mathcal{L}_{f_i}^4)$. 
Consequently, with \eqref{eq:bounds_on_stage_cost} we have for $k = 0,\ldots,N_i$,
\begin{align}
\begin{split}
    &\mynorm{ \hat{x}_{i,k|t'+1} - \opt{x_{i,k|t'+1}}}^2\\
    & \quad \stackrel{\eqref{eq:bounds_on_stage_cost}}{\leq} \frac{1}{\alpha_{1,i}} \ell_i(\hat{x}_{i,k|t'+1}, \hat{u}_{i,k|t'+1}, \opt{r}_{i,k|t'+1}) \\
    & \quad \stackrel{\eqref{eq:sum_li_candidate_bound}}{\leq} \frac{(1+\beta_i) V_{i,t'}}{\alpha_{1,i}} \leq \frac{\epsilon^2}{\|C_i\|^2}.
\end{split}
\end{align}

    The last inequality ensures \eqref{eq:close_enough} if
    \begin{equation}
        V_{i,t'} \leq V_{\epsilon} := \frac{\alpha_{1,i} \epsilon^2}{(1 + \beta_i) \|C_i\|^2}.
    \end{equation}
%
\textit{Part 2:}
    Inequality~\eqref{eq:fast_coverage_exp_cost_decrease_K_steps} from Theorem~\ref{theorem:stability_of_tracking_mpc} shows that the value function of the tracking MPC exponentially converges to a fixed, reachable reference. Thus, for any $V_{\epsilon} > 0$ and any $\VNit \leq V_{\max,i} \, \forall \, t \geq 0$, there is a sufficiently large $\tau$ which implies that $V_{i,t+\tau} \leq V_\epsilon$, i.e.
    \begin{align*}
    V_{i, t + \tau} &\leq \left( 1 - \frac{\alpha_{N,i}}{\gammabari} \right)^{\tau} V_{i, t} \\
     &\leq \left( 1 - \frac{\alpha_{N,i}}{\gammabari} \right)^{\tau} \Vmaxi \\
    &\leq  \max_{i \in \M} \left( 1 - \frac{\alpha_{N,i}}{\gammabari} \right)^{\tau} \Vmaxi \leq V_{\epsilon}, \label{eq:lyapunov_step_with_max}
\end{align*}
    with ${\gammabari} > \alpha_{N,i} > 0$. The last inequality holds $\forall i \in \M$ for
\begin{equation} \label{eq:tau_solution}
    \tau = \frac{\ln V_{\epsilon} - \ln \left( \max_{i \in \M} \Vmaxi \right)}{\ln \left ( \max_{i \in \M} 1 - \frac{\alpha_{N,i}}{\gammabari} \right)}.
\end{equation}

Consequently, condition $V_{i,t'} \leq V_\epsilon$ holds for $t' = t + \tau$, and it follows from \textit{Part I} that condition \eqref{eq:partition_update_condition} is satisfied, resulting in a feasible partition update. This outcome contradicts the initial assumption, implying that condition \eqref{eq:partition_update_condition} is fulfilled for some $t' \in \left[t, t + \tau \right]$ with the finite uniform bound $\tau$. 
\end{proof}


