\section{Theoretical Analysis}

This section shows the theoretical analysis results mentioned in Sect. 3 in detail, including the redundancy of the training samples that are similar to each other and have similar training losses in terms of their contributions to the selector learning, and the effectiveness of the proposed pruning-based acceleration in terms of achieving a similar result as training on full data. 

\subsection{Redundancy of Training Samples}
Denote $\mathcal{L}_i = \mathcal{L}(F(\boldsymbol{X_i};\boldsymbol{\Theta}))$ the loss of $\boldsymbol{X_i}$ at current epoch, where $F(\boldsymbol{X};\Theta)$ is the full model including both the selector $f$ and the projections $h_T$ and $h_K$. $\Theta$ is the set of parameters. Recall that NN-based selector is learned using SGD, by which the learning result (i.e., the update of the parameters) of each iteration depends on the gradient of $\mathcal{L}$ with respect to $\Theta$, i.e.,
\begin{equation}
    \Theta^{t+1} = \Theta^t - \eta \sum_i \nabla_\Theta \mathcal{L}_i, 
\end{equation}
where $t$ is the current epoch, $\eta$ is the learning rate, and $\nabla_\Theta \mathcal{L}_i$ is the gradient of $\mathcal{L}_i$ respect to $\Theta$. According to the chain rule, we have
\begin{equation}
    \nabla \mathcal{L}_i = \nabla_F \mathcal{L}_i \cdot \nabla_\Theta F_i,\label{eq:gradient_Li}
\end{equation}
where $F_i$ represents $F(\boldsymbol{X}_i)$.


Suppose $\boldsymbol{X}_i$ and $\boldsymbol{X}_j$ are two training samples that are similar in themselves and in their losses, i.e.,
\begin{equation}
||\boldsymbol{X}_i - \boldsymbol{X}_j|| < \delta_X,  \label{eq:diff_X}  
\end{equation}
and
\begin{equation}
    |\mathcal{L}_i - \mathcal{L}_j| < \delta_L,\label{eq:diff_L}
\end{equation}
where $\delta_X > 0$ and $\delta_L > 0$ are two small values. Based on Eq.~\eqref{eq:gradient_Li}, the difference of their contributions to the learning is
\begin{equation}
\begin{split}
        &||\nabla_\Theta \mathcal{L}_i - \nabla_\Theta \mathcal{L}_j|| \\=& ||\nabla_F \mathcal{L}_i \cdot \nabla_\Theta F_i - \nabla_F \mathcal{L}_j \cdot \nabla_\Theta F_j|| \\
        =& ||\nabla_F \mathcal{L}_i(\nabla_\Theta F_i - \nabla_\Theta F_j) + \nabla_\Theta F_j (\nabla_F \mathcal{L}_i - \nabla_F \mathcal{L}_j)||.
\end{split}
\end{equation}
By using the triangle inequality, we have
\begin{equation}
\begin{split}
    ||\nabla_\Theta \mathcal{L}_i - \nabla_\Theta \mathcal{L}_j|| \le& ||\nabla_F \mathcal{L}_i||\cdot||\nabla_\Theta F_i - \nabla_\Theta F_j|| \\ &+ ||\nabla_\Theta F_j||\cdot||\nabla_F \mathcal{L}_i - \nabla_F \mathcal{L}_j)||.\label{eq:inequality}
\end{split}
\end{equation}

By using SGD, we have to ensure that the gradient in Eq.~\eqref{eq:gradient_Li} is bounded (e.g., by gradient clipping), i.e., 
\begin{equation}
    ||\nabla_F \mathcal{L}_i|| \le B_L, \label{eq:bound_L}
\end{equation}
and
\begin{equation}
    ||\nabla_\Theta F_i|| \le B_F,\label{eq:bound_F}
\end{equation}
where $B_L$ and $B_F$ are the corresponding bounds. 

Assume that $\nabla_\Theta F$ and $\nabla_F \mathcal{L}$ are \textit{Lipschitz} for $\boldsymbol{X}$. According to Eq.~\ref{eq:diff_X} we have
\begin{equation}
    ||\nabla_\Theta F_i - \nabla_\Theta F_j|| \le C_F||\boldsymbol{X}_i - \boldsymbol{X}_i|| < C_F\delta_X,
\end{equation}
and
\begin{equation}
  ||\nabla_F \mathcal{L}_i - \nabla_F \mathcal{L}_j)||  \le C_L||\boldsymbol{X}_i - \boldsymbol{X}_i|| < C_L\delta_X,\label{eq:lipschitz_L}
\end{equation}
where $C_F > 0$ and $C_L > 0$ are two constants.

Substituting Eqs~\eqref{eq:bound_L}-\eqref{eq:lipschitz_L} back to Eq.~\eqref{eq:inequality}, we get
\begin{equation}
    ||\nabla_\Theta \mathcal{L}_i - \nabla_\Theta \mathcal{L}_j|| \le (B_LC_F + B_FC_L) ||\boldsymbol{X_i} - \boldsymbol{X_j}|| < (B_LC_F + B_FC_L)\delta_X.\label{eq:grad_bounded_by_X}
\end{equation}

From Eq.~\eqref{eq:grad_bounded_by_X}, we can see that $||\nabla_\Theta \mathcal{L}_i - \nabla_\Theta \mathcal{L}_j|| \to 0$ when $\delta_X \to 0$, indicating that the samples close to each other have a similar contribution for updating the parameters of $F$ (also including the selector $f$).

Moreover, assume that the loss is \textit{strongly convex} (e.g., by L2 regularization). We have
\begin{equation}
\begin{split}
  \nabla_F \mathcal{L}_j \nabla_\Theta F_j (\boldsymbol{X}_i - \boldsymbol{X}_j) + \frac{\mu}{2}||\boldsymbol{X}_i - \boldsymbol{X}_j||^2 \le  \mathcal{L}_i - \mathcal{L}_j ,\label{eq:strongly_convex}
\end{split}
\end{equation}
where $\mu > 0$ is a constant. Recall that $\nabla_F \mathcal{L}_j$ and $\nabla_\Theta F_j$ are bounded as Eqs.~\eqref{eq:bound_L}-\eqref{eq:bound_F}. Note that the second-order term with respect to $\boldsymbol{X}$ in Eq.~\eqref{eq:strongly_convex} can be ignored when $\delta_X \to 0$. Thus, based on Eq.\eqref{eq:diff_L}, when $|\nabla_F \mathcal{L}_j  \nabla_\Theta F_j (\boldsymbol{X}_i - \boldsymbol{X}_j)| \le |\mathcal{L}_i-\mathcal{L}_j|$ we get
\begin{equation}
    ||\boldsymbol{X}_i - \boldsymbol{X}_j|| \le A\delta_L,\label{eq:X_bounded_by_delta_L}
\end{equation}
where 
\begin{equation}
    A = \frac{1}{||\nabla_F \mathcal{L}_j\nabla_\Theta F_j||\cdot|\cos<\nabla_F \mathcal{L}_j\nabla_\Theta F_j,\boldsymbol{X}_i - \boldsymbol{X}_j>|}.
\end{equation}

By substituting Eq.~\eqref{eq:X_bounded_by_delta_L} to Eq.~\eqref{eq:grad_bounded_by_X}, we see that the similarity condition in the loss may provide a tighter bound for $||\nabla_\Theta \mathcal{L}_i - \nabla_\Theta \mathcal{L}_j||$ when $A\delta_L < \delta_X$. 

In conclusion, the samples that are similar both in themselves and in their losses have almost \textbf{\textit{identical contributions to the training}}. Note that in our PA module, we use the average loss over the last $t-1$ training epochs (i.e., $\bar{\mathcal{L}}_i$) to approximate the loss in the current epoch (i.e., $\mathcal{L}_i$) following~\cite{qin2024infobatch} to achieve efficient pruning. 
%by applying the first-order Taylor approximation to the term $\nabla_F L_i - \nabla_F L_j$ in Eq.~\ref{eq:inequality}, we get
%\begin{equation}
%    \nabla_F L_i - \nabla_F L_j \approx H_F(\boldsymbol{X}_j)(F_i - F_j),
%\end{equation}
%where $H_F$ is the Hessian matrix of $\mathcal{L}$ with respect to $F$. 
\subsection{Effectiveness of Pruning-based Acceleration}
Recall that in our proposed PA, we perform random pruning and gradient rescale for the samples of $\bar{\mathcal{L}}_i \ge \bar{\mathcal{L}}$ and falling in the same buckets, and the samples of $\bar{\mathcal{L}}_i < \bar{\mathcal{L}}$. Therefore, we can divide the full dataset, denoted as $\mathcal{D}$, into $2$ disjoint subsets, including $\mathcal{D}_{1}$ that combines all buckets that need to prune and $\mathcal{D}_{2}$ other. Formally, we have
\begin{equation}
    \mathcal{D} = \mathcal{D}_{1}\cup \mathcal{D}_{2}.
\end{equation}

Denote $S_1$ the subset of $\mathcal{D}_{1}$ after pruning and $\mathcal{S}$ the pruned dataset used for the current training epoch. We have
\begin{equation}
    \mathcal{S} = \mathcal{S}_1 \cup \mathcal{D}_{2}.
\end{equation}

For each sample $\boldsymbol{X}_i$ to prune, the probability of pruning it is $r$, which is formulated as
\begin{equation}
    Pr(\boldsymbol{X}_i) = r.
\end{equation}

With gradient rescaling, the losses for the remaining samples in the pruned subsets, i.e., $\mathcal{S}_1$, are multiplied by the factor $1/(1-r)$, which is the same as multiplying the corresponding gradients by the factor. Assume that all samples $\boldsymbol{X}$ are drawn from a continuous distribution $\rho(\boldsymbol{X})$. The objective of selector learning on the full dataset can be formulated as
\begin{equation}
    \underset{\Theta}{\arg\min} \underset{\boldsymbol{X} \in \mathcal{D}}{\mathbb{E}}[\mathcal{L}(\boldsymbol{X};\Theta)] =  \int_{\boldsymbol{X}\in \mathcal{D}} \mathcal{L}(\boldsymbol{X;\Theta})\rho(\boldsymbol{X})d\boldsymbol{X}.\label{eq:objective_full_data}
\end{equation}

After pruning using the proposed PA, the selector learning objective becomes
\begin{equation}
\begin{split}
 \ \ \ \ \ \ \ \ \ \ \ &\underset{\Theta}{\arg\min} \underset{\boldsymbol{X} \in \mathcal{S}}{\mathbb{E}}[\mathcal{L}^\prime(\boldsymbol{X};\Theta)]  \\ =& \int_{\boldsymbol{X}\in \mathcal{S}_1} \frac{1}{1-r}\mathcal{L}(\boldsymbol{X;\Theta})\rho(\boldsymbol{X})d\boldsymbol{X} +  \int_{\boldsymbol{X}\in \mathcal{D}_2} \mathcal{L}(\boldsymbol{X;\Theta})\rho(\boldsymbol{X})d\boldsymbol{X},  \label{eq:objective_pruned} 
\end{split}
\end{equation}
where the first term on the right-hand side can be derived to
\begin{equation}
\begin{split}
    &\ \ \ \ \int_{\boldsymbol{X}\in \mathcal{S}_1} \frac{1}{1-r}\mathcal{L}(\boldsymbol{X;\Theta})\rho(\boldsymbol{X})d\boldsymbol{X} \\
    &= \int_{\boldsymbol{X}\in \mathcal{D}_1} \frac{1-Pr(\boldsymbol{X})}{1-r}\mathcal{L}(\boldsymbol{X;\Theta})\rho(\boldsymbol{X})d\boldsymbol{X}\\
    &= \int_{\boldsymbol{X}\in \mathcal{D}_1} \mathcal{L}(\boldsymbol{X;\Theta})\rho(\boldsymbol{X})d\boldsymbol{X}.\label{eq:objective_pruned_subset}
\end{split}
\end{equation}
By substituting Eq.~\eqref{eq:objective_pruned_subset} to Eq.~\eqref{eq:objective_pruned}, we get
\begin{equation}
\begin{split}
  \ \ \ \ \ \ \ \ \ \ \ &\underset{\Theta}{\arg\min} \underset{\boldsymbol{X} \in \mathcal{S}}{\mathbb{E}}[\mathcal{L}^\prime(\boldsymbol{X};\Theta)] \\
    =& \int_{\boldsymbol{X}\in \mathcal{D}_1} \mathcal{L}(\boldsymbol{X;\Theta})\rho(\boldsymbol{X})d\boldsymbol{X} + \int_{\boldsymbol{X}\in \mathcal{D}_2} \mathcal{L}(\boldsymbol{X;\Theta})\rho(\boldsymbol{X})d\boldsymbol{X} \\
    =& \int_{\boldsymbol{X}\in \mathcal{D}} \mathcal{L}(\boldsymbol{X;\Theta})\rho(\boldsymbol{X})d\boldsymbol{X},
\end{split}
\end{equation}
which is consistent with the objective of learning on the full data without pruning as shown in Eq.~\eqref{eq:objective_full_data}. Therefore, we conclude that \textbf{\textit{learning using the proposed pruning strategy can achieve a similar result as learning on the full data}}.


