\section{Mathematical Proofs}

\subsection{Proof of Submodularity for Nash Social Welfare}

\begin{lemma}
The utility function $u_i(S) = \sqrt{|S_i|}$ used in dating recommendation systems is submodular.
\end{lemma}

\begin{proof}
A function $f: 2^V \rightarrow \mathbb{R}$ is submodular if for all $A \subseteq B \subseteq V$ and $v \notin B$:
$$f(A \cup \{v\}) - f(A) \geq f(B \cup \{v\}) - f(B)$$

For $u_i(S) = \sqrt{|S|}$, we have:
$$u_i(A \cup \{v\}) - u_i(A) = \sqrt{|A|+1} - \sqrt{|A|}$$
$$u_i(B \cup \{v\}) - u_i(B) = \sqrt{|B|+1} - \sqrt{|B|}$$

Since $\sqrt{x}$ is concave, its marginal utility decreases as $x$ increases. Therefore:
$$\sqrt{|A|+1} - \sqrt{|A|} \geq \sqrt{|B|+1} - \sqrt{|B|}$$

This confirms submodularity \cite{freeman2017fair}.
\end{proof}

\subsection{Convergence Rate Analysis}

\begin{theorem}[Convergence Rate]
The FAIR-MATCH algorithm converges to an $\epsilon$-optimal solution in $O(\frac{1}{\epsilon^2})$ iterations.
\end{theorem}

\begin{proof}
Using the subgradient method for the Nash social welfare objective:
$$\theta_{t+1} = \theta_t - \eta_t g_t$$

Where $g_t \in \partial f(\theta_t)$ is a subgradient. For the step size $\eta_t = \frac{1}{\sqrt{t}}$, the convergence rate is:
$$f(\bar{\theta}_T) - f(\theta^*) \leq \frac{G\|\theta_0 - \theta^*\|}{\sqrt{T}}$$

Where $G$ is the bound on subgradient norms. This gives the stated convergence rate \cite{freeman2017fair}.
\end{proof}

