%    $$F^n(x)_{\cc{p}{p+r}}=F^n(y)_{\cc{p}{p+r}}.$$
%\end{definition}
%First let us recall a known characterization of equicontinuous CA. 
%\begin{theorem}[{\cite[Theorem 4]{kuurka1997languages}}]
%Let $F$ be a  CA with radius $r>0$ over an alphabet $A$. The following assertions are equivalent.
%\begin{enumerate}
%    \item $F$ is equicontinuous. 
%    \item There exists $k>0$ such that any word $u\in A^{2k+1}$ is $r$-blocking.
%    \item There exists $m\in \N$ and $p>0$ such that $F^{m+p}=F^m$.
%\end{enumerate}
%\end{theorem}
Here we provide a sufficient condition for a dill map to be equicontinuous.
\begin{proposition}\label{pro: equi}
    If $F$ is a dill map with diameter $\diam$ and local rule $f$ such that $1<|f|$ then $F$ is equicontinuous.
\end{proposition}
\begin{pff}
    Let $\epsilon=2^{-m}$ for some $m\in\N$ and let $\delta=2^{-p}$ where $p>\frac{m+|f|(\diam-1)}{|f|-1}$.
    \\ 
    For $x,y\in A^\N$ such that $d(x,y)\le \delta$ we obtain, $x_{\co{0}{p}}=y_{\co{0}{p}}$ and thus: 
    $$f^*(x_{\co{0}{p}})=f^*(y_{\co{0}{p}}).$$
    On the other hand, 
    $$|f^*(x_{\co{0}{p}})|= \sum_{i=0}^{p-\diam}|f(x_{\co{i}{i+\diam}})| \ge |f|\times(p-\diam +1).$$ 
    Hence, for $q_1=p|f|-|f|\times (\diam -1)$ we obtain, $F(x)_{\co{0}{q_1}}=F(y)_{\co{0}{q_1}}$. By induction on $t\in\N$, we obtain for $q_t=|f|^tp-\sum_{i=1}^t|f|^i(\diam-1)$: 
    $F^t(x)_{\co{0}{q_t}}=F^t(y)_{\co{0}{q_t}}.$
    Moreover, Since $|f|>1$, for all $t\in\N$: 
    \begin{eqnarray*}   
    q_t=|f|^t p-\sum_{i=1}^t|f|^i(\diam-1)&\ge & (|f|^t-1)p-|f|(\diam-1)\times \sum_{i=0}^{t-1}|f|^i \\
    &=& \left( (|f|-1)p-|f|(\diam-1)\right) \times\sum_{i=0}^{t-1}|f|^i.
    \end{eqnarray*}
    Therefore, since $p>\frac{m+|f|(\diam-1)}{|f|-1}$, we obtain for all $t\in\N$, $q_t\ge m\times\sum_{i=0}^{t-1}|f|^i\ge m.$
    Thus, for all $t\in\N$, $F^t(x)_{\co{0}{m}}=F^t(y)_{\co{0}{m}}$. In conclusion, $F$ is equicontinuous.
\end{pff}
\begin{corollary}
    If $F$ is a dill map with diameter $\diam$ and local rule $f$ such that $\diam\le |f|$ then $F$ is equicontinuous.
\end{corollary}
\begin{pff}
    If $|f|>1$ then according to Proposition \ref{pro: equi}, $F$ is equicontinuous. Suppose now that $|f|=1$, and thus, $\diam=|f|=1$. For any $x\in A^\N$ and any $p\in \N$, $|f^*(x_{\co{0}{p}})|\ge (p-\diam+1)|f|=p.$
    Therefore, for any $x,y\in A^\N$ and any  $t\in\N$, if $x_{\co{0}{p}}=y_{\co{0}{p}}$ then $F^t(x)_{\co{0}{p}}=F^t(y)_{\co{0}{p}}.$ 
\end{pff}

\paragraph{Expansivity:}
It is well-known that expansive cellular automata are surjective by \cite[Corollary 4.4]{fagnani1998expansivity}  
(this also follows from the fact that every non-surjective cellular automaton contains a diamond, see \cite[Definition~5.33]{kurka2003topological}, and hence cannot be expansive),  
it follows from Theorem~\ref{surjective} that the only expansive surjective uniform dill maps are precisely the expansive cellular automata.  
The same conclusion applies to other dynamical properties such as transitivity, openness, and closing, whose definitions can be found in \cite{kurka2003topological}.  
Indeed, open cellular automata are closing by \cite[Proposition~5.41]{kurka2003topological}, and both closing and transitive cellular automata are surjective by \cite[Proposition~5.41]{kurka2003topological} and \cite{codenotti1996transitive}, respectively.

\begin{corollary}
    A surjective uniform dill map $F$ is expansive \resp{transitive, opening, closing} if and only if, $F$ is an expansive \resp{transitive, opening, closing} CA.
\end{corollary}
\begin{remark}
Thanks to Proposition~\ref{pro: equi}, we can deduce that for a dill map $F$ with local rule $f$ and diameter $\diam$, if $\diam \leq |f|$, then $F$ cannot be expansive.
\end{remark}
%\begin{proposition}
%    If a dill map $F$ is positively expansive then it is not injective.
%\end{proposition}
In contrast to cellular automata, which are known to be surjective whenever
they are expansive, there exist dill maps that
are expansive but not surjective. We illustrate this with the following example.
%In contrast to cellular automata, which are known to be surjective whenever they are expansive (see \cite[Theorem 5.49]{kurka2003topological} for details), it seems that there may exist dill maps that are expansive but not surjective. The following example is a candidate illustrating this possibility.
    \begin{example}\label{ex: nonsurj exp}
        Let $F$ be a dill map defined by its local rule $f$ over $\{0,1,2\}$ such that for all $a,b,c\in \{0,1,2\}$: 
         $$f(a,b,c)=
\left\{
\begin{array}{r c l}
cc\quad  & \text{ if } & a\neq b\neq c, \\
c\quad  & \text{ otherwise}&.
\end{array}
\right.$$
Let us first prove that $F$ is not surjective. Suppose, for contradiction, that there exists a word $u \in A^*$ such that $w = 0121$ is a prefix of $f^*(u)$.

Then, considering $f^*(u_0 u_1 u_2u_3) = w_0w_1w_2 = 01$, we deduce that $u_2=0$ and $u_3 = 1$. Moreover, since $f(u_2 u_3 u_4)=2=w_3$, we must have $u_4 = 2$, which is a contradiction since $f(u_2u_3u_4)=f(012)=22\neq w_3w_4=21.$ Hence, such a word $u$ cannot exist, and $F$ is not surjective.

Now let us prove that $F$ is positively expansive. Let $\epsilon = \frac{1}{2}$ and take $x, y \in A^{\mathbb{N}}$.  
Without loss of generality, assume that $d(x, y) = 2^{-p_0}$ for some $p_0 \geq 2$.  
Hence, $x_{p_0} \neq y_{p_0}$ and $x_{\co{0}{p_0}} = y_{\co{0}{p_0}}$.  
Let $p_t$ denote the first position at which $F^t(x)$ and $F^t(y)$ differ, and define:
$\Delta_t=\sett{i\in\co{0}{p_t}}{F^t(x)_i\neq F^t(x)_{i+1}\neq F^t(x)_{i+2}}.$
%\text{ and } s_p(x)=|f^*(x_{\co{0}{p}})|.$$ \\
If $\Delta_0=\emptyset$, then for any $t\in\N$ we obtain $|(f^*)^t(x_{\co{0}{p}})|=p_t=p-2t$.  
In particular, for $t=\lfloor\frac{p}{2}\rfloor$, it follows that $d(F^t(x), F^t(y))\ge \epsilon$.\\
Now suppose that $\Delta_0\neq \emptyset$, and let $i_0=\min \Delta_0$. Then it is clear that $x_{\co{0}{i_0+3}}$ does not contains a word $u=abc$ such that $a\neq b\neq c$. Since applying $f^*$ cannot create a factor $u = abc$ with $a \neq b \neq c$ unless such a pattern already existed in the previous word, we obtain, for some $t_1\in\N^*$,
$\sharp\Delta_{t_1}\le \sharp\Delta_0-1$, (we can take for example $t_1=\lceil \frac{i_0}{2}\rceil+1$). Let now $i_1=\min \Delta_{t_1}$, and using the same argument, we obtain, for some $t_2\in \N^*$, $\sharp\Delta_{t_2}\le \sharp\Delta_1-1\le \sharp\Delta_0-1$. We iterate this process until all such words disappear, in which case we reach the same situation as in the case where $\Delta_0 = \emptyset$ or otherwise when $p_t\le 1$. Thus, for some $t\in \N$, $d(F^t(x), F^t(y))\ge \epsilon$.  In conclusion, $F$ is expansive but it is not surjective.

%First, we can remark that if $\Delta_{\co{0}{p}}(x)=\emptyset$, then  $F(x)_{\co{0}{s_p(x)}}=\sigma^2(x)_{\co{0}{s_p(x)}}.$ Hence, there is $t\in \N$ such that $d(F^t(x),F^t(y))>\epsilon$ 
% (since $\sigma^2$ is positively expansive). 
