	package sqrtTest;

	import java.math.BigInteger;
	import java.util.Random;
	import java.util.random.RandomGenerator;

	public class SqrtTest {

		public static void main(String[] args) {
			int nWords = 0b1000000000000000;
			Random rand = Random.from(RandomGenerator.getDefault());
			long t0, t1;
			long nTests = 1_000;
			long timeSum1 = 0, timeSum2 = 0;


			for (long n = 0; n < nTests; n++) {
				BigInteger x2 = new BigInteger(nWords << 5, rand);
				BigInt x1 = new BigInt(x2.toString());

				t0 = System.nanoTime();
				BigInt[] sqrtRem1 = x1.sqrtAndRemainder();
				t1 = System.nanoTime();
				long dt = t1 - t0;
				timeSum1 += dt;

				t0 = System.nanoTime();
				BigInteger[] sqrtRem2 = x2.sqrtAndRemainder();
				t1 = System.nanoTime();
				dt = t1 - t0;
				timeSum2 += dt;

				if (!sqrtRem1[0].toString().equals(sqrtRem2[0].toString()) || !sqrtRem1[1].toString().equals(sqrtRem2[1].toString())) {
					System.err.println("Inexact result:");
					System.err.println("sqrt = " + sqrtRem1[0] + ", rem = " + sqrtRem1[1]);
				}
			}

			double mean1 = (double) timeSum1 / nTests;
			double mean2 = (double) timeSum2 / nTests;
			System.out.println("avg time 1 = " + Math.round(mean1));
			System.out.println("avg time 2 = " + Math.round(mean2));
		}
	}
