\appendix
\section{Expected free energy derivations}
\label{sez:efe_eq}
In this Appendix, we provide the complete derivation of the expected free energy expressions \eqref{eq:EFE_2} and \eqref{eq:EFE_3}, as adapted to the adaptive digital twin framework from~\cite{pymdp}:
\\

\paragraph{Expected free energy}
\begin{equation}
\begin{split}
G_t^\pi&=\mathbb{E}_{Q(O_t,D_t\mid\pi)}[\ln{Q(D_{t}\mid\pi)}-\ln{\widetilde{p}(O_t,D_t\mid\pi)}]\\
&=\mathbb{E}_{Q(O_t,D_t\mid\pi)}[\ln{Q(D_{t}\mid\pi)}-\ln{\widetilde{p}(O_t,D_t\mid\pi)} +\underbrace{\ln{Q(D_{t}\mid O_{t},\pi)} -\ln{Q(D_{t}\mid O_{t},\pi)}}_{=0}]\\
&=\mathbb{E}_{Q(O_t,D_t\mid\pi)}[\ln{Q(D_{t}\mid\pi)}-\ln{Q(D_{t}\mid O_{t},\pi)}-\ln{\widetilde{p}(O_{t})} \\
&\hspace{50pt}- \ln{p(D_{t}\mid O_{t},\pi)} +\ln{Q(D_{t}\mid O_{t},\pi)}]\\
&=-\mathbb{E}_{Q(O_t,D_t\mid\pi)}[\ln{Q(D_{t}\mid O_{t},\pi)}-\ln{Q(D_{t}\mid\pi)}]-\mathbb{E}_{Q(O_t,D_t\mid\pi)}[\ln{\widetilde{p}(O_{t})}] \\
&\hspace{50pt}+\mathbb{E}_{Q(O_t,D_t\mid\pi)}[\ln{Q(D_{t}\mid O_{t},\pi)} - \ln{p(D_{t}\mid O_{t},\pi)}]\\
&= -\underbrace{\mathbb{E}_{Q(O_t\mid\pi)}[\text{D}_\text{KL}[Q(D_{t}\mid O_{t},\pi)\mid\mid Q(D_{t}\mid\pi) ] ]}_{\text{Epistemic value (information gain)}} - \underbrace{\mathbb{E}_{Q(O_t\mid\pi)}[\ln{\widetilde{p}(O_{t})}]}_{\text{Pragmatic value (utility)}}\\
&\hspace{50pt}+\underbrace{\mathbb{E}_{Q(O_t\mid\pi)}[\text{D}_\text{KL}[Q(D_{t}\mid O_{t},\pi)\mid\mid p(D_{t}\mid O_{t},\pi) ] ]}_{\text{Expected variational approximation error ($\geq0$)}}.
\end{split}
\end{equation}
\\

\paragraph{Expected free energy with model parameters}
\begin{equation}
\begin{split}
G_t^\pi&=\mathbb{E}_{Q(O_t,D_t,\boldsymbol{\phi}\mid\pi)}[\ln{Q(D_{t},\boldsymbol{\phi}\mid\pi)}-\ln{\widetilde{p}(O_t,D_t,\boldsymbol{\phi}\mid\pi)}]\\
&=\mathbb{E}_{Q(O_t,D_t,\boldsymbol{\phi}\mid\pi)}[\ln{Q(D_{t},\boldsymbol{\phi}\mid\pi)}-\ln{\widetilde{p}(O_t,D_t,\boldsymbol{\phi}\mid\pi)}\\
&\hspace{50pt}+\underbrace{\ln{Q(D_{t},\boldsymbol{\phi}\mid O_{t},\pi)} -\ln{Q(D_{t},\boldsymbol{\phi}\mid O_{t},\pi)}}_{=0}]\\
&=\mathbb{E}_{Q(O_t,D_t,\boldsymbol{\phi}\mid\pi)}[\ln{Q(D_{t}\mid\pi)}+\ln{Q(\boldsymbol{\phi}\mid\pi)} -\ln{\widetilde{p}(O_t)}-\ln{p(D_t,\boldsymbol{\phi}\mid O_t,\pi)}\\&\hspace{50pt}+\ln{Q(D_{t},\boldsymbol{\phi}\mid O_{t},\pi)} -\ln{Q(D_{t},\boldsymbol{\phi}\mid O_{t},\pi)}]\\
&=\mathbb{E}_{Q(O_t,D_t,\boldsymbol{\phi}\mid\pi)}[\ln{Q(D_{t}\mid\pi)}-\ln{Q(D_{t}\mid O_{t},\pi)}+\ln{Q(\boldsymbol{\phi}\mid\pi)}-\ln{Q(\boldsymbol{\phi}\mid O_{t},\pi)}\\&\hspace{50pt}-\ln{\widetilde{p}(O_t)}-\ln{p(D_t,\boldsymbol{\phi}\mid O_t,\pi)}+\ln{Q(D_{t},\boldsymbol{\phi}\mid O_{t},\pi)}]\\
&=-\mathbb{E}_{Q(O_t,D_t,\boldsymbol{\phi}\mid\pi)}[\ln{Q(D_{t}\mid O_{t},\pi)}-\ln{Q(D_{t}\mid\pi)}]\\&\hspace{50pt}-\mathbb{E}_{Q(O_t,D_t,\boldsymbol{\phi}\mid\pi)}[\ln{Q(\boldsymbol{\phi}\mid O_{t},\pi)}-\ln{Q(\boldsymbol{\phi}\mid\pi)}]-\mathbb{E}_{Q(O_t,D_t,\boldsymbol{\phi}\mid\pi)}[\ln{\widetilde{p}(O_t)}]\\&\hspace{50pt}+\mathbb{E}_{Q(O_t,D_t,\boldsymbol{\phi}\mid\pi)}[\ln{Q(D_{t},\boldsymbol{\phi}\mid O_{t},\pi)}-\ln{p(D_t,\boldsymbol{\phi}\mid O_t,\pi)}]\\
&=-\underbrace{\mathbb{E}_{Q(O_t\mid\pi)}[\text{D}_\text{KL}[Q(D_{t}\mid O_{t},\pi)\mid\mid Q(D_{t}\mid\pi)]]}_{\text{Epistemic value (digital state information gain)}}-\underbrace{\mathbb{E}_{Q(O_t\mid\pi)}[\text{D}_\text{KL}[Q(\boldsymbol{\phi}\mid O_{t},\pi)\mid\mid Q(\boldsymbol{\phi}\mid\pi)]]}_{\text{Epistemic value (model parameters information gain)}}\\&\hspace{50pt}-\underbrace{\mathbb{E}_{Q(O_t\mid\pi)}[\ln{\widetilde{p}(O_t)}]}_{\text{Pragmatic value (utility)}}+\underbrace{\mathbb{E}_{Q(O_t\mid\pi)}[\text{D}_\text{KL}[Q(D_{t},\boldsymbol{\phi}\mid O_{t},\pi)\mid\mid p(D_t,\boldsymbol{\phi}\mid O_t,\pi)]]}_{\text{Expected variational approximation error ($\geq0$)}}.
\end{split}
\end{equation}
