\begin{algorithm}[!t]  
\renewcommand\arraystretch{0.8}
	\caption{Distributed coalition algorithm}%算法名字
	\LinesNumbered %要求显示行号
	\KwIn{current node $i$, current cluster $\mathcal{S}_{i}^{curr}$ for node $i$, last iteration operation ${{\mathsf{\mathcal{P}}}_{i,\mathcal{S}_{m}^{(i)}}}$, the number of clusters in current partition $M$, network graph $\mathsf{\mathcal{W}}$}%输入参数
	  Find neighbor node set ${{\mathsf{\mathcal{R}}}_{i}}$ and neighbor cluster set $\mathsf{\mathcal{C}}_{i}^{neibr}=\left\{ \mathcal{S}_{i,l}^{neibr}\left| {{i}^{neibr}}\in \mathcal{S}_{i,l}^{neibr} \right.,\forall {{i}^{neibr}}\in {{\mathsf{\mathcal{R}}}_{i}} \right\}$\; 
   Initial the positive gain operation set ${{P}_{i}}=\varnothing $ \;
    \For{$\mathcal{S}_{i,l}^{neibr}\in \mathsf{\mathcal{C}}_{i}^{neibr}$}{ 
        \eIf{$v\left( \mathcal{S}_{i,l}^{neibr}\cap \left\{ i \right\} \right)>0$ and $g\left( {{\sigma }_{\mathcal{S}_{i}^{curr},\mathcal{S}_{i,l}^{neibr}}}\left( i,\varnothing  \right) \right)>0$}{
            //  the node $i$ join $\mathsf{\mathcal{S}}_{i,l}^{neibr}$ do not violate the constraint, and node $i$ obtain a positive gain by joining $\mathsf{\mathcal{S}}_{i,l}^{neibr}$ directly
            ${{P}_{i}}={{P}_{i}}\cup {{\sigma }_{\mathcal{S}_{i}^{curr},\mathcal{S}_{i,l}^{neibr}}}\left( i,\varnothing  \right)$
        }
        {
            \For{$j\in \mathcal{S}_{i,l}^{neibr}$}{
                \If{$v\left( \mathcal{S}_{i,l}^{neibr}\cap \left\{ j \right\} \right)>0$ and $g\left( {{\sigma }_{\mathcal{S}_{i}^{curr},\mathcal{S}_{i,l}^{neibr}}}\left( i,j \right) \right)>0$}{
                    //  switch operation 
                    ${{P}_{i}}={{P}_{i}}\cup {{\sigma }_{\mathcal{S}_{i}^{curr},\mathcal{S}_{i,l}^{neibr}}}\left( i,j \right)$ 
                }
                \If{$g\left( {{\rho }_{\mathcal{S}_{i}^{curr},\mathcal{S}_{i,l}^{neibr}}}\left( i,j \right) \right)>0$}{
                    //  replace operation
                    ${{P}_{i}}={{P}_{i}}\cup {{\rho }_{\mathcal{S}_{i}^{curr},\mathcal{S}_{i,l}^{neibr}}}\left( i,j \right)$
                }
            }
        }
    }
    \If{${{\varsigma }_\mathcal{S}}(i,i_\mathcal{S}^{h})>0$}{
        ${{P}_{i}}={{P}_{i}}\cup {{\varsigma }_\mathcal{S}}(i,i_\mathcal{S}^{h})$
    }
    Find  trail operation ${{\mathsf{\hat{\mathcal{P}}}}_{i,\mathcal{S}_{i}^{curr}}}$ obey $g\left( {{{\mathsf{\hat{\mathcal{P}}}}}_{i,\mathcal{S}_{i}^{curr}}} \right)>g\left( {{P}_{i,\mathcal{S}_{i}^{curr}}} \right)\quad \forall {{P}_{i,\mathcal{S}_{i}^{curr}}}\in {{P}_{i}}$\;
    Update coalition partition by operation ${{\mathsf{\hat{\mathcal{P}}}}_{i,\mathcal{S}_{i}^{curr}}}$ with probability in Eq. 23, otherwise maintain ${{\mathsf{\mathcal{P}}}_{i,\mathcal{S}_{m}^{(i)}}}$\;

