\section{Differentiability of the CU Loss Function} \label{Appendix_CU-reparameterization}
Here we first show the differentiability of (\ref{eq:CU-objective-final}) w.r.t $\boldsymbol{\theta}$ and then details on the reparameterization trick are provided.
\subsection{Derivative w.r.t the CU Encoder Parameters} \label{appendix:derivative}
The differentiability of the CU loss function w.r.t $\boldsymbol{\Xi}$ is clear since it is explicitly stated in (\ref{eq:CU-objective-final}), however how $\boldsymbol{\theta}$ is updated through the backpropagation is not explicitly visible. Thus, below we show how (\ref{eq:CU-objective-final}) is differentiable w.r.t $\boldsymbol{\theta}$.
\begin{equation*}
    \mathcal{L}^{\text{\tiny CU}}(\boldsymbol{\theta}, \boldsymbol{\Xi}) \approx \mathbb{E}_{p(\mathbf{S},\mathbf{z})} \left[\ \mathbb{E}_{p^{\text{\tiny CU}}_{\boldsymbol{\theta}}(\mathbf{c}|\mathbf{S})} [\ f(\mathbf{z})\, ]\,\right]
\end{equation*}
Where $\mathbf{z}=g(\mathbf{c},\boldsymbol{\Xi})$, and $\mathbf{c}=h(\mathbf{S},\boldsymbol{\theta},\boldsymbol{\epsilon})$. Thus, (\ref{eq:CU-objective-final}) can be expressed as:
\begin{equation*}
    \mathcal{L}^{\text{\tiny CU}}(\boldsymbol{\theta}, \boldsymbol{\Xi}) \approx \mathbb{E}_{p(\mathbf{S},\mathbf{z})} \left[\ \mathbb{E}_{p^{\text{\tiny CU}}_{\boldsymbol{\theta}}(\mathbf{c}|\mathbf{S})} [\ f(g(h(\mathbf{S},\boldsymbol{\theta},\boldsymbol{\epsilon}),\boldsymbol{\Xi}))\, ]\,\right]
\end{equation*}
Consequently:
\begin{equation*}
\begin{aligned}
    &\mathcal{L}^{\text{\tiny CU}}(\boldsymbol{\theta}, \boldsymbol{\Xi}) \approx f(g(h(\mathbf{S},\boldsymbol{\theta},\boldsymbol{\epsilon}),\boldsymbol{\Xi})) \\[0.8em]
    &\frac{\partial\mathcal{L}^{\text{\tiny CU}}(\boldsymbol{\theta}, \boldsymbol{\Xi})}{\partial \boldsymbol{\theta}} = \frac{\partial f}{\partial g} \cdot \frac{\partial g}{\partial h} \cdot \frac{\partial h}{\partial \boldsymbol{\theta}}
\end{aligned}
\end{equation*}
\subsection{Reparameterization Trick} \label{appendix:reparameterization}
We assume that $p^{\text{\tiny CU}}_{\boldsymbol{\theta}}(\mathbf{c}|\mathbf{S})=\mathcal{N}(\mathbf{c}(\mathbf{S};\boldsymbol{\theta}), \sigma^2 \mathbf{I})$, where $\mathbf{c}(\mathbf{S};\boldsymbol{\theta})$ states the deterministic function which maps $\mathbf{S}$ to $\mathbf{c}$ parameterized by $\boldsymbol{\theta}$. It is obvious that $\mathbf{c} \sim p^{\text{\tiny CU}}_{\boldsymbol{\theta}}(\mathbf{c}|\mathbf{S})$ and then in backpropagation when the update w.r.t $\boldsymbol{\theta}$ wants to be executed there will be a problem by:
\begin{equation*}
    \nabla_{\boldsymbol{\theta}} \mathbb{E}_{p^{\text{\tiny CU}}_{\boldsymbol{\theta}}(\mathbf{c}|\mathbf{S})} [\ f(g(c(\mathbf{S};\boldsymbol{\theta}),\boldsymbol{\Xi}))\, ]\
\end{equation*}
Therefore, we introduce a new variable $\boldsymbol{\epsilon}$ as $\mathbf{c}_{i,l} = \mathbf{c}_i + \boldsymbol{\epsilon}_{i,l}$, where we keep $\mathbf{c}_i$ a deterministic variable and $\boldsymbol{\epsilon}_{i,l}$ a sample drawn from $\mathcal{N}(\mathbf{0}, \sigma^2 \mathbf{I})$ distribution. Doing so, the expectation would be w.r.t $p(\boldsymbol{\epsilon})$ as follows, and the differentiability w.r.t $\boldsymbol{\theta}$ will be possible.
\begin{equation*}
\begin{aligned}
    \nabla_{\boldsymbol{\theta}} \mathbb{E}_{p^{\text{\tiny CU}}_{\boldsymbol{\theta}}(\mathbf{c}|\mathbf{S})} [\ f(g(c(\mathbf{s};\boldsymbol{\theta}),\boldsymbol{\Xi}))\,]\ &= \nabla_{\boldsymbol{\theta}} \mathbb{E}_{p(\boldsymbol{\epsilon})} [\ f(g(c(\boldsymbol{\epsilon},\mathbf{S};\boldsymbol{\theta}),\boldsymbol{\Xi}))\, ]\ \\[0.8em]
    &=\mathbb{E}_{p(\boldsymbol{\epsilon})} [\ \nabla_{\boldsymbol{\theta}} f(g(c(\boldsymbol{\epsilon},\mathbf{S};\boldsymbol{\theta}),\boldsymbol{\Xi}))\, ]\ \\[0.8em]
    &\simeq \nabla_{\boldsymbol{\theta}} f(g(c(\boldsymbol{\epsilon},\mathbf{S};\boldsymbol{\theta}),\boldsymbol{\Xi}))
\end{aligned}
\end{equation*}

\section{The Approximated SUs' Objective Function} \label{Appendix:su_loss}
\vspace{-1.3em}
\begin{equation*}
    \begin{aligned}
        \mathcal{L}^{\text{\tiny SU$_n$}}(\boldsymbol{\phi}_n) &=  I(\bm{\hat{x}}_n;z_n) - \lambda\,I(\bm{x}_n;\bm{c}) \\[0.6em]
        &= \iint p(\bm{\hat{x}}_n, z_n)\,\log \frac{p(z_n|\bm{\hat{x}}_n)}{p(z_n)}\,dz_n \, d\bm{\hat{x}}_n \\[0.6em]
        & \quad - \lambda \bigg(\ \iint p(\bm{x}_n, \bm{c})\,\log \frac{p^{\text{\tiny SU}}_{\boldsymbol{\phi}_n}(\bm{x}_n|\bm{c})}{p(\bm{x}_n)}\,d\bm{x}_n \, d\bm{c} \bigg)\ \\[0.6em]
        &= \left [\ \iint p(\bm{\hat{x}}_n, z_n)\,\log \,p(z_n|\bm{\hat{x}}_n)\,dz_n \, d\bm{\hat{x}}_n + H(z_n)\right]\ \\[0.6em]
        & \quad - \lambda \bigg(\ \iint p(\bm{x}_n, \bm{c})\,\log \frac{p^{\text{\tiny SU}}_{\boldsymbol{\phi}_n}(\bm{x}_n|\bm{c})}{p(\bm{x}_n)}\,d\bm{x}_n \, d\bm{c} \bigg)\ \\[0.6em] 
    \end{aligned}
\end{equation*}

Further, we omit the constant entropy term, $H(z_n)$ and exploit the underlying Markov chain structure in (\ref{eq:system_probability}).
\begin{equation*}
    \begin{aligned}
        \mathcal{L}^{\text{\tiny SU$_n$}}(\boldsymbol{\phi}_n) &\approx \iiiint p_{\boldsymbol{\theta}}(z_n,\bm{c})\,p^{\text{\tiny SU}}_{\boldsymbol{\phi}_n}(\bm{x}_n|\mathbf{c}) \\[0.6em] 
        & \qquad \quad \quad p(\bm{\hat{x}}_n|\bm{x}_n) \log p(z_n|\bm{\hat{x}}_n)\, dz_n\, d\bm{\hat{x}}_n\, d\bm{x}_n\, d\bm{c} \\[0.6em]
        & \quad - \lambda \bigg(\ \iiint p_{\boldsymbol{\theta}}(z_n,\bm{c})\\[0.6em]
        &\qquad \qquad p^{\text{\tiny SU}}_{\boldsymbol{\phi}_n}(\bm{x}_n| \bm{c})\,\log \frac{p^{\text{\tiny SU}}_{\boldsymbol{\phi}_n}(\bm{x}_n|\bm{c})}{p(\bm{x}_n)}\,dz_n\,d\bm{x}_n \, d\bm{c} \bigg)\ \\[0.6em]
        & \approx \mathbb{E}_{p_{\boldsymbol{\theta}}(z_n,\bm{c})}\left[\, \iint p^{\text{\tiny SU}}_{\boldsymbol{\phi}_n}(\bm{x}_n|\mathbf{c}) p(\bm{\hat{x}}_n|\bm{x}_n) \right. \\[0.6em]
        & \qquad \qquad \qquad \left. \log p(z_n|\bm{\hat{x}}_n)\,d\bm{\hat{x}}_n\, d\bm{x}_n \right. \\[0.6em] 
        & \qquad \qquad \qquad \left. - \lambda \int p^{\text{\tiny SU}}_{\boldsymbol{\phi}_n}(\bm{x}_n| \bm{c})\,\log \frac{p^{\text{\tiny SU}}_{\boldsymbol{\phi}_n}(\bm{x}_n|\bm{c})}{p(\bm{x}_n)}\,d\bm{x}_n \right]\
    \end{aligned}
\end{equation*}

Next, we adopt the definition of the KL \cite{cover1999elements},
\begin{equation*}
    KL(f||g) = \int f \log \frac{f}{g},
\end{equation*}
in addition to adopting the notation $p_{\boldsymbol{\phi}_n}(\bm{x}_n)$ for the marginal output distribution of the $n$-th SU to get the approximated loss function below:
\begin{equation*}
    \begin{aligned}
        &\mathcal{L}^{\text{\tiny SU$_n$}}(\boldsymbol{\phi}_n) \approx \mathbb{E}_{p_{\boldsymbol{\theta}}(z_n,\bm{c})} \left[\ \mathbb{E}_{p^{\text{\tiny SU}}_{\boldsymbol{\phi}_n}(\bm{x}_n|\bm{c})} \left[\,\mathbb{E}_{p(\bm{\hat{x}}_n|\bm{x}_n)} [\ \log p(z_n|\bm{\hat{x}}_n)\, ]\ \right]\ \right.\\[0.6em] 
        & \qquad \qquad \qquad \qquad - \left. \lambda\, KL(p^{\text{\tiny SU}}_{\boldsymbol{\phi}_n}(\bm{x}_n|\bm{c})\parallel p_{\boldsymbol{\phi}_n}(\bm{x}_n))\right]\,.
    \end{aligned}
\end{equation*}

It is important to note that $p_{\boldsymbol{\theta}}(z_n,\bm{c})$ is readily available at this stage, owing to the pre-trained CU. In essence, we construct our Markov chain by treating $p_{\boldsymbol{\theta}}(z_n,\bm{c})$ as a new, derived source distribution.

\section{Backpropagation of the SU Loss Function} \label{appendix:SU_loss_gradients}
Here we show why we ignore the $\hat{r}(\mathbf{x}_n)$ in the backpropagation of our approximated objective function of the n-th SU in \ref{eq:SU-objective-with-DRE-applied}. We use the SGD over mini-batches to train our SU encoder, and the update procedure looks:
\begin{equation*}
    \boldsymbol{\phi}^{\tau + 1}_{n} \leftarrow \boldsymbol{\phi}^{\tau}_{n} - \frac{\alpha}{M_\tau} \sum_{i\in M_\tau} \nabla_{\boldsymbol{\phi}_n}\mathcal{L}^{\text{\tiny SU$_n$}}_{i}(\boldsymbol{\phi}^{\tau}_{n}, \boldsymbol{\psi}^{\tau}_{n})
\end{equation*}
Thus, when optimized DRE is employed in the objective function, the gradient term becomes zero, and that is why we ignore the involvement of $\hat{r}(\mathbf{x}_n)$ in the optimization of the SU encoder. It is obvious that for other non-linear optimization techniques, such as Adam, the ignorance of the DRE in the updating step of the SUs is not possible.
\begin{equation*}
    \begin{aligned}
        \mathbb{E}_{p_{\boldsymbol{\phi}_n}(\mathbf{x}_n)} \left[\,\nabla_{\boldsymbol{\phi}_n}\log p_{\boldsymbol{\phi}_n}(\mathbf{x}_n) \right]\ &= \int p_{\boldsymbol{\phi}_n}(\mathbf{x}_n) \frac{\nabla_{\boldsymbol{\phi}_n}p_{\boldsymbol{\phi}_n}(\mathbf{x}_n)}{p_{\boldsymbol{\phi}_n}(\mathbf{x}_n)}\,d\mathbf{x}_n\\[0.6em]
        &= \nabla_{\boldsymbol{\phi}_n}\int p_{\boldsymbol{\phi}_n}(\mathbf{x}_n)\,d\mathbf{x}_n = 0
    \end{aligned}
\end{equation*}


