\begin{algorithm}[t]
\caption{Operational flow of CU-HLM.}
\label{algo_1}
\begin{algorithmic}[1]
\Require Input token sequence $\mathbf{s}$, $u_{\text{th}}$, $k(t)^*$ $\forall t$, $r_{\text{max}}$, $\theta_{\text{max}}$
\While{$|\mathbf{r}(t{-}1)| < r_{\text{max}}$ \textbf{and} $r(t{-}1)\neq\text{EOS}$}
    \State \textbf{// SLM Operation at Device (Round $t$)}
    \State Generate input $\mathbf{s}(t) = \mathbf{s} \oplus \mathbf{r}(t{-}1)$
    \State Sample $\{\theta^{(1)}, \ldots, \theta^{(M)}\}$ from $[0, \theta_{\text{max}}]$
    \State Generate vocabulary distributions $\mathbf{x}(t)$, $\tilde{\mathbf{x}}^{(m)}(t)$ $\forall m$
    \State Sample draft token $d$ and perturbed tokens $d^{(m)}$ $\forall m$
    \State Measure uncertainty $u(t)$ via \eqref{eq:uncertainty}
    \State Set $r(t) \gets d$
    \If{$u(t) > u_{\text{th}}$}
        \State Upload top $k(t)^*$ tokens $\{x_1(t), \dots, x_{k(t)^*}(t)\}$ and draft token $d$ to the BS
        \State \textbf{// LLM Operation at BS (Round $t$)}
        \State Reconstruct full distribution $\hat{\mathbf{x}}(t)$ via \eqref{eq_reconst}
        \State Generate LLM distribution $\mathbf{y}(t)$ by processing $\mathbf{s}(t)$
        \If{$y_d(t) < x_d(t)$}
            \State With probability $1 - \frac{y_d(t)}{x_d(t)}$, sample 
 a target token $r(t) = d^\ast$ from:
            \[
            P(r(t) = d^\ast)=\frac{(y_{d^\ast}(t) - \hat{x}_{d^\ast}(t))^+}{\sum_{i=1}^{|\mathcal{V}|} (y_i(t) - \hat{x}_i(t))^+}
            \]
        \EndIf
        \State Send $r(t)$ to the device
        \ElsIf{$u(t) \leq u_{\text{th}}$}
        \State \textbf{Opportunistic Skipping}
        \EndIf
        \State Update $\mathbf{r}(t) = \mathbf{r}(t{-}1) \oplus r(t)$, $t \gets t + 1$
\EndWhile
\end{algorithmic}
\end{algorithm}



\subsection{Offline Vocabulary Compression} \label{Subsection: Top-k}
%%\vspace{-10pt}



Directly computing \( D_{\text{TV}}(\bm{p}(t), \bm{q}(t)) \) is computationally expensive, as it involves accessing the full LLM distribution \( y_v(t) \), computing the resampling distributions in \eqref{resampling} and \eqref{resampling_distortion}, and evaluating their element-wise difference. To improve tractability, we instead derive the following upper bound:

\begin{proposition}[Upper Bound on Total Variation Distance]
\label{prop:1}
Given that \(\bm{x}(t)\) and \(\bm{y}(t)\) denote the vocabulary distributions of the SLM and LLM at the \(t\)-th round, respectively, the total variation distance between the resampling distributions \( \bm{p}(t) \) and \( \bm{q}(t) \) is upper bounded as:
\begin{align}
D_{\text{TV}}(\bm{p}(t), \bm{q}(t)) \leq \underbrace{\frac{
\sum\limits_{i=k+1}^{|\mathcal{V}|} |x_i(t) - \hat{x}_i(t)|
}{
D_{\text{TV}}(\bm{x}(t), \bm{y}(t))
}}_{:= \mathrm{U}_{\text{TV}}(k,t)}. \label{eq:TVD_2}
\end{align}
\begin{proof}
See Appendix \ref{Proof_1}. 
\end{proof}
\end{proposition}
This upper bound offers a tractable approximation of the TVD, enabling efficient estimation of resampling distortion without requiring full computation.  
Note, however, that \( \mathrm{U}_{\text{TV}}(k,t) \) depends on the full LLM-side distribution \( \bm{y}(t) \), which is not accessible at the device side.  
To address this, we assume access to a statistical estimate of the long-term average of \( \mathrm{U}_{\text{TV}}(k,t) \), which can be practically obtained via periodic downlink feedback from the server sharing historical observations of \( \bm{y}(t) \).





\begin{remark}[Offline Vocabulary Compression]
We determine a fixed compressed vocabulary size \( k^* \) that minimizes uplink communication cost while ensuring that the resampling distortion remains within a specified tolerance \( \theta \).  
This is achieved by replacing the per-round constraint in~\eqref{eq:opt} with a time-averaged upper bound \( \mathbb{E}_t[\mathrm{U}_{\text{TV}}(k,t)] \), leading to the following relaxed optimization:
\begin{equation}
k^* = \arg\min_{k} \left\{ k \;\middle|\; \mathbb{E}_t[\mathrm{U}_{\text{TV}}(k,t)] \leq \theta \right\}.
\end{equation}
\end{remark}
This approach is effective for offline tuning, but its applicability is limited in online contexts, as \( k^* \) is fixed across all rounds \( t \).  
Future work may explore tighter theoretical bounds using known inequalities that relate TVD to Wasserstein distance~\cite{gibbs2002choosing} or Kullback–Leibler divergence~\cite{canonne2022short,niu2025rate}.



