\section{Proof of Proposition~\ref{prop:1}}\label{Proof_1}

We begin by recalling the definition of the TVD between two probability distributions \( \bm{p}(t) \) and \( \bm{q}(t) \) as
\begin{equation}
    D_{\text{TV}}(\bm{p}(t), \bm{q}(t)) = \frac{1}{2} \left\| \bm{p}(t) - \bm{q}(t) \right\|_1, \label{eq:proof_1}
\end{equation}
where \( \|\cdot\|_1 \) denotes the \( \ell_1 \)-norm, defined as the sum of the absolute values of the vector’s components.

To simplify the analysis, define two auxiliary vectors \( \bm{\gamma} \) and \( \bm{\omega} \) such that the \(v\)-th components are given by \( \gamma_v = (y_v(t) - x_v(t))^+ \) and \( \omega_v = (y_v(t) - \hat{x}_v(t))^+ \), respectively.

Substituting these into \eqref{eq:proof_1}, we have:
\begin{equation}
    D_{\text{TV}}(\bm{p}(t), \bm{q}(t)) = \frac{1}{2} \left\| \frac{\bm{\gamma}}{\|\bm{\gamma}\|_1} - \frac{\bm{\omega}}{\|\bm{\omega}\|_1} \right\|_1.
\end{equation}

We decompose the \( \ell_1 \)-norm as follows:
{\footnotesize
\begin{align}
 \left\|  \frac{\bm{\gamma}}{\|\bm{\gamma}\|_1} - \frac{\bm{\omega}}{\|\bm{\omega}\|_1} \right\|_1 
 &= \left\| \left(  \frac{\bm{\gamma}}{\|\bm{\gamma}\|_1} - \frac{\bm{\omega}}{\|\bm{\gamma}\|_1} \right) 
 + \left(  \frac{\bm{\omega}}{\|\bm{\gamma}\|_1} - \frac{\bm{\omega}}{\|\bm{\omega}\|_1} \right) \right\|_1 \\
 &\overset{\text{(a)}}{\leq} \left\|  \frac{\bm{\gamma} - \bm{\omega}}{\|\bm{\gamma}\|_1} \right\|_1 
 + \left\| \bm{\omega} \left( \frac{1}{\|\bm{\gamma}\|_1} - \frac{1}{\|\bm{\omega}\|_1} \right) \right\|_1,
\end{align}}
where (a) follows from the triangle inequality.

We now bound each term separately. For the first term:
\begin{equation}\label{append_first}
\left\| \frac{\bm{\gamma} - \bm{\omega}}{\|\bm{\gamma}\|_1} \right\|_1 
= \frac{\|\bm{\gamma} - \bm{\omega}\|_1}{\|\bm{\gamma}\|_1}.
\end{equation}

For the second term, using the reverse triangle inequality:
\begin{align}\label{append_second}
\left\| \bm{\omega} \left( \frac{1}{\|\bm{\gamma}\|_1} - \frac{1}{\|\bm{\omega}\|_1} \right) \right\|_1 
&= \|\bm{\omega}\|_1 \cdot \left| \frac{1}{\|\bm{\gamma}\|_1} - \frac{1}{\|\bm{\omega}\|_1} \right|\nonumber\\
&= \frac{|\|\bm{\gamma}\|_1 - \|\bm{\omega}\|_1|}{\|\bm{\gamma}\|_1} \nonumber\\
&\leq \frac{\|\bm{\gamma} - \bm{\omega}\|_1}{\|\bm{\gamma}\|_1}.
\end{align}

Thus, combining \eqref{append_first} and \eqref{append_second}, we obtain:
\begin{equation}
D_{\text{TV}}(\bm{p}(t), \bm{q}(t)) 
\leq \frac{\|\bm{\gamma} - \bm{\omega}\|_1}{\|\bm{\gamma}\|_1}.
\end{equation}

Next, we bound the numerator. Since ReLU is a 1-Lipschitz function, it holds that:
\begin{align}
  \|\bm{\gamma} - \bm{\omega}\|_1 &\leq \|\bm{x}(t) - \hat{\bm{x}}(t)\|_1 \nonumber\\
  &= \left\| \left(\bm{x}(t) - \hat{\bm{x}}(t) \right)_{k+1:|\mathcal{V}|} \right\|_1,  \label{append_nume}
\end{align}
where \( (\cdot)_{a:b} \) denotes the subvector consisting of indices from \( a \) to \( b \), exploiting the fact that \( \bm{x}(t) \) and \( \hat{\bm{x}}(t) \) are identical over the top-\( k \) elements.

Finally, for the denominator, since both \( \bm{x}(t) \) and \( \bm{y}(t) \) are valid probability distributions, we apply mass conservation to obtain:
\begin{align}
\|\bm{\gamma}\|_1&=\sum_{i=1}^{|\mathcal{V}|} (y_i(t) - x_i(t))^+\\
&= \frac{1}{2} \sum_{i=1}^{|\mathcal{V}|} |y_i(t) - x_i(t)| = D_{\text{TV}}(\bm{x}(t), \bm{y}(t)). \label{append_denom}
\end{align}
Substituting \eqref{append_nume} and \eqref{append_denom} completes the proof. \qed


%We then consider the denominator element-wise. Noting that $\|\min(\bm{A}, \bm{B})\|_1$ is lower bounded by the $\ell_1$-norm over only the common (overlapping) elements between $\bm{A}$ and $\bm{B}$, we obtain the following inequality:
%\begin{equation}
%  \|\min(\bm{A}, \bm{B})\|_1 \geq \|\bm{A}_{1:k}\|_1 = \|\bm{B}_{1:k}\|_1.  
%\end{equation}

%Expressing both the numerator and the denominator element-wise completes the proof of Proposition~\ref{prop:1}. \qed

