\section{Computing invariant sets}\label{sectioninvariantset}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
We will first establish an effective description of the invariant set associated with a given algebraic variety and a polynomial map. Subsequently, we will derive an algorithm based on this description to compute such a set. 
We begin with a technical lemma to express the preimage of an algebraic variety under a polynomial map.
%In this paragraph, we prove an effective description of the invariant set associated to a given algebraic variety and a polynomial map. Then, we derive an algorithm based on this description to compute such set. We start with a technical lemma providing an effective description of the preimage of an algebraic variety with respect to a polynomial map.
\begin{lemma}\label{lem:equtionspreimage}
Given a polynomial map $F: \mathbb{C}^n \longrightarrow \mathbb{C}^m$ and  an algebraic variety $X \subset \mathbb{C}^m$, the preimage $F^{-1}(X)$ is also an algebraic variety. Moreover, if $X=\V(g_1, \ldots, g_k)$ and $F = (f_{1}, \ldots, f_{m})$, where $g_1,\ldots,g_k\in \mathbb{C}[y_1, \ldots, y_m]$ and $f_1, \ldots, f_m \in \mathbb{C}[x_1, \ldots, x_n]$, then 
\[
F^{-1}(X) = \V(g_{1}(f_1, \ldots , f_m), \ldots, g_{k}(f_1, \ldots, f_m)) \subset \mathbb{C}^n. 
\]
\end{lemma}
\vspace{-2mm}
\begin{proof}
%Let $F = (f_{1}, \ldots, f_{m})$ and $X = \V(g_1, \ldots, g_k)$ as in the statement, 
By definition, we have that:
  \begin{align*}
    F^{-1}(X) %&= %\{ x \in \C^n \mid(f_{1}(x), \ldots, f_{m}(x)) \in \V(g_1,\ldots,g_k) \}\\
 &= \{ x \in \C^n \mid \forall\, 1 \leq i \leq k,\, 
 g_i(f_1(x),\ldots,f_m(x)) = 0\}.
  \end{align*}
 Let $h_i =  g_i(f_1,\ldots,f_m)\in\C[x_1,\ldots,x_n]$, for all $1 \leq i \leq k$, then
 $
    F^{-1}(X) = \V(h_1,\ldots,h_k),
 $ 
 and $F^{-1}(X)$ is an algebraic variety.
\end{proof}

Before proving the main result, we need the following lemma.
\begin{lemma}\label{lem:invset}
Let $F : \Cn \longrightarrow \Cn$ be a polynomial map and $X\subseteq\Cn$ an algebraic variety. Then, $F(S_{(F,X)})$ is a subset of $S_{(F,X)}$.
\end{lemma}
\begin{proof}
 Let $x \in S_{(F,X)}$. By the definition of the invariant set, $F^{(m)}(x) \subseteq X$ for every $m$. Thus, $F^{(m)}(F(x)) \subseteq X$, implying that $F(x) \in S_{(F,X)}$ for every $x \in S_{(F,X)}$. Hence, $F(S_{(F,X)}) \subseteq S_{(F,X)}$.
 %Let $x$ be an element in $S_{(F,X)}$. By the definition of the invariant set, $F^{(m)}(x)$ is contained in $X$ for every integer $m\in \N$. Therefore, $F^{(m)}(F(x))$ is contained in $X$, % for every integer $m\in \N$ which proves that $F(x)$ is contained in $S_{(F,X)}$ for every $x \in S_{(F,X)}$. Thus, $F(S_{(F,X)})$ is a subset of $S_{(F,X)}$.
\end{proof}

\vspace{-2mm} We now give an effective method to compute invariant sets, by means of a stopping criterion for the intersection of the iterated preimages. In the following, %for any $m\geq 0$, and any $Y \subset \C^n$, 
$(F^{(m)})^{-1}$ will be denoted by $F^{(-m)}$.
\begin{proposition}\label{prop:stabilization}
Let $F : \Cn \longrightarrow \Cn$ be a polynomial map and $X\subseteq\Cn$ an algebraic variety. We define $X_m=\bigcap\limits_{i=0}^{m}F^{-i}(X)$ for all $m \in \N$. Then, the following statements are true:
\begin{itemize}
        \item[$(a)$] $X_{m+1} \subseteq X_{m}$ for all $m$.
        \item[$(b)$] There exists %a natural number 
        $N\in\mathbb{N}$ such that $X_{N} = X_{m}$ for all $m \geq N$.
        \item[$(c)$]  If $X_{N}=X_{N+1}$ for some $N$, then $X_{N}=X_{m}$ for all $m\geq N$.
        \item[$(d)$]  The invariant set $S_{(F,X)}$ is equal to $X_{N}$.
    \end{itemize}
\end{proposition}
\begin{proof}
 $(a)$ The following is straightforward from the definition: 
 $$X_{m+1}=X_m\cap F^{-(m+1)}(X)\subseteq X_m.$$

        \smallskip

        $(b)$ From $(a)$, we have the following descending chain 
        \[ 
            X_{0} \supseteq X_{1} \supseteq X_{2} \supseteq \cdots\supseteq X_{m} \supseteq X_{m+1} \supseteq \cdots,
        \]
       which are algebraic varieties by Lemma~\ref{lem:equtionspreimage}. 
       Thus, we have: % the ascending chain of ideals: 
       \[
        I(X_{0})\subseteq I(X_{1}) \subseteq I(X_{2})\subseteq \cdots \subseteq I(X_{m})\subseteq I(X_{m+1})\subseteq \cdots.
        \]
    Since $\C[x_{1},x_{2},\ldots,x_{n}]$ is a Noetherian ring, there exists a natural number $N$ such that $I(X_{N})=I(X_{m})$ for all $m\geq N$. Therefore, 
    $$X_N = \V(I(X_N)=\V(I(X_m))=X_m \text{ for all } m\geq N.$$

\smallskip 
$(c)$ For such an $N$, we have that 
\[
    X_{N+2} =X\cap F^{-1}(X_{N+1})=X\cap F^{-1}(X_N)=X_{N+1}.
 \] 
Thus,
$
X_{m}=X_{m+1}$ for all $m \geq N$,
and so %which implies 
$X_N = X_m$ for all $m\geq N$.

\smallskip
$(d)$ We will first prove that $S_{(F,X)}\subseteq X_{m}$ for every $m$, by induction on $m$. 
By the invariant set's definition, $S_{(F,X)}$ is a subset of $X=X_{0}$ which proves the base case $m=0$.
Now let $m>0$ and assume $S_{(F,X)}\subseteq X_{m-1}$.
%\textbf{Induction step.} 
By Lemma~\ref{lem:invset} and the induction hypothesis,
$$F(S_{(F,X)})\subset S_{(F,X)}\subset X_{m-1}.$$
Therefore, $S_{(F,X)}$ is a subset of $F^{-1}(X_{m-1})$. Note that $S_{(F,X)}$ is a subset of $X$ by the definition. Thus, 
$S_{(F,X)}\subset F^{-1}(X_{m-1})\cap X = X_{m}.$
In particular, when $m=N$, we have that $S_{(F,X)}\subseteq X_{N}$.

\smallskip
To prove the other inclusion, for every $x\in X_{m}$, note that $F^{m}(x)$ is contained in $X$ since $x\in X_m\subseteq F^{-m}(X)$. By $(a)$ and $(b)$, $X_{N}$ is contained in $X_{m}$ for every $m\in N$. Thus, $F^{m}(x)$ is contained in $X$ for every $x\in X_{N}$ and every $m\in \N$. Hence, $X_{N}\subseteq S_{(F,X)}$.
\end{proof}

