\begin{proposition}\label{prop:terminateinvariant}
    Let $\ab\in\mathbb{C}^n$, $X$ be an algebraic variety and $F:\C^n\to \C^n$ a polynomial map. 
    Then, the polynomial loop $\mathcal{L}(\ab,X,F)$ never terminates if and only if $\ab \in S_{(F, X)}$.
\end{proposition}
\begin{proof} 
% Let $\ab= (a_1, a_2,\ldots, a_n)$ be the initial value of $\mathcal{L}$. 
The statement directly follows from the definition, as $\mathcal{L}(\ab,X,F)$ never terminates if, and only if, $F^{(m)}(\ab)\in X$ for all $m\geq 0$, %\tag*{\qedhere}
%\end{center}
that is, if and only if $\ab\in S_{(F,X)}$.
\end{proof}


