\noindent The following main result follows from the above criterion.
\begin{theorem}\label{algogeneral}
 Let $F=(f_1,\ldots,f_n)$ be a sequences of polynomials in $\Q[x_1,\ldots,x_n]$ and let $d \geq 1$ and $m = \binom{n+d}{d}$.  Then, there exists an algorithm \textsf{TruncatedInvariant} which, on input $(F,d)$ computes a polynomial matrix $A$, with $m$ columns, and coefficients in  {$\Q[x_1,\ldots,x_n]$}, such that %the following holds.
the dth truncated invariant ideal of $\mathcal{L}(\ab,0,F)$~for any $\ab \in \Q^n$ is: % equal to:
 %Then for any $\ab \in \Q^n$, the dth-truncated invariant ideal of $\mathcal{L}(\ab,0,F)$ is defined by
 \[
  I_{d,\mathcal{L}} = 
  \left\{ \sum_{ |\alpha_i|\leq d}b_{i}{\bf x}^{\alpha_i} \mid (b_1,\ldots,b_m) \in \ker\,A(\ab) \right\}
 \]
  where~$\ker\,A(\ab)$~is~right-kernel of $A$, whose entries~are~evaluated~at~$\ab$.
\end{theorem}
\begin{proof}
    Let $y_1,\ldots,y_m$ be new indeterminates, and define $g$, $F_m$ and $X$ as in Proposition~\ref{prop3.4}. Then, by Proposition~\ref{thm:corralgo1}, on input $(g,F_m)$, Algorithm~\ref{algo1} computes polynomials $h_1,\dotsc,h_N$ in $\Q[x_1,\ldots,\\ x_n,y_1,\dotsc,y_n]$, whose common vanishing set is $S_{(F_m,X)}$.
    Moreover, by construction of Algorithm~\ref{algo1} and definition of $F_m$, we have:
    \[
        h_j = g\circ F_m^j(x_1,\ldots,x_n,y_1,\dotsc,y_m) = g\Big(F^j(x_1,\ldots,x_n),y_1,\dotsc,y_m\Big)
    \] 
     for $0\leq j \leq N$. Thus, $h_j$'s are linear in the $y_i$'s, and there exists a matrix $A$ with $m$ columns and coefficients in $\Q[x_1,\ldots,x_n]$~such~that %for all $j$: %$1\leq j \leq n$,
%    \todoremi{Pb notation}
    \begin{equation}\label{eqn:matrix}
    \begin{bmatrix}
        h_1\cdots
        h_m 
    \end{bmatrix}^t
    =
    A \cdot 
    \begin{bmatrix}
        y_1\cdots
        y_m   
    \end{bmatrix}^t
    \end{equation}
    Let $\bb \in \Q^n$, by Proposition~\ref{prop3.4}, $g(\xb,\bb)$ is a polynomial invariant of $\mathcal{L}(\ab,0,F)$ if, and only if, $(\ab,\bb)\in S_{(F_m,X)}$, that is, by \eqref{eqn:matrix}, if and only if $A(a_1,\dotsc,a_n)\cdot \bb = 0$. Since any polynomial in $\Q[x_1,\ldots,x_n]$ can be written as $g(\xb,\bb)$, for some $\bb \in \Q^m$, we are done.
\end{proof}

\begin{remark}\label{remark_disequality}
We can add disequalities of form $p(x) \neq 0$ in the guard loop as in \cite{muller2004computing}. 
Indeed, by applying Algorithm~\ref{algo1} to $(p\cdot g,F_m)$ instead of $(g,F_m)$ in the above proof,  
this implies that at each iteration, either $p(x)=0$ and the loop terminates (and so does Algorithm~\ref{algo1}) or we add the usual constraints given by the polynomial map.
\end{remark}
