Following the above idea, we present an algorithm to compute a vector basis of the dth truncated invariant ideal of a loop with a fixed initial value. We first explain two subroutines used in this algorithm:
(i) The procedure \textsf{VectorBasis} takes linear forms as input and computes a vector basis of the common vanishing set of these forms.
(ii) The procedure \textsf{CheckPI} takes as input ${\bf a} \in \Q^n$ and polynomials $F=(f_1,\ldots,f_n)$ and $g$ in $\Q[x_1,\ldots,x_n]$. It outputs \texttt{True} if, and only, if $g$ is a polynomial invariant of $\mathcal{L}(\ab,0,F)$. Such a procedure can be obtained by a direct combination of an application of Algorithm~\ref{algo1} to $(g,F)$ and the effective criterion given by Proposition~\ref{prop:terminateinvariant}.

% It returns ``True'' if $(h_1(a), \ldots, h_k(a)) =0$ where $(h_1, \ldots, h_k) \gets \text{InvariantSet}(g, F)$, and ``False'' otherwise.
% The procedure ``CheckPI'' takes a sequence of rational numbers ${\bf a}$, a sequence of polynomials $F$, and a polynomial $g$ as input. It returns ``True'' if $(h_1(a), \ldots, h_k(a)) =0$ where $(h_1, \ldots, h_k) \gets \text{InvariantSet}(g, F)$, and ``False'' otherwise. Consequently, $\CheckPI({\bf a}, F, g)$ assesses whether $g=0$ constitutes a polynomial invariant for a loop with initial value ${\bf a}$ and a polynomial map $F$ based on Proposition~\ref{prop_sufficient}. A common choice for the parameter $M$ is $\binom{n+d}{d}$ as outlined in Algorithm~\ref{alg2}, although it can be chosen differently based on the underlying loop.

\begin{algorithm}[H]
\caption{Computing truncated invariant ideals}\label{alg2}
\begin{algorithmic}[1]\setstretch{1.2}
\Require A sequence of rational numbers ${\bf a} = (a_1,\ldots,a_n)$, a natural number $d$ and %a sequence of 
polynomials $F=(f_1,\ldots,f_n) \in \mathbb{Q}[x_1,\ldots,x_n]$.
\Ensure Polynomials forming a vector space basis for the dth truncated ideal of the loop $\mathcal{L}(\ab,0,F)$. % with initial value $\bf a$ and a polynomial map $F$. $\mathcal{L}(\ab,F)$?}
\State $ g\gets\sum\limits_{|\alpha_i|\leq d}y_i{\bf x}^{\alpha_i};$
\State$M\gets \binom{n+d}{d};$
\State $(b_1,\ldots,b_m)\gets \VectorBasis\big(g({\bf a,y}),g(F({\bf a),y}), \ldots g(F^{M}({\bf a),y})\big)$;
\State \label{step:B}$\mathcal{B}\gets \big(\sum\limits_{|\alpha_i|\leq d}b_{1,i}{\bf x}^{\alpha_i},\ldots ,\sum\limits_{|i|\leq d}b_{m,i}{\bf x}^{\alpha_i}\big)$;
\State$C=(h_1,\ldots,h_l) \gets \{ h\in \mathcal{B}\mid \CheckPI({\bf a},F,h)==False\};$
\If{$C ==\emptyset$,}
%\algstore{testcont}

%\end{algorithmic}
%\end{algorithm}  
%\begin{algorithm}
%\begin{algorithmic}[1]
%\algrestore{testcont}

\State \Return $\mathcal{B};$
\Else
\State$(\widetilde{h}_1,\ldots, \widetilde{h}_k) \gets \InvariantSet(\sum_{j=1}\limits^{l} z_jh_j, (f_1,\ldots , f_n, z_1,\ldots, z_l ));$
\State$(b_{1}',\ldots, b_{s}')\gets \VectorBasis(\widetilde{h}_1({\bf a,z}),\ldots, \widetilde{h}_k({\bf a,z}))$;
\State$\mathcal{B}_1\gets \big(\sum\limits_{j=1}^{l}b_{1,i}'h_j, \ldots, \sum\limits_{j=1}^{l}b_{s,i}'h_j\big)$;
\State$\mathcal{B}_2\gets \mathcal{B}.remove(C); $
\State$\mathcal{B}\gets\mathcal{B}_1.extend(\mathcal{B}_2);$
\State \Return $\mathcal{B};$
\EndIf
\end{algorithmic}
\end{algorithm}

\begin{remark}\label{remark_disequality_fixed}
As described in Remark~\ref{remark_disequality}, for the general case, one can easily adapt this algorithm to handle loops with disequalities $p(x)\neq 0$ in the guard by replacing $g$ with $p\cdot g$ at step 3.

In terms of complexity, in the worst case, Algorithm~\ref{alg2} does not find any candidates at step 3 and calls Algorithm~\ref{algo1} on the general loop at step 9, without exploiting the given initial values. However, in practice, all candidates found at step 3 are invariants (see Section~\ref{sec:implementation}), and Algorithm~\ref{alg2} terminates at step 7.
\end{remark}

