    \begin{definition}[Hockey stick divergence and dominating pairs] The hockey stick divergence between two random variables $X$ and $Y$, (with pdfs $\mu_X$, $\mu_Y$) is defined as   
    $$HS_\alpha(X,Y) = \Ex_{\theta_\sim S}[(\frac{\mu_X(\theta)}{\mu_Y(\theta)}-\alpha)_{+}].$$ We say a pair of random variables $(X,Y)$ dominates another pair $(M,S)$ iff for all $\alpha\in \R$ 
    $$HS_\alpha(M,S))\leq HS_\alpha(X,Y).$$
    \end{definition}
    \begin{lemma}\label{lem:HS_to_fDP}
    Let $f=T(X,Y)$ be a trade-off function, for a pair of distributions $(M,S)$ we have 
    $$\forall \cT, \Pr_{\theta\sim M}[\theta \in \cT] \leq 1 - f(\Pr_{\theta\sim S}[\theta \in \cT])$$ if and only if $(M,S)$ is dominated by $(X,Y)$.
    \end{lemma}
    % Now let $\mu$ be the pdf of $M_1(\cS\cup \set{x})$ and $\nu$ be the pdf of $\Sim_1(\cS, \Psi(x))$. We can rewrite the expectation as follows:
    % \begin{align*}&\E_{\theta\sim M_1(\cS \cup \set{x})}[\Pr[\Sim_2(\cS, \Psi(x) , \theta)\in \cT]\\
    % &~~~=\E_{\theta\sim \Sim_1(\cS, \Psi(x))}[\Pr[\Sim_2(\cS, \Psi(x) , \theta)\in \cT]\cdot \frac{\mu(\theta)}{\nu(\theta)}]
    % \end{align*}

    let $M\equiv (U_1,U_2)= (M_2(\cS \cup \set{x}), M_1 o M_2(\cS \cup \set{x})$ be the joint distribution of the result of running the mechanism.  Similarly $S\equiv(S_1,S_2)\equiv \Sim_1 o \Sim_2(\cS \cup{\Psi(x)})$. We use $S_2[\theta]$ and $U_2[\theta]$ to denote the conditional random variable of $S_2\mid S_1=\theta$ and $U_2\mid U_1=\theta$. Also let $\mu=(\mu_1,\mu_2)$ be the pdf of $M$ and $\nu=(\nu_1,\nu_2)$ the pdf of $S$. We also abuse the notation and $X_1(.)$, $X_2(.)$  $Y_1(.)$ and $Y_2(.)$ and the probability density functions for $X_1, X_2, Y_1,$ and $Y_2$. We have

    % For $\alpha\in[0,1]$, let us define $$t^+(\mu, \nu, \alpha) = \inf \set{t\in R^+; \Pr[\frac{\mu(x)}{\nu(x)}\geq t] \geq \alpha}$$
    % and $$t^{-}(\mu, \nu, \alpha) = \sup \set{t\in R^+; \Pr_{x\sim M}[\frac{\mu(x)}{\nu(x) \geq t}] \leq \alpha}$$

    \begin{align*}
        &HS_\alpha (M, S) = \Ex_{\theta \sim S} [(\frac{\mu(\theta)}{\nu(\theta)}-\alpha)_+]\\
        &=\Ex_{\theta_1 \sim S_1}\Big[\Ex_{\theta_2 \sim S_2[\theta_1]}[(\frac{\mu(\theta_1,\theta_2)}{\nu(\theta_1,\theta_2)}-\alpha)_+]\Big]\\
        &=\Ex_{\theta_1 \sim S_1}\Big[\frac{\mu_1(\theta_1)}{\nu_1(\theta_1)}\Ex_{\theta_2 \sim S_2[\theta_1]}[(\frac{\mu_2[\theta_1](\theta_2)}{\nu_2[\theta_1](\theta_2)}-\alpha\cdot \frac{\nu_1(\theta_1)}{\mu_1(\theta_1)})_+]\Big]\\
        &= \Ex_{\theta_1 \sim S_1}\Big[\frac{\mu_1(\theta_1)}{\nu_1(\theta_1)}HS_{\alpha\cdot \frac{\nu_1(\theta_1)}{\mu_1(\theta_1)}}(M_2[\theta],S_2[\theta_2])\Big]\\
        &\leq \Ex_{\theta_1 \sim S_1}\Big[\frac{\mu_1(\theta_1)}{\nu_1(\theta_1)}HS_{\alpha\cdot \frac{\nu_1(\theta_1)}{\mu_1(\theta_1)}}(X_2,Y_2)\Big]\\
        &=\Ex_{\theta_1 \sim S_1}\Big[\Ex_{\theta_2 \sim Y_2}[(\frac{\mu_1(\theta_1)X_2(\theta_2)}{\nu_1(\theta_1)Y_2(\theta_2)}-\alpha)_+]\Big]\\
        &=\Ex_{\theta_2 \sim Y_2}\Big[\Ex_{\theta_1 \sim S_1}[(\frac{\mu_1(\theta_1)X_2(\theta_2)}{\nu_1(\theta_1)Y_2(\theta_2)}-\alpha)_+]\Big]\\
        &=\Ex_{\theta_2 \sim Y_2}\Big[\frac{X_2(\theta_2)}{Y_2(\theta_2)}\Ex_{\theta_1 \sim S_1}[(\frac{\mu_1(\theta_1)}{\nu_1(\theta_1)}-\alpha\frac{Y_2(\theta_2)}{X_2(\theta_2)})_+]\Big]\\
        &=\Ex_{\theta_2 \sim Y_2}\Big[\frac{X_2(\theta_2)}{Y_2(\theta_2)}HS_{\alpha\frac{Y_2(\theta_2)}{X_2(\theta_2)})}(M_1, S_1)\Big]\\
        &\leq \Ex_{\theta_2 \sim Y_2}\Big[\frac{X_2(\theta_2)}{Y_2(\theta_2)}HS_{\alpha\frac{Y_2(\theta_2)}{X_2(\theta_2)})}(X_1, Y_1)\Big]\\
         &=\Ex_{\theta_2 \sim Y_2}\Big[\Ex_{\theta_1 \sim X_1}[(\frac{X_1(\theta_1)X_2(\theta_2)}{Y_1(\theta_1)Y_2(\theta_2)}-\alpha)_+]\Big]\\
         &=HS_\alpha(X_1\times X_2, Y_1\times Y_2).
    \end{align*}
    With similar steps we can show that $H_\alpha(M,S) \leq HS_\alpha(X_1\times X_2, Y_1 \times Y_2).$ Therefore using Lemma \ref{lem:HS_to_fDP} we conclude the proof.
\end{proof}

% \section*{Sub-sampling does not amplif feature DP.}
Now we show that sub-sampling does not generally improve feature-DP. We construct a mechanism $M$ that is \fDPi with respect to a feature $\Psi$, but for any $p\in[0,1]$ its sub-sampled version does not satisfy \fDPi for any $\epsilon'< \epsilon$. 
\begin{proof}[Proof of Proposition \ref{prop:sub-samp-FDP}]
Let $\cB=\set{0,1}^d$ and define a mechanism $M\colon \cB^* \to \cB^*$ as follows. Let $\cS=\set{x_1, \dots, x_n; x_i\in \cB}$, we define $M(X)$
$$M(\cS) = \set{R(x_1), \dots,R(x_n)}$$
where $R(x_i)$ is Boolean random variable that is sampled based on the randomized response mechanism as follows:
\begin{align*}
R(x_i) = \begin{cases}
x_i^1,x_i^2,\dots, x_i^d &\text{With probability $\frac{e^{2\epsilon}}{1+e^{2\epsilon}}$}\\    
1-x^1_i,x_i^2,\dots, x_i^d &\text{With probability $\frac{1}{1+e^{2\epsilon}}$}
\end{cases}
\end{align*}
Also let us define the feature $\Psi\colon \cB \to \cB$ be a feature defined as
$$\Psi(b_1,\dots,b_d)= (b_2,\dots,b_d).$$ 

We first show that $M'=M~o~\poisson_p$ is \fDPi[$\epsilon$]. We construct a simulator $\Sim:\cB^*\times \cB \to \cB^*$ as follows:
\begin{align*}
\Sim\Big(\set{x_1,\dots, x_n}, \Psi(x_{n+1})\Big) &=M'(\set{x_1,\dots, x_n})\\&~~~\cup G_p(\Psi(x_{n+1})).
\end{align*}
where 
\begin{align*}
G_p(b_2,\dots,b_d)=
\begin{cases}
    \emptyset& \text{With probability $1-p\frac{e^\epsilon}{1+e^{2\epsilon}}$},\\
    \set{(0,b_2,\dots,b_d)}& \text{With probability $\frac{p}{2}$},\\
    \set{(1,b_2,\dots,b_d)}& \text{With probability $\frac{p}{2}$}.
\end{cases}
\end{align*}
In what follows we use $G$ to denote $G_{1.0}$.
Now we use $\Sim$ as a simulator for $M' = M o~\poisson_p$. 
Consider two datasets $\cS=\set{x_1,\dots,x_n}$ and $\cS'=\cS \cup \set{x_{n+1}}$.

Let $\cT^*\subset \cB$ We have
\begin{align*}\Pr[M'(\cS') =\cT] &= (1-p)\cdot \Pr[M'(\cS) =\cT]\\ 
&~~~+ p \cdot \Pr[M(\cS) \cup \set{R(x_{n+1})} = \cT].
\end{align*}
On the other hand, we have
\begin{align*}\Pr[\Sim(\cS, \Psi(x_{n+1})) =\cT] &= (1-p)\cdot \Pr[M'(\cS) =\cT]\\ 
&+ p \cdot \Pr[M(\cS) \cup \set{G(\Psi(x_{n+1}))} = \cT].
\end{align*}
We now only focus on the second terms. Let $b$ be the first bit of $x_{n+1}$. We have
\begin{align*}q_1&=\Pr[M(\cS) \cup \set{R(x_{n+1})} = \cT]\\  &=
(1-\frac{1}{2e^\epsilon}) \Pr[M(\cS) \cup \set{(b,\Psi(x_{n+1)})} = \cT]\\
&+\frac{1}{2e^\epsilon} \Pr[M(\cS) \cup \set{(1-b,\Psi(x_{n+1)})} = \cT].
\end{align*}
We also have
\begin{align*}q_2&=\Pr[M(\cS) \cup \set{G(\Psi(x_{n+1}))} = \cT]\\  &=
\frac{1}{2} \Pr[M(\cS) \cup \set{(b,\Psi(x_{n+1}))} = \cT]\\
&+\frac{1}{2} \Pr[M(\cS) \cup \set{(1-b,\Psi(x_{n+1}))} = \cT].
\end{align*}
Let $q_3 = (1-\frac{1}{2e^\epsilon}) \Pr[M(\cS) \cup \set{(b,\Psi(x_{n+1}))} = \cT]$, $q_4=\frac{1}{2e^\epsilon} \Pr[M(\cS) \cup \set{(1-b,\Psi(x_{n+1}))} = \cT]$, $q_5 = \frac{1}{2} \Pr[M(\cS) \cup \set{(b,\Psi(x_{n+1}))} = \cT]$, $q_6=\frac{1}{2} \Pr[M(\cS) \cup \set{(1-b,\Psi(x_{n+1}))} = \cT]$ so that we have $q_1$=$q_3 + q_4$ and $q_2=q_5+q_6$. We can now check that 

$$e^{-\epsilon}\leq \frac{q_3}{q_5}\leq e^\epsilon\text{~~and~~}e^{-\epsilon}\leq \frac{q_4}{q_6} \leq e^\epsilon.$$
Therefore we have $$e^{-\epsilon}\leq\frac{(1-p)\Pr[M'(\cS) =\cT] + p\cdot q_1}{(1-p)\Pr[M'(\cS) =\cT] + p\cdot q_2}\leq e^\epsilon.$$

Now we prove the tightness. We need to show that for any simulator $\Sim$ there is a pair of datasets and a possible outcome where the ratio of probabilities is at least $e^\epsilon$. Let $\cS=\set{\mathbf{0}}$ and $\cS'=\set{\mathbf{a},\mathbf{b}}$ and $\cS''=\set{\mathbf{a},\mathbf{c}}$ where 
$$\mathbf{a}=(0,\dots,0), \mathbf{b}=(1,\dots,1) \text{~and~} \mathbf{c}=(0,1,\dots,1) .$$
Now let $\Sim$ be an arbitrary simulator that satisfies \fDPi{$(\epsilon',0)$} for $\epsilon'<\epsilon$. Let $\cT_1$ be the set of all possible outcomes with $\mathbf{b}\in \cT_1$.

We have, 
\begin{align*}
q_1=\Pr[M'(\cS')\in \cT_1] = p\cdot (1-\frac{1}{2e^\epsilon}).
\end{align*}
and
\begin{align*}
q_2=\Pr[M'(\cS'')\in \cT_1] = \frac{p}{2e^\epsilon}.
\end{align*}
Now let us define
\begin{align*}
q_3=\Pr[\Sim(\cS, \Psi(\mathbf{b})) \in \cT_1] = \Pr[\Sim(\cS, \Psi(\mathbf{c}))\in \cT_1].
\end{align*}
\begin{align*}
q_4=\Pr[M'(\cS')\not \in  \cT_2 \cup \cT_1] = 1-p.
\end{align*}
\end{proof}
