\begin{proof}[Proof of Theorem \ref{thm:att_inf}]
We want to bound the following quantity.
    $$adv(A, X, u, S, d, \rho)= \Pr_{\substack{x\sim [X\mid \Psi(X)=u]\\ \theta \sim M(S \cup \set{x})\\
    x' \sim A(\theta)}}[d(x', x)\leq \rho].$$
For simplicity, let us assume $A$ is deterministic. Note that this assumption is without loss of generality because we can always fix the randomness of $A$ to be the best possible randomness for the objective, and by averaging argument the advantage of such deterministic attack is at least as good as the randomized attack. 
We rewrite this expectation as follows: 

\begin{align*}
    &\Pr_{\substack{x\sim [X\mid \Psi(X)=u]\\ \theta \sim M(S \cup \set{x})\\
    x' \sim A(\theta)}}[d(x', x)\leq \rho]\\
    &~~~= \E_{x\sim [X\mid \Psi(X)=u]}[\Pr_{\theta \sim M(S \cup \set{x})}[(A(\theta),x)\leq \rho]].
\end{align*}
Let us define an event $E$ on the model parameters where $E_x=\set{\theta\in \Theta; d(A(\theta),x)\leq \rho}$.
Therefore we have,
\begin{align*}
    &\Pr_{\substack{x\sim [X\mid \Psi(X)=u]\\ \theta \sim M(S \cup \set{x})\\
    x' \sim A(\theta)}}[d(x', x)\leq \rho]\\
    &~~~~= \E_{x\sim [X\mid \Psi(X)=u]}[M(S\cup \set{x})\in E_x ].
\end{align*}
let $\Sim$ be the simulator for feature $\Psi$ for which the feature DP is satisfied. By the definition of feature DP we have, 

$$\Pr[M(S\cup \set{x}) \in E_x] \leq 1-f\big(\Pr[\Sim(S, u)\in E_x]) \leq \rho]\big) .$$
Therefore using Jensen inequality and the definition of $\ball(\cdot)$ we have,
\begin{align*}&\E_{x\sim [X\mid \Psi(X)=u]}[M(S\cup \set{x}) \in E_x]\\
&~~~\leq 1- \E_{x\sim [X\mid \Psi(X)=u]}[f(\Pr[\Sim(\cS, u)\in E_x])]
\\
&~~~\leq 1- f(\E_{x\sim [X\mid \Psi(X)=u]}[\Pr[\Sim(\cS, u)\in E_x]])
\end{align*}
On the other hand we have
\begin{align*}&\E_{x\sim [X\mid \Psi(X)=u]}[\Pr[\Sim(\cS, u)\in E_x]]\\
&~~~= \E_{x\sim [X\mid \Psi(X)=u]}[\E_{\theta\sim A(\Sim(\cS, u))}[d(A(\theta),x)\leq \rho]]\\
&~~~=\E_{\theta\sim A(\Sim(\cS, u))}[\E_{x\sim [X\mid \Psi(X)=u]}[d(A(\theta),x)\leq \rho]]\\
&~~~\leq \E_{\theta\sim A(\Sim(\cS, u))}[\ball(X,u,d,\rho)]].\\
&~~~=\ball(X,u,d,\rho)
\end{align*}
\end{proof}

% \thmutility*
\begin{proof}[Proof of Theorem \ref{thm:utility}]First note that the gradient  $g_t$ is an unbiased estimate of the empirical gradient by linearity of expectation. We can also bound the expected $\ell_2$ norm of the gradient by $\tau'^2$ and the variance of the added noise by $d\sigma^2$. Therefore, applying the standard stochastic gradient oracle techniques (Theorems 2 and 3 in \citep{shamir2013stochastic}  for analyzing the convergence of SGD, we can bound the gap between the empirical risk of the optimal and the obtained model to be at most
\[(\frac{M^2}{c} + c\tau'^2 + cd\sigma^2)\frac{2+\log(T)}{\sqrt{T}}.\] in the case of convex loss functions (See Theorem 2 in \citep{shamir2013stochastic}). Similarly, for the $\lambda$- strongly convex losses, by using Theorem 3 in \citep{shamir2013stochastic} we can bound the excess empirical risk by

$$17(\tau'^2 + d\sigma^2)\frac{1+\log(T)}{\lambda T}.$$
\end{proof}

\begin{proof}[Proof of Theorem \ref{thm:privacy}]
Here we first analyze one step of the mechanism. Let us start with a lemma about feature-DP. For warm-up we first do the privacy analysis for the case of privacy with replacement, then we show how the privacy with insertion deletion follows similarly by defining a proper simulator. 
\begin{proposition}\label{propone}
Let $\Psi$ be a feature and $M_\lambda$ be a parameterized mechanism that is $f$ feature DP with respect $\Psi$, (\fDPr[f]), for all parameters $\lambda$. Also, let $M'_\lambda$ be an arbitrary parameterized mechanism that operates on $\Psi(\cS)$. Then, adaptive composition of $M$ and $M'$ in both orders ($MoM'$ and $M'oM$) is also $f$ feature DP (\fDPr[f]). Note that adaptive composition means that the parameter of $M$ (or $M'$) could be a function of the output of $M'$ (or $M$). 
\end{proposition}
\begin{proof} Let us use $\Lambda(\theta)$ to denote the parameter of $\theta$ that is passed to the parameterized mechanisms $M$ and $M'$. We have
\begin{align*}
\Pr[MoM'(\cS) \in S] &= \E_{\lambda \sim \Lambda(M'(\Psi(\cS))}\Pr[M_\lambda(\cS) \in S]\\&= \E_{\lambda \sim \Lambda(M'(\Psi(\cS'))}\Pr[M_\lambda(\cS) \in S]\\ &\leq 
\E_{\lambda \sim \Lambda(M'(\Psi(\cS'))}  [1-f(\Pr[M_\lambda(\cS') \in S)]\\
&\leq 1- f(\E_{\lambda \sim \Lambda(M'(\Psi(\cS'))}  [\Pr[M_\lambda(\cS') \in S])\\
&=1- f(  [\Pr[MoM'(\cS') \in S])
\end{align*}
Note that the last two lines follow by convexity of $f$.
Similarly, for the other direction we have,
\begin{align*}
\Pr[M'oM(\cS) \in S] &= \E_{\lambda \sim \Lambda(M(\cS))}\Pr[M'_\lambda(\Psi(\cS)) \in S]\\&= \E_{\lambda \sim \Lambda(M(\cS))}\Pr[M'_\lambda(\Psi(\cS')) \in S]\\ &\leq 1- f(\E_{\lambda \sim \Lambda(M(\cS'))}  \Pr[M'_\lambda(\Psi(\cS')) \in S])\\
&= 1-f(\Pr[M'oM(\cS') \in S]).
\end{align*}
\end{proof}
Note that in the Proposition above, it is crucial that $M$ and $M'$ do not share internal randomness. This is the main reason we cannot use the same batch for the public and private loss functions.
% We also state a proposition without proof about the connection between feature-DP and DP.

Now note that each iteration of the algorithm can be stated as $MoM'$ where $M'(\Psi(\cS))$ is the process of calculating $g_t^{pub}$, and $M(\cS)$ is a sub-sampled Gaussian mechanism that calculates $\frac{1}{m}\sum_{x\in D} \nabla \ell_{priv}(\mathbf{w}_t, x) + \mathcal{N}(g_t^{pub},\sigma^2).$
Therefore, each step of the algorithm is as private as of a sub-sampled Gaussian mechanism with sub-sampling rate $q=m/n$ and noise multiplier $\sigma/\tau$. So, using Propositions \ref{propone} and \ref{prop:DP_to_FDP} also applying the composition theorem \ref{thm:FDP_composition} we finish the proof. Additionally, by converting $f$-DP to DP we get that the mechanism is $(\epsilon,\delta)$-DP  for $\epsilon=c\frac{m\tau}{\sigma\cdot n} \sqrt{\log(\frac{1}{\delta}) \log(\frac{T}{\delta})}$ and  some constant $c$.

For the case of insertion/deletion, we need to design a simulator. Consider a simulator $sim$ that is defined by Algorithm \ref{alg:feature-DP-sim}. This algorithm takes the same inputs as of algorithm \ref{alg:feature-DP}, but it also takes an additional public feature value $u$. We have highlighted the only difference between the simulator and Algorithm $\ref{alg:feature-DP}$ in color red.

Now let $X_i$ be a random variable that corresponds to $g_i$ in algorithm \ref{alg:feature-DP-sim} and $Y_i$ be the the random variable that corresponds to $g_i$ in Algorithm \ref{alg:feature-DP}. By construction of the simulator, we know that $X_i$ and $Y_i$ are both mixture of Gaussian distributions $\cN(A_i, \sigma^2)$, $\cN(B_i, \sigma^2)$ where $B_i$ itself is a mixture of $A_i$ and $C_i=A_i+ \nabla \ell_{priv}(\mathbf{w}_t; x)$, with $B_i=(1-p)\cdot A_i + p \cdot C_i$. Therefore, the hockey-stick divergence between $X_i$ and $Y_i$ is bounded by that of $\cN(0, \sigma^2)$ and $(1-p)\cN(0, \sigma^2) + p\cN(0,\sigma^2)$ (See Theorem 4 in~\citep{balle2018privacy}). Therefore, for each step of the mechanism we have $T(X_i, Y_i)$ is dominated by $T\Big(\cN(0,\sigma^2), (1-p)\cN(0,\sigma^2) + p\cN(L, \sigma^2)\Big)$ and therefore by composition of trade-off functions (See Theorem 3.2 in \citep{dong2019gaussian}) for the entire mechanism we have 
$$T\Big((X_1,\dots, X_T),(Y_1,\dots, Y_T)\Big)$$ is dominated by $$f=T\Big(\cN(0,\sigma^2)^T , \big((1-p)\cN(0,\sigma^2) + p\cN(L, \sigma^2)\big)^T\Big).$$

This implies that for any event $\cT$, setting $X=(X_1,\dots, X_n)$ and $Y=(Y_1,\dots, Y_n)$ we have
$$\Pr[X \in \cT] \leq 1-f(\Pr[Y\in \cT]).$$
And this shows that the mechanism satisfies $f$-DP with respect to feature $\Psi$ for the function $f$ specified in Theorem \ref{thm:privacy}.





\begin{algorithm}
 %\vspace{-4pt}
\caption{Simulator for Noisy SGD with Public Features}\label{alg:feature-DP-sim}
\begin{algorithmic}[1]
\REQUIRE Public feature $\Psi$, Dataset $\cS$, Batch sizes $m$, $m'$, Learning rate schedule $\eta(t)$, standard deviation $\sigma$, Projection space $\mathcal{W} \in R^d$, Loss functions $\ell_{priv}, \ell_{pub}$, Number of iterations $T$, {\color{red} public feature value $u$}
\STATE Initialize $\mathbf{w}_1 \in \mathcal{W}$
\FOR{$t = 1, \dots, T$}
    \STATE Sample a mini-batch $B^{priv}_t$ with Poisson sampling with probability $p=m/|\cS|$. 
    \STATE $g^{priv}_{t}~=~\frac{1}{m}\sum_{x\in B_t^{priv}}\nabla \ell_{priv}(\mathbf{w}_t; x)$
    \STATE {\color{red} Construct a set $\cS''$ = $\cS \cup \set{x'}$ with $\Psi(x') = u$  }
    \STATE{\color{red} Sample a second mini-batch $B^{pub}_t$ of size $m'$ uniformly at random from $\cS''$.}

    \STATE $g_t^{pub}=~\frac{1}{m'}\sum_{x\in B_t^{pub}}\nabla \ell_{pub}(\mathbf{w}_t; \Psi(x)).$
    \STATE Let $g_t~=~g_t^{pub} + g_t^{priv} + \mathcal{N}(0, \sigma^2)$
    \STATE Update $\mathbf{w}_{t+1} = \mathbf{w}_t - \eta(t)\cdot g_t$
    \STATE Project $\mathbf{w}_{t+1}$ into the set $\mathcal{W}$: $\mathbf{w}_{t+1} = \text{Proj}_{\mathcal{W}}(\mathbf{w}_{t+1})$
\ENDFOR
\STATE \textbf{return} $\mathsf{aggregate}(\mathbf{w}_1,\dots,\mathbf{w}_{T+1})$
\end{algorithmic}
\end{algorithm}
\end{proof}


