\begin{proof}[Proof of Lemma~\ref{l:construction}\arxivonly{
(see more explicit proof of Lemma~\ref{l:construction} in the Addendum)
}]
If $m = 0$, then we set $A \ldots O := AO$ and $B \ldots C := BC$. 

Assume $m \neq 0$. Take $0 < \varepsilon_1 < \varepsilon_2 < |AO|$.
Denote $R := \{ p \in \mathbb{R}^2 : \varepsilon_1 \leqslant \rho(p, BO) \leqslant \varepsilon_2 \}$ (this is a subset of $\mathbb{R}^2$ homeomorphic to the annulus $S^1 \times D^1$). 
%The complement $\mathbb{R}^2 \setminus R$ has two connected components: an unbounded one $U$ and a bounded one $V$ (we have $\{ B, O\} \subset V$ and $\{ A, C \} \subset U$). 
Clearly, $\partial R$ splits the segment $AO$ into three segments. Denote them by $\gamma_1$, $\gamma_2$, $\gamma_3$ ordered and directed from $A$ to $O$ (see Figure~\ref{f:1}). Analogously, $\partial R$ splits the segment $BC$ into three segments. Denote them by $\lambda_1$, $\lambda_2$, $\lambda_3$ ordered and directed from $B$ to $C$.


Take disjoint simple polygonal lines (spirals) $s$, $s'$ inside $R$ so that

\begin{itemize}
    \item[(a)] $s$ joins the end of $\gamma_1$ to the origin of $\gamma_3$;
    \item[(b)] $s'$ joins the end of $\lambda_1$ to the origin of $\lambda_3$;
    \item[(c)] $s$ makes $|m|$ rotations counterclockwise/clockwise, if $m$ is positive/negative, around the segment~$BO$;
    \item[(d)] $s'$ makes $|m|$ rotations clockwise/counterclockwise, if $m$ is positive/negative, around the segment~$BO$.
\end{itemize}

The conditions (a), (b) imply that $s\gamma_2^{-1}$ and $s'\lambda_2^{-1}$ are closed polygonal lines. 
Since each point $A$ and $C$ can be separated from the set $R$ by a straight line, we have
\begin{equation}
    w(s\gamma_2^{-1}, C) = 0,
    \qquad
    \text{and}
    \qquad
    w(s'\lambda_2^{-1}, A) = 0.
\end{equation}

The conditions (c), (d) imply that
\begin{equation}
    w(s\gamma_2^{-1}, B) = m,
    \qquad
    \text{and}
    \qquad
    w(s'\lambda_2^{-1}, O) = -m.
\end{equation}

We set $A \ldots O := \gamma_1s\gamma_3$ and $B \ldots C := \lambda_1s'\lambda_3$. %Then connect $B$ and $C$ by a simple polygonal line $\Lambda_m$ disjoint with $\Gamma_m$.

Let us check the conditions from the formulation. 
We have
$$w'(B \ldots C, A) 
\overset{\text{(\ref{eq:add}, \ref{eq:inv})}}{=}
w'(\lambda_1\lambda_2\lambda_3, A) + w'(s'\lambda_2^{-1}, A) 
\overset{\text{(\ref{eq:conn})}}{=}
w'(BC, A) + w(s'\lambda_2^{-1}, A) \overset{(1)}{=} \frac{\angle BAC}{2\pi} = \frac{1}{6},$$

$$w'(A \ldots O, B) 
\overset{\text{(\ref{eq:add}, \ref{eq:inv})}}{=}
w'(\gamma_1\gamma_2\gamma_3, B) + w'(s\gamma_2^{-1}, B) 
\overset{\text{(\ref{eq:conn})}}{=}
w'(AO, B) + w(s\gamma_2^{-1}, B) 
\overset{(2)}{=} 
\frac{\angle ABO}{2\pi} + m =  -\frac{1}{12} + m,$$

$$w'(A \ldots O, C) 
\overset{\text{(\ref{eq:add}, \ref{eq:inv})}}{=}
w'(\gamma_1\gamma_2\gamma_3, C) + w'(s\gamma_2^{-1}, C) 
\overset{\text{(\ref{eq:conn})}}{=}
w'(AO, C) + w(s\gamma_2^{-1}, C) 
\overset{(1)}{=} 
\frac{\angle ACO}{2\pi} = \frac{1}{12},$$

$$w'(B \ldots C, O) 
\overset{\text{(\ref{eq:add}, \ref{eq:inv})}}{=}
w'(\lambda_1\lambda_2\lambda_3, O) + w'(s'\lambda_2^{-1}, O) 
\overset{\text{(\ref{eq:conn})}}{=}
w'(BC, O) + w(s'\lambda_2^{-1}, O) 
\overset{(2)}{=}  
\frac{\angle BOC}{2\pi} - m = \frac{1}{3} - m.$$
\end{proof}

