\subsubsection{Derive the Property Matrix $\mathbf D$}
Each layer is characterized by an associated property matrix $\mathbf{D}$ that describes how the field changes as it propagates through the layer along the $z$-axis. $\mathbf{D}$ for any layer is derived using the Maxwell-Faraday equation (Equation \ref{eqn:faraday_law}) and Ampère's law(Equation \ref{eqn:ampere_law}), which define the partial derivatives of the electric and magnetic fields along $z$.

Substituting the Equations \ref{eqn:inverseE} and \ref{eqn:inverseH} into the Equations \ref{eqn:faraday_law} and \ref{eqn:ampere_law} produces the following linear system within the layer:
\begin{equation}
\begin{bmatrix}
\frac{\partial \mathbf{P}_x}{\partial z} \\
\frac{\partial \mathbf{P}_y}{\partial z} \\
\frac{\partial \mathbf{B}_x}{\partial z} \\
\frac{\partial \mathbf{B}_y}{\partial z}
\end{bmatrix} = ik\mathbf D\begin{bmatrix}
\mathbf{P}_x\\ 
\mathbf{P}_y\\ 
\mathbf{B}_x\\
\mathbf{B}_y
\end{bmatrix} = ik\mathbf{D}\mathbf{R}
\label{eqn:Phi_system}
\end{equation}
where $\mathbf{R}$ is the vector of transverse component of the electric and magnetic fields. The unknown $M$-dimensional sub-vectors of $\mathbf{R}$ have the format:
\begin{equation}
    \mathbf{P}_x =
    \begin{bmatrix}
         p_x\left(\bar{\mathbf{s}}_0 \right)\\
         p_x\left(\bar{\mathbf{s}}_1 \right)\\
         \vdots\\
         p_x\left(\bar{\mathbf{s}}_{M-1} \right)
    \end{bmatrix}
\end{equation}
The property matrix $\mathbf D$ is a \textbf{known} $4M\times 4M$ matrix computed from the layer's material properties described in Equations \ref{eqn: epsilon} and \ref{eqn:inverse_n_fourier}:
\begin{equation}
    \mathbf{D}=
    \begin{bmatrix}
        \mathbf{0} & \mathbf{0} & \mathbf{s}_x\mathbf{s}_y^T\circ \bm \Psi & \mathbf{I} - \mathbf{s}_x\mathbf{s}_x^T\circ \bm \Psi\\
        \mathbf{0} & \mathbf{0} & \mathbf{s}_y\mathbf{s}_y^T\circ \bm \Psi - \mathbf{I} & - \mathbf{s}_y\mathbf{s}_x^T\circ \bm \Psi\\
        \mathbf{s}_x\mathbf{s}_y^T & \bm \Phi-\mathbf{s}_x\mathbf{s}_x^T & \mathbf{0} & \mathbf{0}\\
        \mathbf{s}_y\mathbf{s}_y^T - \bm \Phi & -\mathbf{s}_y\mathbf{s}_x^T & \mathbf{0} & \mathbf{0}
    \end{bmatrix}
    \label{eqn:matrix_D}
\end{equation}
The vectors $\mathbf s_x, \mathbf s_y \in \mathbb{R}^{M\times 1}$ are the spatial frequencies and $\circ$ is the Hadamard product.

The material properties for the layer are encoded in the matrices $\bm \Phi\in \mathbb C^{M\times M}$ and $\bm \Psi\in \mathbb C^{M\times M}$. The rows of $\bm \Phi$ and $\bm \Psi$ are the dynamic phase-shifted result of $\bm \phi$  (Equation \ref{eqn: epsilon}) and $\bm \psi$  (Equation \ref{eqn:inverse_n_fourier}), which represent convolution with the boundary field $\mathbf P$ using a circulant matrix:
\begin{equation*}
    \bm \Psi =
    \begin{bmatrix}
        \color{blue}{\psi_0}               & \psi_{M-1}           & \cdots               & \psi_{\lfloor{\frac{M}{2}}\rfloor}   & \cdots     & \psi_1\\
        \psi_1               & \color{blue}{\psi_0}             & \cdots               & \psi_{\lfloor{\frac{M}{2}}\rfloor+1} & \cdots     & \psi_2\\
        \vdots               & \vdots               & \ddots               & \vdots               & \ddots     & \vdots\\
        \psi_{\lfloor{\frac{M}{2}}\rfloor-1} & \psi_{\lfloor{\frac{M}{2}}\rfloor-2} & \cdots               & \psi_{M-1}           & \cdots     & \psi_{\lfloor{\frac{M}{2}}\rfloor}\\
        \psi_{\lfloor{\frac{M}{2}}\rfloor}   & \psi_{\lfloor{\frac{M}{2}}\rfloor-1} & \cdots               & \color{blue}{\psi_0}             & \cdots     & \psi_{\lfloor{\frac{M}{2}}\rfloor+1}\\
        \psi_{\lfloor{\frac{M}{2}}\rfloor+1} & \psi_{\lfloor{\frac{M}{2}}\rfloor}   & \cdots               & \psi_{1}             & \cdots     & \psi_{\lfloor{\frac{M}{2}}\rfloor+2}\\
        \vdots               & \vdots               & \ddots               & \vdots               & \ddots     & \vdots\\
        \psi_{M-1}           & \psi_{M-2}           & \cdots               & \psi_{\lfloor{\frac{M}{2}}\rfloor-1} & \cdots     & \color{blue}{\psi_0}
    \end{bmatrix}
\end{equation*}

\subsubsection{Eigendecomposition of $\mathbf D$}
The eigendecomposition for each $\mathbf D$ generates a list of $\Gamma$ and $\mathbf{Q}$, represented as 
$$\mathbf D= \mathbf Q\bm \Gamma\mathbf Q^{-1}$$
where $ \text{diag} \left(\bm\Gamma\right) = \left[\gamma_1, -\gamma_1, \gamma_2, -\gamma_2, \cdots, \gamma_{2M}, -\gamma_{2M}\right]^T$ and all $\gamma _i\geq 0$ and $\gamma_i \geq \gamma_{i+1}$. Positive eigenvalues correspond to the field propagating along the positive $z$-axis, while negative eigenvalues correspond to the reflected field within a layer.
%These components of $\mathbf{Q}$ is expressed as a set of row vectors:
%\begin{equation*}
%\mathbf{Q} = \left[\mathbf{q}_1, \mathbf{h}_1, ..., \mathbf{q}_{2M}, \mathbf{h}_{2M}\right]^T    
%\end{equation*}
% 

We use these terms to express the linear system in Equation \ref{eqn:Phi_system} as a set of linear equations:
\begin{equation}
    \frac{\partial\mathbf{R}}{\partial z} = ik\mathbf{Q}\bm\Gamma\mathbf{Q}^{-1}\mathbf{R}
\end{equation}
Solving this partial differential equation for $\mathbf{R}$ yields:
\begin{equation*}
    \mathbf{Q}^{-1}\frac{\partial\mathbf{R}}{\partial z} = ik\bm\Gamma\mathbf{Q}^{-1}\mathbf{R}
\end{equation*}
\begin{equation*}
    \frac{\partial\left(\mathbf{Q}^{-1}\mathbf{R}\right)}{\partial z} = ik\bm\Gamma\left(\mathbf{Q}^{-1}\mathbf{R}\right)
\end{equation*}
Since the vector differential equation $\frac{\partial\mathbf{a}}{\partial z} = \mathbf{a}$ has the solution $a_j=\alpha_je^z$, the resulting vector is composed of the scalar components:
\begin{equation*}
    \left[\mathbf{Q}^{-1}\mathbf{R}\right]_j=\alpha_j  \exp\left[ ik\Gamma_{jj}z \right]
\end{equation*}
Multiplying by $\mathbf{Q}$ provides the electromagnetic field:
\begin{equation}
   \mathbf{R} =  \mathbf{Q}\left[\text{\bf exp} \left( ik\bm\Gamma z\right)\right]\bm\alpha 
\label{eqn:field_in_layer}
\end{equation}
where {\bf exp} is an element-wise exponential function and $\bm \alpha \in \mathbb{C}^{4M}$ is a vector of unknown quantities resulting from the integration.

We then break $\mathbf Q$ into two matrices with columns corresponding to positive ($\check {\mathbf Q} \in \mathbb{C}^{4M\times 4M}$) and negative ($\hat {\mathbf Q} \in \mathbb{C}^{4M\times 4M}$) eigenvalues:
\begin{align*}
    \mathbf{Q} &= {\mathbf Q} \mathbf{I} = {\mathbf Q} \left( \check{\mathbf{I}} + \hat{\mathbf{I}} \right) = \check {\mathbf Q} + \hat {\mathbf Q}
\end{align*}
where $\check{\mathbf I}[2j,2j] = 1$ and $\hat{\mathbf I}[2j+1,2j+1] = 1$ for $j\in [0,2M-1]$.
