The Connection Equations are created by repeatedly substituting Equations \ref{eqn:upper_boundary} and \ref{eqn:middle_boundary} into Equation \ref{eqn:lower_boundary} to eliminate $\bm \alpha$. We define the following terms to simplify the expansion:
\begin{equation*}
    \Grave{\mathbf{Q}}_{\ell}=\mathbf{\check Q}^{(\ell)} + \mathbf{\hat Q}^{(\ell)}\mathbf{G}\left(\bm \Gamma^{(\ell)}, z_{\ell}, z_{\ell-1}\right)
\end{equation*}
\begin{equation*}
    \Acute{\mathbf{Q}}_{\ell}=\mathbf{\check Q}^{(\ell)}\mathbf{G}\left(\bm \Gamma^{(\ell)}, z_{\ell-1}, z_{\ell}\right) + \mathbf{\hat Q}^{(\ell)}
\end{equation*}
Equations \ref{eqn:upper_boundary} and \ref{eqn:middle_boundary} are re-written:
\begin{align*}
    \bar{\mathbf{G}}\bar{\mathbf{R}} + \hat{\mathbf{R}}= \Acute{\mathbf{Q}}_1\bm \alpha^{(1)} &\rightarrow \bm \alpha^{(1)} = \Acute{\mathbf{Q}}_1^{-1} \left[\bar{\mathbf{G}}\bar{\mathbf{R}} + \hat{\mathbf{R}} \right]\\
    \Grave{\mathbf{Q}}_{\ell-1}\bm\alpha^{(\ell-1)}  =\Acute{\mathbf{Q}}_{\ell}\bm\alpha^{(\ell)} &\rightarrow \bm\alpha^{(\ell)} = \Acute{\mathbf{Q}}_{\ell}^{-1}\Grave{\mathbf{Q}}_{\ell-1}\bm\alpha^{(\ell-1)}
\end{align*}
Finally, these equations are substituted into Equation \ref{eqn:lower_boundary} to create the expansion:
\begin{equation}
 \begin{aligned}
    \check{\mathbf{R}}&=\Grave{\mathbf{Q}}_L\bm\alpha^{(L)}\\
    \check{\mathbf{R}}&=\Grave{\mathbf{Q}}_L\Acute{\mathbf{Q}}_{L}^{-1}\Grave{\mathbf{Q}}_{L-1}\bm\alpha^{(L-1)}\\
    \check{\mathbf{R}}&=\Grave{\mathbf{Q}}_L\Acute{\mathbf{Q}}_{L}^{-1}\Grave{\mathbf{Q}}_{L-1}\cdots \Grave{\mathbf{Q}}_2\Acute{\mathbf{Q}}_{2}^{-1}\Grave{\mathbf{Q}}_{1}\bm\alpha^{(1)}\\
    \check{\mathbf{R}}&=\Grave{\mathbf{Q}}_L\Acute{\mathbf{Q}}_{L}^{-1}\Grave{\mathbf{Q}}_{L-1}\cdots \Grave{\mathbf{Q}}_2\Acute{\mathbf{Q}}_{2}^{-1}\Grave{\mathbf{Q}}_{1}\Acute{\mathbf{Q}}_1^{-1} \left[\bar{\mathbf{G}}\bar{\mathbf{R}} + \hat{\mathbf{R}} \right]
    \label{eqn:connection_R}
\end{aligned}   
\end{equation}

This linear system provides $4M$ constraints on the transverse components of the electromagnetic field $\mathbf{R}=\left[\mathbf{P}_x, \mathbf{P}_y, \mathbf{B}_x, \mathbf{B}_y\right]^T$. We are interested in the electric field $\mathbf{P}=\left[\mathbf{P}_x, \mathbf{P}_y, \mathbf{P}_z\right]^T$, which can be transformed into $\mathbf{R}$ using the matrix $\mathbf{C}\in\mathbb{C}^{4M\times3M}$:
\begin{equation}
    \mathbf{C}\mathbf{P} = \begin{bmatrix}
        \mathbf{I} & \mathbf{0} & \mathbf{0}\\
        \mathbf{0} & \mathbf{I} & \mathbf{0}\\
        \mathbf{0} & \text{diag}\left[-\hat{\mathbf{s}}_z \right] & \text{diag}\left[-\mathbf{s}_y\right]\\
        \text{diag}\left[\hat{\mathbf{s}}_z \right] & \mathbf{0} & -\mathbf{s}_x
    \end{bmatrix}
    \begin{bmatrix}
        \mathbf{P}_x\\
        \mathbf{P}_y\\
        \mathbf{P}_z
    \end{bmatrix}
    =   \mathbf{R}
\end{equation}

%\begin{equation}
%    \begin{aligned}
%        \check {\mathbf P}_x = \check {\mathbf Q}^{(L)}_{x} \hat {\mathbf Q}^{(L)}_x \check {\mathbf Q}^{(L-1)}_x \hdots \hat {\mathbf Q}^{(1)}_x ( \mathbf{A}_x\bar {\mathbf P}_x  + \hat {\mathbf P}_x)
%    \end{aligned}
%    \label{eqn:single_connection}
%\end{equation}
%where $\mathbf{A}_x$ \david{Define everything here.}

Substituting the $\mathbf{R}$s in Equation \ref{eqn:connection_R} with $\mathbf{C} \mathbf P$, we can get the final Connection Equations:
%\begin{equation*}  
%\begin{aligned}
%    \check {\mathbf P} = \check {\mathbf Q}_{L} \cdot \hat {\mathbf Q}_{L} \cdot \check {\mathbf Q}_{L-1} \hdots \hat {\mathbf Q}_{1} \cdot\mathbf ( \mathbf{A}\bar {\mathbf P}  + \hat {\mathbf P})
%\end{aligned}
%\end{equation*}
\begin{equation}
    \begin{aligned}
        \mathbf{C}\check{\mathbf{P}}&=\Grave{\mathbf{Q}}_L\Acute{\mathbf{Q}}_{L}^{-1}\Grave{\mathbf{Q}}_{L-1}\cdots \Grave{\mathbf{Q}}_2\Acute{\mathbf{Q}}_{2}^{-1}\Grave{\mathbf{Q}}_{1}\Acute{\mathbf{Q}}_1^{-1} \left[\bar{\mathbf{G}}\mathbf{C}\bar{\mathbf{P}} + \mathbf{C}\hat{\mathbf{P}} \right]\\
        \mathbf{C}\check{\mathbf{P}}&=\mathbf{K} \left[\bar{\mathbf{G}}\mathbf{C}\bar{\mathbf{P}} + \mathbf{C}\hat{\mathbf{P}} \right]\\
        \mathbf{C}\check{\mathbf{P}} - \mathbf{K}\mathbf{C}\hat{\mathbf{P}}&=\mathbf{K}\bar{\mathbf{G}}\mathbf{C}\bar{\mathbf{P}}\\
        %\mathbf{C}\check{\mathbf{P}}&=\check{\mathbf{Q}}_L\hat{\mathbf{Q}}_{L}^{-1}\check{\mathbf{Q}}_{L-1}\cdots \check{\mathbf{Q}}_2\hat{\mathbf{Q}}_{2}^{-1}\check{\mathbf{Q}}_{1}\hat{\mathbf{Q}}_1^{-1} \mathbf{C}\left[\bar{\mathbf{G}}\bar{\mathbf{P}} + \hat{\mathbf{P}} \right]
    \end{aligned}
    \label{eqn:connection_equations}
\end{equation}
 where $\check {\mathbf P}, \bar {\mathbf P}$ and $ \hat {\mathbf P} \in \mathbb{C}^{3M \times 1}$, $\grave {\mathbf Q}_{L}, \Acute {\mathbf Q}_{L}^{-1}, \hdots, \Acute {\mathbf Q}_{1}^{-1}=\mathbf{K} \in \mathbb{C}^{4M \times 4M}$. 

 This system of linear equations resolves the final set of constraints used to solve for the external fields $\hat{\mathbf{P}}$ and $\check{\mathbf{P}}$ (Figure \ref {fig:linear_functions_Hete}).

\subsection{Calculate the Scattered Field}

\subsubsection{Outside of the Sample}
The electric field outside of the sample is calculated directly from Equations \ref{eqn:P} and \ref{eqn:e_from_p} for any spatial coordinate $(r_x, r_y, z)$, where $z$ is outside of the sample ($z \leq z_0$ or $z_L \leq z$).
