%     \end{cases}
% \end{equation}

\subsubsection{Inside the Sample}
The interior sample field depends on the $\bm{\alpha}$ values associated with the corresponding layer. If $z_{\ell-1} \leq z \leq z_{\ell}$, then the coordinate is inside layer $\ell$ and requires $\bm{\alpha}^{(\ell)}$. This can be directly calculated from Equation \ref{eqn:middle_boundary} by solving the linear system based on $\bm \alpha$ values from two adjacent layers. Therefore, calculating the internal field at an arbitrary point requires solving all $L$ $\bm\alpha$ vectors as a pre-processing step. The associated plane waves within the layer are calculated from Equation \ref{eqn:field_in_layer} and \ref{eqn:P}:
\begin{equation}
    \mathbf{R}^{(\ell)}(z) =  \left[\mathbf{\check Q}^{(\ell)}\mathbf{G}\left(\bm {\Gamma}^{(\ell)}, z_{\ell-1}, z\right) +\mathbf{\hat Q}^{(\ell)}\mathbf{G}\left(\bm {\Gamma}^{(\ell)}, z_{\ell}, z\right)\right]\bm \alpha^{(\ell)}
    \label{eqn:InsideField}
\end{equation}
The two propagation matrices are the only terms dependent on the spatial coordinate, so to avoid confusion with their coordinates we will redefine them:
\begin{align*}
    \check{\mathbf{G}}^{(\ell)}(z) &= \mathbf{G}\left(\bm {\Gamma}^{(\ell)}, z_{\ell-1}, z\right)\\
    \hat{\mathbf{G}}^{(\ell)}(z) &= \mathbf{G}\left(\bm {\Gamma}^{(\ell)}, z_{\ell}, z\right)
\end{align*}
The plane waves associated with the field at any $z$ coordinate within the sample requires the terms associated with the corresponding layer $\ell$, where $z_{\ell-1} \leq z \leq z_{\ell}$. Within a single layer $\ell$, Equation \ref{eqn:InsideField} is:
\begin{equation}
    \mathbf{R}(z) =  \left[\mathbf{\check Q}\check{\mathbf{G}}(z) +\mathbf{\hat Q}\hat{\mathbf{G}}(z)\right] \bm \alpha
    \label{eqn:layer_R_vector}
\end{equation}


The $x$ and $y$ components of $\mathbf{E}$ are given by $\mathbf{P}_x$ and $\mathbf{P}_y$ directly in $\mathbf{R}$. The $z$ component is calculated from the Fourier coefficients of the magnetic field $\mathbf{B}_x$ and $\mathbf{B}_y$ also stored in $\mathbf{R}$. 

Using Ampere's law (Equation \ref{eqn:ampere_law}) we express the $z$ component of the electric field in terms of the magnetic field:
\begin{equation}
 \left[\mathbf{E}(\mathbf{r})\right]_z=-\frac{1}{i k n^2(\mathbf{r})} \sqrt{\frac{\mu_0}{\varepsilon_0}}\left[\nabla \times \mathbf{H}(\mathbf{r})\right]_z
\label{eqn:electric_z}
\end{equation}
Note that the $z$ component of the curl operator depends only on the $x$ and $y$ components of the magnetic field:
\begin{equation*}
    \left[\nabla \times \mathbf{H}(\mathbf{r})\right]_z = \frac{\partial}{\partial y}H_x - \frac{\partial}{\partial x}H_y
\end{equation*}
Since we have the $x$ and $y$ components of the magnetic field expressed as a Fourier series:
\begin{equation*}
    \left[\mathbf{H}(\mathbf{r})\right]_{xy} =\sqrt{\frac{\varepsilon_0}{\mu_0}} \sum_{m=0}^{M-1} 
    \left[\mathbf{B}_m\right]_{xy}
    \exp \left(ik
    \bar{\mathbf{s}}_m \cdot     \bar{\mathbf{r}}
    \right)
\end{equation*}
calculating the derivatives yeilds:
\begin{equation*}
    \begin{bmatrix}
        \frac{\partial}{\partial x} H_y(\bar{\mathbf{r}})\\
        \frac{\partial}{\partial y} H_x(\bar{\mathbf{r}})
    \end{bmatrix}
    = ik\sqrt{\frac{\varepsilon_0}{\mu_0}} \sum_{m=0}^{M-1}
    \bar{\mathbf{s}}_m \circ 
    \begin{bmatrix}
        b_{y}\\
        b_{x}
    \end{bmatrix}_m
    \exp \left(ik
    \bar{\mathbf{s}}_m \cdot \bar{\mathbf{r}}
    \right)
\end{equation*}
Using these terms in Equation \ref{eqn:electric_z} provides the $z$ component of the electric field in known terms in $\mathbf{R}$ (Equation \ref{eqn:InsideField}):
\begin{equation*}
    E_z(\bar{\mathbf{r}})=\frac{-1}{i k n^2(\bar{\mathbf{r}})} \sqrt{\frac{\mu_0}{\varepsilon_0}}\left[-\frac{\partial}{\partial x}H_y(\bar{\mathbf{r}}) + \frac{\partial}{\partial y}H_x(\bar{\mathbf{r}})\right]
\end{equation*}
Substituting in the plane wave decomposition for the derivatives allows us to eliminate the common constants:
\begin{equation*}
    E_z(\bar{\mathbf{r}})= 
    \left[ \frac{-1}{n^2(\bar{\mathbf{r}})} \right]
    \left[ \sum_{m=0}^{M-1}
    \bar{\mathbf{s}}_m \circ 
    \begin{bmatrix}
        b_{y}\\
        b_{x}
    \end{bmatrix}_m
    \exp \left(ik
    \bar{\mathbf{s}}_m \cdot \bar{\mathbf{r}}
    \right) \right]^T
    \begin{bmatrix}
        -1\\
        1
    \end{bmatrix}
\end{equation*}
Replacing the inverse squared refractive index of the sample with its know Fourier decomposition (Equation \ref{eqn:inverse_n_fourier}):
\begin{multline*}
    E_z(\bar{\mathbf{r}})=
     \left[ -\sum_{m=0}^{M-1}\psi_m \exp \left(ik
    \bar{\mathbf{s}}_m \cdot \bar{\mathbf{r}}
    \right)  \right] \times \\
     \left[ \sum_{m=0}^{M-1}
    \bar{\mathbf{s}}_m \circ 
    \begin{bmatrix}
        b_y\\
        b_x
    \end{bmatrix}_m
    \exp \left(ik
    \bar{\mathbf{s}}_m \cdot \bar{\mathbf{r}}
    \right) \right]^T
    \begin{bmatrix}
        -1\\
        1
    \end{bmatrix}
\end{multline*}
%\begin{equation*}
%    \left[\nabla \times \mathbf{H}(\mathbf{r})\right]_z = -\frac{\partial}{\partial x}H_y + \frac{\partial}{\partial y}H_x \\ \xrightarrow{\mathscr{F}} ik\sqrt{\frac{\varepsilon_0}{\mu_0}} 
%\begin{bmatrix}
%    -\bar {\mathbf s}_x(\mathbf m)B_y(\mathbf m)\\
%    \bar {\mathbf s}_y(\mathbf m)B_x(\mathbf m)
%\end{bmatrix}
%\end{equation*}
shows that $E_z$ is the product of two Fourier transforms:
\begin{equation*}
    E_z(\bar{\mathbf{r}}) =\mathscr{F}^{-1}\left[ -\bm{\psi} \right]\times
    \left[ \sum_{m=0}^{M-1}
    \bar{\mathbf{s}}_m \circ 
    \begin{bmatrix}
        b_y\\
        b_x
    \end{bmatrix}_m
    \exp \left(ik
