    \end{bmatrix}
\end{equation*}
By the convolution theorem, the $z$ component of a plane wave oriented along $\mathbf{s}_m$ is:
\begin{equation*}
    \left[p_z\right](\bar{\mathbf{s}}_m) 
        = -\bm{\psi}_m \ast \left\{\bar{\mathbf{s}}_m \cdot
\begin{bmatrix}
    b_{y}\\
    -b_{x}
\end{bmatrix}_m\right\}
    \label{eqn:convolution}
\end{equation*}
